page.css:
:root{
  /* Brand palette v5, sampled from the approved logo: blue #0088C0, teal #00A890, grey #888888 */
  --blue:#0088C0; --blue-600:#0A78AC; --blue-700:#0A6E9C; --blue-800:#0A587F; --deep:#0A3A52;
  --navy:#0A3A52; --navy-800:#0A3A52; --ink:#12303F; --grey:#888888;
  --teal:#00A890; --teal-600:#0A8E7C; --teal-700:#0A7E6E; --teal-800:#0A6357; --teal-100:#D6EFEA;
  --amber:#0A6E9C; --amber-700:#0A6E9C; --amber-100:#E6F3FB; --hl:#86E6D8;
  --cream:#F3F7F9; --mist:#E7F4F1; --sky:#E6F3FB; --slate:#EEF5F9; --line:#D3E4EC;
  --body:#33474F; --muted:#5F7178; --white:#ffffff;
  --maxw:1180px; --radius:16px; --radius-sm:10px;
  --shadow:0 18px 44px -20px rgba(10,58,82,.42); --shadow-sm:0 8px 22px -14px rgba(10,58,82,.4);
  --font-body:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --font-display:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font-body);color:var(--body);background:var(--white);
  font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3,h4{font-family:var(--font-display);color:var(--ink);line-height:1.14;margin:0 0 .5em;font-weight:800;letter-spacing:-.02em}
h2{font-size:clamp(1.7rem,3.6vw,2.5rem)}
h3{font-size:1.26rem;font-weight:700;letter-spacing:-.01em}
p{margin:0 0 1rem}
a{color:var(--teal-700);text-decoration-thickness:1px;text-underline-offset:2px}
a:hover{color:var(--teal-800)}
.vh{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.hero__sub a{color:#fff;text-decoration:underline;text-underline-offset:3px;font-weight:600}
.hero__sub a:hover{color:var(--hl)}
img{max-width:100%;display:block}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 22px}
.section{padding:76px 0}
.section--tight{padding:56px 0}
.eyebrow{display:inline-flex;align-items:center;gap:.5rem;font-weight:700;font-size:.78rem;
  letter-spacing:.14em;text-transform:uppercase;color:var(--teal-700);margin:0 0 .9rem}
.eyebrow::before{content:"";width:26px;height:2px;background:var(--amber);border-radius:2px}
.lead{font-size:1.12rem;color:var(--body);max-width:60ch}
.center{text-align:center}
.center .lead{margin-left:auto;margin-right:auto}

/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.55rem;font-weight:700;
  font-size:1rem;padding:.92rem 1.5rem;border-radius:999px;border:2px solid transparent;cursor:pointer;
  text-decoration:none;transition:transform .15s ease,background .2s ease,box-shadow .2s ease;line-height:1}
.btn:hover{transform:translateY(-2px)}
.btn--primary{background:var(--teal-700);color:#fff;box-shadow:var(--shadow-sm)}
.btn--primary:hover{background:var(--teal-800);color:#fff}
.btn--light{background:var(--cream);color:var(--navy)}
.btn--light:hover{background:#fff;color:var(--navy)}
.btn--ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn--ghost:hover{background:rgba(255,255,255,.12);color:#fff}
.btn--outline{background:transparent;color:var(--teal-700);border-color:var(--teal-700)}
.btn--outline:hover{background:var(--mist);color:var(--teal-800)}

.skip{position:absolute;left:-999px;top:0;background:var(--navy);color:#fff;padding:.7rem 1.1rem;z-index:200;border-radius:0 0 8px 0}
.skip:focus{left:0;color:#fff}

/* Utility bar */
.util{background:var(--navy);color:#cddbe8;font-size:.86rem}
.util .wrap{display:flex;flex-wrap:wrap;gap:.4rem 1.4rem;align-items:center;justify-content:space-between;padding-top:.5rem;padding-bottom:.5rem}
.util a{color:#e7eef6;text-decoration:none}
.util a:hover{color:#fff}
.util .util__group{display:flex;flex-wrap:wrap;gap:.3rem 1.3rem;align-items:center}
.util i{color:var(--hl);margin-right:.4rem}
.util__reg{font-weight:700;color:#fff}

/* Header */
.site-header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.93);backdrop-filter:saturate(1.4) blur(8px);
  border-bottom:1px solid var(--line)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding-top:.55rem;padding-bottom:.55rem}
.brand{display:inline-flex;align-items:center;text-decoration:none}
.brand img{height:56px;width:auto;max-width:210px;object-fit:contain;display:block}
.nav{display:flex;align-items:center;gap:.35rem}
.nav a{color:var(--ink);text-decoration:none;font-weight:600;font-size:.97rem;padding:.5rem .7rem;border-radius:8px}
.nav a:hover{background:var(--mist);color:var(--teal-800)}
.nav__has{position:relative}
.nav__panel{position:absolute;top:calc(100% + 6px);left:0;background:#fff;border:1px solid var(--line);border-radius:12px;
  box-shadow:var(--shadow);padding:.5rem;min-width:255px;display:none;z-index:20}
.nav__has:hover .nav__panel,.nav__has:focus-within .nav__panel{display:block}
.nav__panel a{display:block;padding:.55rem .7rem;font-size:.92rem}
.header__cta{display:flex;align-items:center;gap:.6rem}
.header__phone{display:inline-flex;align-items:center;gap:.45rem;font-weight:700;color:var(--navy);text-decoration:none;font-size:.95rem}
.header__phone i{color:var(--teal-700)}
.burger{display:none;background:var(--mist);border:1px solid var(--line);border-radius:10px;width:46px;height:46px;font-size:1.2rem;color:var(--navy);cursor:pointer}

/* Hero */
.hero{position:relative;color:#e9f3f1;background:linear-gradient(120deg,#0A3A52 0%,#0A6E9C 46%,#00A890 120%);overflow:hidden}
.hero::after{content:"";position:absolute;right:-8%;top:-30%;width:520px;height:520px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,rgba(0,168,144,.30),rgba(0,168,144,0) 62%);pointer-events:none}
.hero .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1.08fr .92fr;gap:48px;align-items:center;padding-top:70px;padding-bottom:78px}
.hero__eyebrow{color:var(--hl)}
.hero h1{color:#fff;font-size:clamp(2.15rem,5vw,3.4rem);font-weight:800;margin-bottom:.4em;letter-spacing:-.025em}
.hero h1 .hl{color:var(--hl)}
.hero__sub{font-size:1.15rem;color:#dcebe8;max-width:52ch;margin-bottom:1.5rem}
.hero__cta{display:flex;flex-wrap:wrap;gap:.8rem;margin-bottom:1.6rem}
.hero__chips{display:flex;flex-wrap:wrap;gap:.5rem}
.chip{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.22);
  border-radius:999px;padding:.42rem .8rem;font-size:.82rem;font-weight:600;color:#eef7f4}
.chip i{color:var(--hl)}

.hero__media{position:relative}
.hero__ph{position:relative;border-radius:22px;overflow:hidden;box-shadow:0 30px 60px -28px rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.2)}
.ph{position:relative;background:
    repeating-linear-gradient(45deg,rgba(255,255,255,.05) 0 12px,rgba(255,255,255,.09) 12px 24px),
    linear-gradient(135deg,#0A78AC,#0A7E6E);
  color:#eafaf6;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:.45rem;padding:22px}
.ph--light{background:
    repeating-linear-gradient(45deg,rgba(11,36,64,.05) 0 12px,rgba(11,36,64,.09) 12px 24px),
    linear-gradient(135deg,#E6F3FB,#E7F4F1);color:var(--teal-800)}
.ph i.ph__ico{font-size:1.9rem;opacity:.9}
.ph__label{font-weight:700;font-size:.82rem;letter-spacing:.08em;text-transform:uppercase}
.ph__meta{font-size:.75rem;opacity:.9;max-width:36ch;line-height:1.4}
.hero__ph .ph{aspect-ratio:4/3}
.matchcard{position:absolute;left:-18px;bottom:-22px;background:#fff;color:var(--ink);border-radius:16px;
  box-shadow:var(--shadow);padding:14px 16px;width:min(300px,78%);border:1px solid var(--line)}
.matchcard .mc-title{font-size:.8rem;text-transform:uppercase;letter-spacing:.1em;color:var(--teal-700);margin:0 0 .55rem;font-weight:800}
.matchcard ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:.5rem}
.matchcard li{display:flex;align-items:center;gap:.5rem;font-size:.86rem;font-weight:600;color:var(--body)}
.matchcard li i{width:26px;height:26px;display:grid;place-items:center;border-radius:8px;background:var(--mist);color:var(--teal-700);font-size:.8rem}

/* Trust bar */
.trustbar{background:var(--cream);border-bottom:1px solid var(--line)}
.trustbar .grid{display:grid;grid-template-columns:repeat(5,1fr);gap:18px}
.trust{display:flex;gap:.7rem;align-items:flex-start}
.trust i{flex:none;width:40px;height:40px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.05rem}
.trust b{display:block;color:var(--ink);font-size:.95rem;line-height:1.25}
.trust span{font-size:.83rem;color:var(--muted)}

/* Services */
.svc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:36px}
.svc{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px;box-shadow:var(--shadow-sm);transition:transform .18s ease,box-shadow .2s ease;overflow:hidden}
.svc::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:linear-gradient(var(--blue),var(--teal))}
.svc:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.svc__ico{width:52px;height:52px;display:grid;place-items:center;border-radius:13px;background:var(--mist);color:var(--teal-700);font-size:1.3rem;margin-bottom:14px}
.svc h3{margin-bottom:.4rem}
.svc p{font-size:.96rem;margin-bottom:1rem}
.svc a.svc__link{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}
.svc a.svc__link i{transition:transform .15s ease}
.svc a.svc__link:hover i{transform:translateX(3px)}
.svc-more{margin-top:22px;display:flex;flex-wrap:wrap;gap:.6rem 1.1rem;align-items:center;font-size:.95rem}
.svc-more span{font-weight:700;color:var(--ink)}
.callout{margin-top:26px;display:flex;gap:18px;align-items:center;flex-wrap:wrap;justify-content:space-between;
  background:linear-gradient(120deg,#0A3A52,#0A7E6E);color:#e9f3f1;border-radius:var(--radius);padding:24px 26px;
  border:1px solid rgba(255,255,255,.14);box-shadow:var(--shadow-sm);position:relative;overflow:hidden}
.callout::after{content:"";position:absolute;right:-40px;top:-40px;width:180px;height:180px;border-radius:50%;
  background:radial-gradient(circle,rgba(0,168,144,.32),transparent 65%)}
.callout .callout__t{position:relative;z-index:2;max-width:64ch}
.callout h3{color:#fff;margin-bottom:.25rem}
.callout p{margin:0;color:#d7e6e2;font-size:.96rem}
.callout .btn{position:relative;z-index:2}

/* Matching */
.matching{background:var(--navy);color:#e3eef1;position:relative;overflow:hidden}
.matching::before{content:"";position:absolute;inset:0;background:radial-gradient(1000px 420px at 82% -10%,rgba(0,168,144,.34),transparent 60%);pointer-events:none}
.matching .wrap{position:relative;z-index:2;display:grid;grid-template-columns:.95fr 1.05fr;gap:46px;align-items:center}
.matching h2{color:#fff}
.matching .eyebrow{color:var(--hl)}
.matching .lead{color:#c6d7db}
.match-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.match{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:14px;padding:18px}
.match i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:rgba(134,230,216,.16);color:var(--hl);font-size:1.1rem;margin-bottom:10px}
.match b{display:block;color:#fff;font-size:1rem;margin-bottom:.2rem}
.match span{font-size:.88rem;color:#bfd3d7}

/* Steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:40px;counter-reset:step}
.step{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px 22px;box-shadow:var(--shadow-sm)}
.step__n{counter-increment:step;width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:var(--amber-100);color:var(--amber-700);font-size:1.3rem;font-weight:800;margin-bottom:14px}
.step__n::before{content:counter(step)}
.step h3{font-size:1.1rem;margin-bottom:.35rem}
.step p{font-size:.92rem;margin:0}
.pill-note{margin-top:26px;display:inline-flex;align-items:center;gap:.6rem;background:var(--mist);border:1px solid var(--line);border-radius:999px;padding:.6rem 1.1rem;font-weight:600;color:var(--teal-800);font-size:.95rem}
.pill-note i{color:var(--teal-700)}

/* Coverage */
.coverage{background:var(--slate)}
.cov-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:34px}
.cov{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:28px;box-shadow:var(--shadow-sm)}
.cov__head{display:flex;align-items:center;gap:.7rem;margin-bottom:.4rem}
.cov__head i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.1rem}
.cov__head h3{margin:0}
.cov__head span{font-size:.82rem;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.08em}
.cov ul{list-style:none;padding:0;margin:.7rem 0 1rem;display:flex;flex-wrap:wrap;gap:.5rem}
.cov li{background:var(--mist);border:1px solid var(--line);border-radius:999px;font-size:.85rem;font-weight:600;color:var(--teal-800);overflow:hidden;transition:background .15s ease,border-color .15s ease}
.cov li:hover{background:var(--teal-100);border-color:var(--teal-700)}
.cov li a{display:block;padding:.32rem .75rem;color:var(--teal-800);text-decoration:none}
.cov a{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}

/* Reviews */
.rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:34px}
.rev{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm);position:relative}
.rev .quo{font-size:1.6rem;color:var(--teal);opacity:.5}
.rev p{color:var(--muted);font-size:.95rem;font-style:italic}
.rev .rev__ph{display:flex;align-items:center;gap:.7rem;margin-top:14px;border-top:1px dashed var(--line);padding-top:14px}
.rev .rev__av{width:42px;height:42px;border-radius:50%;background:var(--mist);display:grid;place-items:center;color:var(--teal-700)}
.rev .rev__meta b{display:block;color:var(--ink);font-size:.9rem}
.rev .rev__meta span{font-size:.78rem;color:var(--muted)}
.rev-note{margin-top:22px;text-align:center;font-size:.92rem;color:var(--muted)}

/* Why */
.why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:36px}
.why{display:flex;gap:.9rem;align-items:flex-start;background:var(--cream);border:1px solid var(--line);border-radius:14px;padding:22px}
.why i{flex:none;width:46px;height:46px;display:grid;place-items:center;border-radius:12px;background:var(--teal-700);color:#fff;font-size:1.1rem}
.why b{display:block;color:var(--ink);font-size:1.02rem;margin-bottom:.2rem}
.why span{font-size:.9rem;color:var(--muted)}

/* FAQ */
.faq{max-width:820px;margin:34px auto 0}
.qa{border:1px solid var(--line);border-radius:12px;margin-bottom:12px;background:#fff;overflow:hidden}
.qa__q{width:100%;text-align:left;background:none;border:0;padding:18px 20px;font-family:var(--font-body);font-weight:700;font-size:1.03rem;color:var(--ink);display:flex;justify-content:space-between;align-items:center;gap:1rem;cursor:pointer}
.qa__q i{color:var(--teal-700);transition:transform .2s ease;flex:none}
.qa__q[aria-expanded="true"] i{transform:rotate(45deg)}
.qa__a{padding:0 20px;max-height:0;overflow:hidden;transition:max-height .25s ease,padding .25s ease}
.qa__a p{margin:0 0 16px}
.qa__q[aria-expanded="true"]+.qa__a{padding:2px 20px 4px}

/* CTA + form */
.cta{background:linear-gradient(135deg,#0A3A52 0%,#0A6E9C 50%,#00A890 130%);color:#e9f3f1;position:relative;overflow:hidden}
.cta::after{content:"";position:absolute;left:-6%;bottom:-40%;width:460px;height:460px;border-radius:50%;background:radial-gradient(circle,rgba(0,168,144,.24),transparent 62%);pointer-events:none}
.cta .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
.cta h2{color:#fff}
.cta .eyebrow{color:var(--hl)}
.cta__points{list-style:none;padding:0;margin:1.2rem 0 0;display:grid;gap:.6rem}
.cta__points li{display:flex;gap:.6rem;align-items:flex-start;color:#d7e6e2;font-size:.98rem}
.cta__points i{color:var(--hl);margin-top:.2rem}
.cta__calls{display:flex;flex-wrap:wrap;gap:.7rem;margin-top:1.4rem}
.callbtn{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.24);color:#fff;text-decoration:none;border-radius:12px;padding:.7rem 1rem;font-weight:700;font-size:.95rem}
.callbtn i{color:var(--hl)}
.callbtn:hover{background:rgba(255,255,255,.18);color:#fff}
.form{background:#fff;border-radius:20px;padding:26px;box-shadow:var(--shadow);color:var(--body)}
.form h3{color:var(--ink)}
.form .fnote{font-size:.86rem;color:var(--muted);margin-bottom:1.1rem}
.field{margin-bottom:14px}
.field label{display:block;font-weight:700;font-size:.88rem;color:var(--ink);margin-bottom:.35rem}
.field input,.field select,.field textarea{width:100%;padding:.72rem .85rem;border:1.5px solid var(--line);border-radius:10px;font-family:inherit;font-size:.97rem;color:var(--ink);background:#fff}
.field input:focus,.field select:focus,.field textarea:focus{outline:3px solid rgba(14,159,142,.30);border-color:var(--teal-700)}
.field textarea{min-height:92px;resize:vertical}
.field .req{color:#b23b3b}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.form .consent{font-size:.8rem;color:var(--muted);margin:.4rem 0 1rem}
.form__msg{display:none;background:var(--sky);border:1px solid var(--blue);color:var(--deep);border-radius:10px;padding:.8rem 1rem;font-size:.9rem;font-weight:600;margin-bottom:1rem}
.form__msg.show{display:block}

/* Footer */
.footer{background:var(--navy);color:#c4d3df;font-size:.94rem}
.footer a{color:#dbe6f0;text-decoration:none}
.footer a:hover{color:#fff}
.footer__top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.2fr;gap:34px;padding:58px 0 34px}
.footer__logo{display:inline-block;background:#fff;border-radius:12px;padding:10px 14px;margin-bottom:1rem}
.footer__logo img{height:44px;width:auto;max-width:170px;object-fit:contain;display:block}
.footer p{color:#b6c7d4;font-size:.92rem}
.footer h4{color:#fff;font-size:.82rem;letter-spacing:.12em;text-transform:uppercase;margin:0 0 1rem;font-weight:800}
.footer ul{list-style:none;padding:0;margin:0;display:grid;gap:.55rem}
.footer .nap li{display:flex;gap:.6rem;align-items:flex-start;margin-bottom:.55rem}
.footer .nap i{color:var(--hl);width:18px;margin-top:.2rem;flex:none}
.footer__socials{display:flex;gap:.55rem;margin-top:1rem}
.footer__socials a{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:rgba(255,255,255,.08);color:#e7eef6}
.footer__socials a:hover{background:var(--teal-700);color:#fff}
.footer__bottom{border-top:1px solid rgba(255,255,255,.12);padding:18px 0;display:flex;flex-wrap:wrap;gap:.6rem 1.4rem;align-items:center;justify-content:space-between;font-size:.85rem;color:#9fb4c4}
.footer__bottom a{color:#c4d3df}
.footer__legal{display:flex;flex-wrap:wrap;gap:.4rem 1.2rem}

/* Mobile call bar */
.mcall{position:fixed;left:0;right:0;bottom:0;z-index:90;display:none;grid-template-columns:1fr 1fr;background:#fff;border-top:1px solid var(--line);box-shadow:0 -8px 24px -14px rgba(11,36,64,.5)}
.mcall a{display:flex;align-items:center;justify-content:center;gap:.5rem;padding:.9rem;font-weight:800;text-decoration:none;font-size:.95rem}
.mcall a.call{color:var(--navy)}
.mcall a.enq{background:var(--teal-700);color:#fff}

/* Responsive */
@media (max-width:960px){
  .hero .wrap,.matching .wrap,.cta .wrap{grid-template-columns:1fr;gap:34px}
  .hero__media{max-width:520px}
  .trustbar .grid{grid-template-columns:repeat(2,1fr)}
  .steps{grid-template-columns:1fr 1fr}
  .why-grid,.rev-grid{grid-template-columns:1fr 1fr}
  .footer__top{grid-template-columns:1fr 1fr}
  .nav,.header__phone{display:none}
  .burger{display:inline-flex;align-items:center;justify-content:center}
  .mcall{display:grid}
  body{padding-bottom:56px}
}
@media (max-width:620px){
  .section{padding:56px 0}
  .svc-grid,.match-grid,.cov-grid,.why-grid,.rev-grid,.steps,.trustbar .grid{grid-template-columns:1fr}
  .matchcard{position:static;width:100%;margin-top:14px}
  .util .wrap{justify-content:flex-start}
  .footer__top{grid-template-columns:1fr}
  h2{font-size:1.6rem}
}
.mnav{position:fixed;inset:0;z-index:120;background:rgba(6,18,32,.55);display:none}
.mnav.open{display:block}
.mnav__panel{position:absolute;top:0;right:0;height:100%;width:min(330px,86vw);background:#fff;padding:20px;overflow-y:auto;box-shadow:var(--shadow)}
.mnav__panel a{display:block;padding:.8rem .4rem;border-bottom:1px solid var(--line);color:var(--ink);text-decoration:none;font-weight:700}
.mnav__panel a.sub{padding-left:1.3rem;font-weight:600;font-size:.94rem;color:var(--body)}
.mnav__close{background:var(--mist);border:0;border-radius:10px;width:44px;height:44px;font-size:1.1rem;float:right;margin-bottom:.5rem;cursor:pointer;color:var(--navy)}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}

:root{
  /* Brand palette v5, sampled from the approved logo: blue #0088C0, teal #00A890, grey #888888 */
  --blue:#0088C0; --blue-600:#0A78AC; --blue-700:#0A6E9C; --blue-800:#0A587F; --deep:#0A3A52;
  --navy:#0A3A52; --navy-800:#0A3A52; --ink:#12303F; --grey:#888888;
  --teal:#00A890; --teal-600:#0A8E7C; --teal-700:#0A7E6E; --teal-800:#0A6357; --teal-100:#D6EFEA;
  --amber:#0A6E9C; --amber-700:#0A6E9C; --amber-100:#E6F3FB; --hl:#86E6D8;
  --cream:#F3F7F9; --mist:#E7F4F1; --sky:#E6F3FB; --slate:#EEF5F9; --line:#D3E4EC;
  --body:#33474F; --muted:#5F7178; --white:#ffffff;
  --maxw:1180px; --radius:16px; --radius-sm:10px;
  --shadow:0 18px 44px -20px rgba(10,58,82,.42); --shadow-sm:0 8px 22px -14px rgba(10,58,82,.4);
  --font-body:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --font-display:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font-body);color:var(--body);background:var(--white);
  font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3,h4{font-family:var(--font-display);color:var(--ink);line-height:1.14;margin:0 0 .5em;font-weight:800;letter-spacing:-.02em}
h2{font-size:clamp(1.7rem,3.6vw,2.5rem)}
h3{font-size:1.26rem;font-weight:700;letter-spacing:-.01em}
p{margin:0 0 1rem}
a{color:var(--teal-700);text-decoration-thickness:1px;text-underline-offset:2px}
a:hover{color:var(--teal-800)}
.vh{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.hero__sub a{color:#fff;text-decoration:underline;text-underline-offset:3px;font-weight:600}
.hero__sub a:hover{color:var(--hl)}
img{max-width:100%;display:block}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 22px}
.section{padding:76px 0}
.section--tight{padding:56px 0}
.eyebrow{display:inline-flex;align-items:center;gap:.5rem;font-weight:700;font-size:.78rem;
  letter-spacing:.14em;text-transform:uppercase;color:var(--teal-700);margin:0 0 .9rem}
.eyebrow::before{content:"";width:26px;height:2px;background:var(--amber);border-radius:2px}
.lead{font-size:1.12rem;color:var(--body);max-width:60ch}
.center{text-align:center}
.center .lead{margin-left:auto;margin-right:auto}

/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.55rem;font-weight:700;
  font-size:1rem;padding:.92rem 1.5rem;border-radius:999px;border:2px solid transparent;cursor:pointer;
  text-decoration:none;transition:transform .15s ease,background .2s ease,box-shadow .2s ease;line-height:1}
.btn:hover{transform:translateY(-2px)}
.btn--primary{background:var(--teal-700);color:#fff;box-shadow:var(--shadow-sm)}
.btn--primary:hover{background:var(--teal-800);color:#fff}
.btn--light{background:var(--cream);color:var(--navy)}
.btn--light:hover{background:#fff;color:var(--navy)}
.btn--ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn--ghost:hover{background:rgba(255,255,255,.12);color:#fff}
.btn--outline{background:transparent;color:var(--teal-700);border-color:var(--teal-700)}
.btn--outline:hover{background:var(--mist);color:var(--teal-800)}

.skip{position:absolute;left:-999px;top:0;background:var(--navy);color:#fff;padding:.7rem 1.1rem;z-index:200;border-radius:0 0 8px 0}
.skip:focus{left:0;color:#fff}

/* Utility bar */
.util{background:var(--navy);color:#cddbe8;font-size:.86rem}
.util .wrap{display:flex;flex-wrap:wrap;gap:.4rem 1.4rem;align-items:center;justify-content:space-between;padding-top:.5rem;padding-bottom:.5rem}
.util a{color:#e7eef6;text-decoration:none}
.util a:hover{color:#fff}
.util .util__group{display:flex;flex-wrap:wrap;gap:.3rem 1.3rem;align-items:center}
.util i{color:var(--hl);margin-right:.4rem}
.util__reg{font-weight:700;color:#fff}

/* Header */
.site-header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.93);backdrop-filter:saturate(1.4) blur(8px);
  border-bottom:1px solid var(--line)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding-top:.55rem;padding-bottom:.55rem}
.brand{display:inline-flex;align-items:center;text-decoration:none}
.brand img{height:56px;width:auto;max-width:210px;object-fit:contain;display:block}
.nav{display:flex;align-items:center;gap:.35rem}
.nav a{color:var(--ink);text-decoration:none;font-weight:600;font-size:.97rem;padding:.5rem .7rem;border-radius:8px}
.nav a:hover{background:var(--mist);color:var(--teal-800)}
.nav__has{position:relative}
.nav__panel{position:absolute;top:calc(100% + 6px);left:0;background:#fff;border:1px solid var(--line);border-radius:12px;
  box-shadow:var(--shadow);padding:.5rem;min-width:255px;display:none;z-index:20}
.nav__has:hover .nav__panel,.nav__has:focus-within .nav__panel{display:block}
.nav__panel a{display:block;padding:.55rem .7rem;font-size:.92rem}
.header__cta{display:flex;align-items:center;gap:.6rem}
.header__phone{display:inline-flex;align-items:center;gap:.45rem;font-weight:700;color:var(--navy);text-decoration:none;font-size:.95rem}
.header__phone i{color:var(--teal-700)}
.burger{display:none;background:var(--mist);border:1px solid var(--line);border-radius:10px;width:46px;height:46px;font-size:1.2rem;color:var(--navy);cursor:pointer}

/* Hero */
.hero{position:relative;color:#e9f3f1;background:linear-gradient(120deg,#0A3A52 0%,#0A6E9C 46%,#00A890 120%);overflow:hidden}
.hero::after{content:"";position:absolute;right:-8%;top:-30%;width:520px;height:520px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,rgba(0,168,144,.30),rgba(0,168,144,0) 62%);pointer-events:none}
.hero .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1.08fr .92fr;gap:48px;align-items:center;padding-top:70px;padding-bottom:78px}
.hero__eyebrow{color:var(--hl)}
.hero h1{color:#fff;font-size:clamp(2.15rem,5vw,3.4rem);font-weight:800;margin-bottom:.4em;letter-spacing:-.025em}
.hero h1 .hl{color:var(--hl)}
.hero__sub{font-size:1.15rem;color:#dcebe8;max-width:52ch;margin-bottom:1.5rem}
.hero__cta{display:flex;flex-wrap:wrap;gap:.8rem;margin-bottom:1.6rem}
.hero__chips{display:flex;flex-wrap:wrap;gap:.5rem}
.chip{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.22);
  border-radius:999px;padding:.42rem .8rem;font-size:.82rem;font-weight:600;color:#eef7f4}
.chip i{color:var(--hl)}

.hero__media{position:relative}
.hero__ph{position:relative;border-radius:22px;overflow:hidden;box-shadow:0 30px 60px -28px rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.2)}
.ph{position:relative;background:
    repeating-linear-gradient(45deg,rgba(255,255,255,.05) 0 12px,rgba(255,255,255,.09) 12px 24px),
    linear-gradient(135deg,#0A78AC,#0A7E6E);
  color:#eafaf6;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:.45rem;padding:22px}
.ph--light{background:
    repeating-linear-gradient(45deg,rgba(11,36,64,.05) 0 12px,rgba(11,36,64,.09) 12px 24px),
    linear-gradient(135deg,#E6F3FB,#E7F4F1);color:var(--teal-800)}
.ph i.ph__ico{font-size:1.9rem;opacity:.9}
.ph__label{font-weight:700;font-size:.82rem;letter-spacing:.08em;text-transform:uppercase}
.ph__meta{font-size:.75rem;opacity:.9;max-width:36ch;line-height:1.4}
.hero__ph .ph{aspect-ratio:4/3}
.matchcard{position:absolute;left:-18px;bottom:-22px;background:#fff;color:var(--ink);border-radius:16px;
  box-shadow:var(--shadow);padding:14px 16px;width:min(300px,78%);border:1px solid var(--line)}
.matchcard .mc-title{font-size:.8rem;text-transform:uppercase;letter-spacing:.1em;color:var(--teal-700);margin:0 0 .55rem;font-weight:800}
.matchcard ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:.5rem}
.matchcard li{display:flex;align-items:center;gap:.5rem;font-size:.86rem;font-weight:600;color:var(--body)}
.matchcard li i{width:26px;height:26px;display:grid;place-items:center;border-radius:8px;background:var(--mist);color:var(--teal-700);font-size:.8rem}

/* Trust bar */
.trustbar{background:var(--cream);border-bottom:1px solid var(--line)}
.trustbar .grid{display:grid;grid-template-columns:repeat(5,1fr);gap:18px}
.trust{display:flex;gap:.7rem;align-items:flex-start}
.trust i{flex:none;width:40px;height:40px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.05rem}
.trust b{display:block;color:var(--ink);font-size:.95rem;line-height:1.25}
.trust span{font-size:.83rem;color:var(--muted)}

/* Services */
.svc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:36px}
.svc{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px;box-shadow:var(--shadow-sm);transition:transform .18s ease,box-shadow .2s ease;overflow:hidden}
.svc::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:linear-gradient(var(--blue),var(--teal))}
.svc:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.svc__ico{width:52px;height:52px;display:grid;place-items:center;border-radius:13px;background:var(--mist);color:var(--teal-700);font-size:1.3rem;margin-bottom:14px}
.svc h3{margin-bottom:.4rem}
.svc p{font-size:.96rem;margin-bottom:1rem}
.svc a.svc__link{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}
.svc a.svc__link i{transition:transform .15s ease}
.svc a.svc__link:hover i{transform:translateX(3px)}
.svc-more{margin-top:22px;display:flex;flex-wrap:wrap;gap:.6rem 1.1rem;align-items:center;font-size:.95rem}
.svc-more span{font-weight:700;color:var(--ink)}
.callout{margin-top:26px;display:flex;gap:18px;align-items:center;flex-wrap:wrap;justify-content:space-between;
  background:linear-gradient(120deg,#0A3A52,#0A7E6E);color:#e9f3f1;border-radius:var(--radius);padding:24px 26px;
  border:1px solid rgba(255,255,255,.14);box-shadow:var(--shadow-sm);position:relative;overflow:hidden}
.callout::after{content:"";position:absolute;right:-40px;top:-40px;width:180px;height:180px;border-radius:50%;
  background:radial-gradient(circle,rgba(0,168,144,.32),transparent 65%)}
.callout .callout__t{position:relative;z-index:2;max-width:64ch}
.callout h3{color:#fff;margin-bottom:.25rem}
.callout p{margin:0;color:#d7e6e2;font-size:.96rem}
.callout .btn{position:relative;z-index:2}

/* Matching */
.matching{background:var(--navy);color:#e3eef1;position:relative;overflow:hidden}
.matching::before{content:"";position:absolute;inset:0;background:radial-gradient(1000px 420px at 82% -10%,rgba(0,168,144,.34),transparent 60%);pointer-events:none}
.matching .wrap{position:relative;z-index:2;display:grid;grid-template-columns:.95fr 1.05fr;gap:46px;align-items:center}
.matching h2{color:#fff}
.matching .eyebrow{color:var(--hl)}
.matching .lead{color:#c6d7db}
.match-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.match{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:14px;padding:18px}
.match i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:rgba(134,230,216,.16);color:var(--hl);font-size:1.1rem;margin-bottom:10px}
.match b{display:block;color:#fff;font-size:1rem;margin-bottom:.2rem}
.match span{font-size:.88rem;color:#bfd3d7}

/* Steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:40px;counter-reset:step}
.step{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px 22px;box-shadow:var(--shadow-sm)}
.step__n{counter-increment:step;width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:var(--amber-100);color:var(--amber-700);font-size:1.3rem;font-weight:800;margin-bottom:14px}
.step__n::before{content:counter(step)}
.step h3{font-size:1.1rem;margin-bottom:.35rem}
.step p{font-size:.92rem;margin:0}
.pill-note{margin-top:26px;display:inline-flex;align-items:center;gap:.6rem;background:var(--mist);border:1px solid var(--line);border-radius:999px;padding:.6rem 1.1rem;font-weight:600;color:var(--teal-800);font-size:.95rem}
.pill-note i{color:var(--teal-700)}

/* Coverage */
.coverage{background:var(--slate)}
.cov-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:34px}
.cov{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:28px;box-shadow:var(--shadow-sm)}
.cov__head{display:flex;align-items:center;gap:.7rem;margin-bottom:.4rem}
.cov__head i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.1rem}
.cov__head h3{margin:0}
.cov__head span{font-size:.82rem;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.08em}
.cov ul{list-style:none;padding:0;margin:.7rem 0 1rem;display:flex;flex-wrap:wrap;gap:.5rem}
.cov li{background:var(--mist);border:1px solid var(--line);border-radius:999px;font-size:.85rem;font-weight:600;color:var(--teal-800);overflow:hidden;transition:background .15s ease,border-color .15s ease}
.cov li:hover{background:var(--teal-100);border-color:var(--teal-700)}
.cov li a{display:block;padding:.32rem .75rem;color:var(--teal-800);text-decoration:none}
.cov a{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}

/* Reviews */
.rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:34px}
.rev{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm);position:relative}
.rev .quo{font-size:1.6rem;color:var(--teal);opacity:.5}
.rev p{color:var(--muted);font-size:.95rem;font-style:italic}
.rev .rev__ph{display:flex;align-items:center;gap:.7rem;margin-top:14px;border-top:1px dashed var(--line);padding-top:14px}
.rev .rev__av{width:42px;height:42px;border-radius:50%;background:var(--mist);display:grid;place-items:center;color:var(--teal-700)}
.rev .rev__meta b{display:block;color:var(--ink);font-size:.9rem}
.rev .rev__meta span{font-size:.78rem;color:var(--muted)}
.rev-note{margin-top:22px;text-align:center;font-size:.92rem;color:var(--muted)}

/* Why */
.why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:36px}
.why{display:flex;gap:.9rem;align-items:flex-start;background:var(--cream);border:1px solid var(--line);border-radius:14px;padding:22px}
.why i{flex:none;width:46px;height:46px;display:grid;place-items:center;border-radius:12px;background:var(--teal-700);color:#fff;font-size:1.1rem}
.why b{display:block;color:var(--ink);font-size:1.02rem;margin-bottom:.2rem}
.why span{font-size:.9rem;color:var(--muted)}

/* FAQ */
.faq{max-width:820px;margin:34px auto 0}
.qa{border:1px solid var(--line);border-radius:12px;margin-bottom:12px;background:#fff;overflow:hidden}
.qa__q{width:100%;text-align:left;background:none;border:0;padding:18px 20px;font-family:var(--font-body);font-weight:700;font-size:1.03rem;color:var(--ink);display:flex;justify-content:space-between;align-items:center;gap:1rem;cursor:pointer}
.qa__q i{color:var(--teal-700);transition:transform .2s ease;flex:none}
.qa__q[aria-expanded="true"] i{transform:rotate(45deg)}
.qa__a{padding:0 20px;max-height:0;overflow:hidden;transition:max-height .25s ease,padding .25s ease}
.qa__a p{margin:0 0 16px}
.qa__q[aria-expanded="true"]+.qa__a{padding:2px 20px 4px}

/* CTA + form */
.cta{background:linear-gradient(135deg,#0A3A52 0%,#0A6E9C 50%,#00A890 130%);color:#e9f3f1;position:relative;overflow:hidden}
.cta::after{content:"";position:absolute;left:-6%;bottom:-40%;width:460px;height:460px;border-radius:50%;background:radial-gradient(circle,rgba(0,168,144,.24),transparent 62%);pointer-events:none}
.cta .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
.cta h2{color:#fff}
.cta .eyebrow{color:var(--hl)}
.cta__points{list-style:none;padding:0;margin:1.2rem 0 0;display:grid;gap:.6rem}
.cta__points li{display:flex;gap:.6rem;align-items:flex-start;color:#d7e6e2;font-size:.98rem}
.cta__points i{color:var(--hl);margin-top:.2rem}
.cta__calls{display:flex;flex-wrap:wrap;gap:.7rem;margin-top:1.4rem}
.callbtn{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.24);color:#fff;text-decoration:none;border-radius:12px;padding:.7rem 1rem;font-weight:700;font-size:.95rem}
.callbtn i{color:var(--hl)}
.callbtn:hover{background:rgba(255,255,255,.18);color:#fff}
.form{background:#fff;border-radius:20px;padding:26px;box-shadow:var(--shadow);color:var(--body)}
.form h3{color:var(--ink)}
.form .fnote{font-size:.86rem;color:var(--muted);margin-bottom:1.1rem}
.field{margin-bottom:14px}
.field label{display:block;font-weight:700;font-size:.88rem;color:var(--ink);margin-bottom:.35rem}
.field input,.field select,.field textarea{width:100%;padding:.72rem .85rem;border:1.5px solid var(--line);border-radius:10px;font-family:inherit;font-size:.97rem;color:var(--ink);background:#fff}
.field input:focus,.field select:focus,.field textarea:focus{outline:3px solid rgba(14,159,142,.30);border-color:var(--teal-700)}
.field textarea{min-height:92px;resize:vertical}
.field .req{color:#b23b3b}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.form .consent{font-size:.8rem;color:var(--muted);margin:.4rem 0 1rem}
.form__msg{display:none;background:var(--sky);border:1px solid var(--blue);color:var(--deep);border-radius:10px;padding:.8rem 1rem;font-size:.9rem;font-weight:600;margin-bottom:1rem}
.form__msg.show{display:block}

/* Footer */
.footer{background:var(--navy);color:#c4d3df;font-size:.94rem}
.footer a{color:#dbe6f0;text-decoration:none}
.footer a:hover{color:#fff}
.footer__top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.2fr;gap:34px;padding:58px 0 34px}
.footer__logo{display:inline-block;background:#fff;border-radius:12px;padding:10px 14px;margin-bottom:1rem}
.footer__logo img{height:44px;width:auto;max-width:170px;object-fit:contain;display:block}
.footer p{color:#b6c7d4;font-size:.92rem}
.footer h4{color:#fff;font-size:.82rem;letter-spacing:.12em;text-transform:uppercase;margin:0 0 1rem;font-weight:800}
.footer ul{list-style:none;padding:0;margin:0;display:grid;gap:.55rem}
.footer .nap li{display:flex;gap:.6rem;align-items:flex-start;margin-bottom:.55rem}
.footer .nap i{color:var(--hl);width:18px;margin-top:.2rem;flex:none}
.footer__socials{display:flex;gap:.55rem;margin-top:1rem}
.footer__socials a{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:rgba(255,255,255,.08);color:#e7eef6}
.footer__socials a:hover{background:var(--teal-700);color:#fff}
.footer__bottom{border-top:1px solid rgba(255,255,255,.12);padding:18px 0;display:flex;flex-wrap:wrap;gap:.6rem 1.4rem;align-items:center;justify-content:space-between;font-size:.85rem;color:#9fb4c4}
.footer__bottom a{color:#c4d3df}
.footer__legal{display:flex;flex-wrap:wrap;gap:.4rem 1.2rem}

/* Mobile call bar */
.mcall{position:fixed;left:0;right:0;bottom:0;z-index:90;display:none;grid-template-columns:1fr 1fr;background:#fff;border-top:1px solid var(--line);box-shadow:0 -8px 24px -14px rgba(11,36,64,.5)}
.mcall a{display:flex;align-items:center;justify-content:center;gap:.5rem;padding:.9rem;font-weight:800;text-decoration:none;font-size:.95rem}
.mcall a.call{color:var(--navy)}
.mcall a.enq{background:var(--teal-700);color:#fff}

/* Responsive */
@media (max-width:960px){
  .hero .wrap,.matching .wrap,.cta .wrap{grid-template-columns:1fr;gap:34px}
  .hero__media{max-width:520px}
  .trustbar .grid{grid-template-columns:repeat(2,1fr)}
  .steps{grid-template-columns:1fr 1fr}
  .why-grid,.rev-grid{grid-template-columns:1fr 1fr}
  .footer__top{grid-template-columns:1fr 1fr}
  .nav,.header__phone{display:none}
  .burger{display:inline-flex;align-items:center;justify-content:center}
  .mcall{display:grid}
  body{padding-bottom:56px}
}
@media (max-width:620px){
  .section{padding:56px 0}
  .svc-grid,.match-grid,.cov-grid,.why-grid,.rev-grid,.steps,.trustbar .grid{grid-template-columns:1fr}
  .matchcard{position:static;width:100%;margin-top:14px}
  .util .wrap{justify-content:flex-start}
  .footer__top{grid-template-columns:1fr}
  h2{font-size:1.6rem}
}
.mnav{position:fixed;inset:0;z-index:120;background:rgba(6,18,32,.55);display:none}
.mnav.open{display:block}
.mnav__panel{position:absolute;top:0;right:0;height:100%;width:min(330px,86vw);background:#fff;padding:20px;overflow-y:auto;box-shadow:var(--shadow)}
.mnav__panel a{display:block;padding:.8rem .4rem;border-bottom:1px solid var(--line);color:var(--ink);text-decoration:none;font-weight:700}
.mnav__panel a.sub{padding-left:1.3rem;font-weight:600;font-size:.94rem;color:var(--body)}
.mnav__close{background:var(--mist);border:0;border-radius:10px;width:44px;height:44px;font-size:1.1rem;float:right;margin-bottom:.5rem;cursor:pointer;color:var(--navy)}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}

:root{
  /* Brand palette v5, sampled from the approved logo: blue #0088C0, teal #00A890, grey #888888 */
  --blue:#0088C0; --blue-600:#0A78AC; --blue-700:#0A6E9C; --blue-800:#0A587F; --deep:#0A3A52;
  --navy:#0A3A52; --navy-800:#0A3A52; --ink:#12303F; --grey:#888888;
  --teal:#00A890; --teal-600:#0A8E7C; --teal-700:#0A7E6E; --teal-800:#0A6357; --teal-100:#D6EFEA;
  --amber:#0A6E9C; --amber-700:#0A6E9C; --amber-100:#E6F3FB; --hl:#86E6D8;
  --cream:#F3F7F9; --mist:#E7F4F1; --sky:#E6F3FB; --slate:#EEF5F9; --line:#D3E4EC;
  --body:#33474F; --muted:#5F7178; --white:#ffffff;
  --maxw:1180px; --radius:16px; --radius-sm:10px;
  --shadow:0 18px 44px -20px rgba(10,58,82,.42); --shadow-sm:0 8px 22px -14px rgba(10,58,82,.4);
  --font-body:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --font-display:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font-body);color:var(--body);background:var(--white);
  font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3,h4{font-family:var(--font-display);color:var(--ink);line-height:1.14;margin:0 0 .5em;font-weight:800;letter-spacing:-.02em}
h2{font-size:clamp(1.7rem,3.6vw,2.5rem)}
h3{font-size:1.26rem;font-weight:700;letter-spacing:-.01em}
p{margin:0 0 1rem}
a{color:var(--teal-700);text-decoration-thickness:1px;text-underline-offset:2px}
a:hover{color:var(--teal-800)}
.vh{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.hero__sub a{color:#fff;text-decoration:underline;text-underline-offset:3px;font-weight:600}
.hero__sub a:hover{color:var(--hl)}
img{max-width:100%;display:block}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 22px}
.section{padding:76px 0}
.section--tight{padding:56px 0}
.eyebrow{display:inline-flex;align-items:center;gap:.5rem;font-weight:700;font-size:.78rem;
  letter-spacing:.14em;text-transform:uppercase;color:var(--teal-700);margin:0 0 .9rem}
.eyebrow::before{content:"";width:26px;height:2px;background:var(--amber);border-radius:2px}
.lead{font-size:1.12rem;color:var(--body);max-width:60ch}
.center{text-align:center}
.center .lead{margin-left:auto;margin-right:auto}

/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.55rem;font-weight:700;
  font-size:1rem;padding:.92rem 1.5rem;border-radius:999px;border:2px solid transparent;cursor:pointer;
  text-decoration:none;transition:transform .15s ease,background .2s ease,box-shadow .2s ease;line-height:1}
.btn:hover{transform:translateY(-2px)}
.btn--primary{background:var(--teal-700);color:#fff;box-shadow:var(--shadow-sm)}
.btn--primary:hover{background:var(--teal-800);color:#fff}
.btn--light{background:var(--cream);color:var(--navy)}
.btn--light:hover{background:#fff;color:var(--navy)}
.btn--ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn--ghost:hover{background:rgba(255,255,255,.12);color:#fff}
.btn--outline{background:transparent;color:var(--teal-700);border-color:var(--teal-700)}
.btn--outline:hover{background:var(--mist);color:var(--teal-800)}

.skip{position:absolute;left:-999px;top:0;background:var(--navy);color:#fff;padding:.7rem 1.1rem;z-index:200;border-radius:0 0 8px 0}
.skip:focus{left:0;color:#fff}

/* Utility bar */
.util{background:var(--navy);color:#cddbe8;font-size:.86rem}
.util .wrap{display:flex;flex-wrap:wrap;gap:.4rem 1.4rem;align-items:center;justify-content:space-between;padding-top:.5rem;padding-bottom:.5rem}
.util a{color:#e7eef6;text-decoration:none}
.util a:hover{color:#fff}
.util .util__group{display:flex;flex-wrap:wrap;gap:.3rem 1.3rem;align-items:center}
.util i{color:var(--hl);margin-right:.4rem}
.util__reg{font-weight:700;color:#fff}

/* Header */
.site-header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.93);backdrop-filter:saturate(1.4) blur(8px);
  border-bottom:1px solid var(--line)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding-top:.55rem;padding-bottom:.55rem}
.brand{display:inline-flex;align-items:center;text-decoration:none}
.brand img{height:56px;width:auto;max-width:210px;object-fit:contain;display:block}
.nav{display:flex;align-items:center;gap:.35rem}
.nav a{color:var(--ink);text-decoration:none;font-weight:600;font-size:.97rem;padding:.5rem .7rem;border-radius:8px}
.nav a:hover{background:var(--mist);color:var(--teal-800)}
.nav__has{position:relative}
.nav__panel{position:absolute;top:calc(100% + 6px);left:0;background:#fff;border:1px solid var(--line);border-radius:12px;
  box-shadow:var(--shadow);padding:.5rem;min-width:255px;display:none;z-index:20}
.nav__has:hover .nav__panel,.nav__has:focus-within .nav__panel{display:block}
.nav__panel a{display:block;padding:.55rem .7rem;font-size:.92rem}
.header__cta{display:flex;align-items:center;gap:.6rem}
.header__phone{display:inline-flex;align-items:center;gap:.45rem;font-weight:700;color:var(--navy);text-decoration:none;font-size:.95rem}
.header__phone i{color:var(--teal-700)}
.burger{display:none;background:var(--mist);border:1px solid var(--line);border-radius:10px;width:46px;height:46px;font-size:1.2rem;color:var(--navy);cursor:pointer}

/* Hero */
.hero{position:relative;color:#e9f3f1;background:linear-gradient(120deg,#0A3A52 0%,#0A6E9C 46%,#00A890 120%);overflow:hidden}
.hero::after{content:"";position:absolute;right:-8%;top:-30%;width:520px;height:520px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,rgba(0,168,144,.30),rgba(0,168,144,0) 62%);pointer-events:none}
.hero .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1.08fr .92fr;gap:48px;align-items:center;padding-top:70px;padding-bottom:78px}
.hero__eyebrow{color:var(--hl)}
.hero h1{color:#fff;font-size:clamp(2.15rem,5vw,3.4rem);font-weight:800;margin-bottom:.4em;letter-spacing:-.025em}
.hero h1 .hl{color:var(--hl)}
.hero__sub{font-size:1.15rem;color:#dcebe8;max-width:52ch;margin-bottom:1.5rem}
.hero__cta{display:flex;flex-wrap:wrap;gap:.8rem;margin-bottom:1.6rem}
.hero__chips{display:flex;flex-wrap:wrap;gap:.5rem}
.chip{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.22);
  border-radius:999px;padding:.42rem .8rem;font-size:.82rem;font-weight:600;color:#eef7f4}
.chip i{color:var(--hl)}

.hero__media{position:relative}
.hero__ph{position:relative;border-radius:22px;overflow:hidden;box-shadow:0 30px 60px -28px rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.2)}
.ph{position:relative;background:
    repeating-linear-gradient(45deg,rgba(255,255,255,.05) 0 12px,rgba(255,255,255,.09) 12px 24px),
    linear-gradient(135deg,#0A78AC,#0A7E6E);
  color:#eafaf6;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:.45rem;padding:22px}
.ph--light{background:
    repeating-linear-gradient(45deg,rgba(11,36,64,.05) 0 12px,rgba(11,36,64,.09) 12px 24px),
    linear-gradient(135deg,#E6F3FB,#E7F4F1);color:var(--teal-800)}
.ph i.ph__ico{font-size:1.9rem;opacity:.9}
.ph__label{font-weight:700;font-size:.82rem;letter-spacing:.08em;text-transform:uppercase}
.ph__meta{font-size:.75rem;opacity:.9;max-width:36ch;line-height:1.4}
.hero__ph .ph{aspect-ratio:4/3}
.matchcard{position:absolute;left:-18px;bottom:-22px;background:#fff;color:var(--ink);border-radius:16px;
  box-shadow:var(--shadow);padding:14px 16px;width:min(300px,78%);border:1px solid var(--line)}
.matchcard .mc-title{font-size:.8rem;text-transform:uppercase;letter-spacing:.1em;color:var(--teal-700);margin:0 0 .55rem;font-weight:800}
.matchcard ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:.5rem}
.matchcard li{display:flex;align-items:center;gap:.5rem;font-size:.86rem;font-weight:600;color:var(--body)}
.matchcard li i{width:26px;height:26px;display:grid;place-items:center;border-radius:8px;background:var(--mist);color:var(--teal-700);font-size:.8rem}

/* Trust bar */
.trustbar{background:var(--cream);border-bottom:1px solid var(--line)}
.trustbar .grid{display:grid;grid-template-columns:repeat(5,1fr);gap:18px}
.trust{display:flex;gap:.7rem;align-items:flex-start}
.trust i{flex:none;width:40px;height:40px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.05rem}
.trust b{display:block;color:var(--ink);font-size:.95rem;line-height:1.25}
.trust span{font-size:.83rem;color:var(--muted)}

/* Services */
.svc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:36px}
.svc{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px;box-shadow:var(--shadow-sm);transition:transform .18s ease,box-shadow .2s ease;overflow:hidden}
.svc::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:linear-gradient(var(--blue),var(--teal))}
.svc:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.svc__ico{width:52px;height:52px;display:grid;place-items:center;border-radius:13px;background:var(--mist);color:var(--teal-700);font-size:1.3rem;margin-bottom:14px}
.svc h3{margin-bottom:.4rem}
.svc p{font-size:.96rem;margin-bottom:1rem}
.svc a.svc__link{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}
.svc a.svc__link i{transition:transform .15s ease}
.svc a.svc__link:hover i{transform:translateX(3px)}
.svc-more{margin-top:22px;display:flex;flex-wrap:wrap;gap:.6rem 1.1rem;align-items:center;font-size:.95rem}
.svc-more span{font-weight:700;color:var(--ink)}
.callout{margin-top:26px;display:flex;gap:18px;align-items:center;flex-wrap:wrap;justify-content:space-between;
  background:linear-gradient(120deg,#0A3A52,#0A7E6E);color:#e9f3f1;border-radius:var(--radius);padding:24px 26px;
  border:1px solid rgba(255,255,255,.14);box-shadow:var(--shadow-sm);position:relative;overflow:hidden}
.callout::after{content:"";position:absolute;right:-40px;top:-40px;width:180px;height:180px;border-radius:50%;
  background:radial-gradient(circle,rgba(0,168,144,.32),transparent 65%)}
.callout .callout__t{position:relative;z-index:2;max-width:64ch}
.callout h3{color:#fff;margin-bottom:.25rem}
.callout p{margin:0;color:#d7e6e2;font-size:.96rem}
.callout .btn{position:relative;z-index:2}

/* Matching */
.matching{background:var(--navy);color:#e3eef1;position:relative;overflow:hidden}
.matching::before{content:"";position:absolute;inset:0;background:radial-gradient(1000px 420px at 82% -10%,rgba(0,168,144,.34),transparent 60%);pointer-events:none}
.matching .wrap{position:relative;z-index:2;display:grid;grid-template-columns:.95fr 1.05fr;gap:46px;align-items:center}
.matching h2{color:#fff}
.matching .eyebrow{color:var(--hl)}
.matching .lead{color:#c6d7db}
.match-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.match{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:14px;padding:18px}
.match i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:rgba(134,230,216,.16);color:var(--hl);font-size:1.1rem;margin-bottom:10px}
.match b{display:block;color:#fff;font-size:1rem;margin-bottom:.2rem}
.match span{font-size:.88rem;color:#bfd3d7}

/* Steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:40px;counter-reset:step}
.step{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px 22px;box-shadow:var(--shadow-sm)}
.step__n{counter-increment:step;width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:var(--amber-100);color:var(--amber-700);font-size:1.3rem;font-weight:800;margin-bottom:14px}
.step__n::before{content:counter(step)}
.step h3{font-size:1.1rem;margin-bottom:.35rem}
.step p{font-size:.92rem;margin:0}
.pill-note{margin-top:26px;display:inline-flex;align-items:center;gap:.6rem;background:var(--mist);border:1px solid var(--line);border-radius:999px;padding:.6rem 1.1rem;font-weight:600;color:var(--teal-800);font-size:.95rem}
.pill-note i{color:var(--teal-700)}

/* Coverage */
.coverage{background:var(--slate)}
.cov-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:34px}
.cov{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:28px;box-shadow:var(--shadow-sm)}
.cov__head{display:flex;align-items:center;gap:.7rem;margin-bottom:.4rem}
.cov__head i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.1rem}
.cov__head h3{margin:0}
.cov__head span{font-size:.82rem;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.08em}
.cov ul{list-style:none;padding:0;margin:.7rem 0 1rem;display:flex;flex-wrap:wrap;gap:.5rem}
.cov li{background:var(--mist);border:1px solid var(--line);border-radius:999px;font-size:.85rem;font-weight:600;color:var(--teal-800);overflow:hidden;transition:background .15s ease,border-color .15s ease}
.cov li:hover{background:var(--teal-100);border-color:var(--teal-700)}
.cov li a{display:block;padding:.32rem .75rem;color:var(--teal-800);text-decoration:none}
.cov a{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}

/* Reviews */
.rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:34px}
.rev{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm);position:relative}
.rev .quo{font-size:1.6rem;color:var(--teal);opacity:.5}
.rev p{color:var(--muted);font-size:.95rem;font-style:italic}
.rev .rev__ph{display:flex;align-items:center;gap:.7rem;margin-top:14px;border-top:1px dashed var(--line);padding-top:14px}
.rev .rev__av{width:42px;height:42px;border-radius:50%;background:var(--mist);display:grid;place-items:center;color:var(--teal-700)}
.rev .rev__meta b{display:block;color:var(--ink);font-size:.9rem}
.rev .rev__meta span{font-size:.78rem;color:var(--muted)}
.rev-note{margin-top:22px;text-align:center;font-size:.92rem;color:var(--muted)}

/* Why */
.why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:36px}
.why{display:flex;gap:.9rem;align-items:flex-start;background:var(--cream);border:1px solid var(--line);border-radius:14px;padding:22px}
.why i{flex:none;width:46px;height:46px;display:grid;place-items:center;border-radius:12px;background:var(--teal-700);color:#fff;font-size:1.1rem}
.why b{display:block;color:var(--ink);font-size:1.02rem;margin-bottom:.2rem}
.why span{font-size:.9rem;color:var(--muted)}

/* FAQ */
.faq{max-width:820px;margin:34px auto 0}
.qa{border:1px solid var(--line);border-radius:12px;margin-bottom:12px;background:#fff;overflow:hidden}
.qa__q{width:100%;text-align:left;background:none;border:0;padding:18px 20px;font-family:var(--font-body);font-weight:700;font-size:1.03rem;color:var(--ink);display:flex;justify-content:space-between;align-items:center;gap:1rem;cursor:pointer}
.qa__q i{color:var(--teal-700);transition:transform .2s ease;flex:none}
.qa__q[aria-expanded="true"] i{transform:rotate(45deg)}
.qa__a{padding:0 20px;max-height:0;overflow:hidden;transition:max-height .25s ease,padding .25s ease}
.qa__a p{margin:0 0 16px}
.qa__q[aria-expanded="true"]+.qa__a{padding:2px 20px 4px}

/* CTA + form */
.cta{background:linear-gradient(135deg,#0A3A52 0%,#0A6E9C 50%,#00A890 130%);color:#e9f3f1;position:relative;overflow:hidden}
.cta::after{content:"";position:absolute;left:-6%;bottom:-40%;width:460px;height:460px;border-radius:50%;background:radial-gradient(circle,rgba(0,168,144,.24),transparent 62%);pointer-events:none}
.cta .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
.cta h2{color:#fff}
.cta .eyebrow{color:var(--hl)}
.cta__points{list-style:none;padding:0;margin:1.2rem 0 0;display:grid;gap:.6rem}
.cta__points li{display:flex;gap:.6rem;align-items:flex-start;color:#d7e6e2;font-size:.98rem}
.cta__points i{color:var(--hl);margin-top:.2rem}
.cta__calls{display:flex;flex-wrap:wrap;gap:.7rem;margin-top:1.4rem}
.callbtn{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.24);color:#fff;text-decoration:none;border-radius:12px;padding:.7rem 1rem;font-weight:700;font-size:.95rem}
.callbtn i{color:var(--hl)}
.callbtn:hover{background:rgba(255,255,255,.18);color:#fff}
.form{background:#fff;border-radius:20px;padding:26px;box-shadow:var(--shadow);color:var(--body)}
.form h3{color:var(--ink)}
.form .fnote{font-size:.86rem;color:var(--muted);margin-bottom:1.1rem}
.field{margin-bottom:14px}
.field label{display:block;font-weight:700;font-size:.88rem;color:var(--ink);margin-bottom:.35rem}
.field input,.field select,.field textarea{width:100%;padding:.72rem .85rem;border:1.5px solid var(--line);border-radius:10px;font-family:inherit;font-size:.97rem;color:var(--ink);background:#fff}
.field input:focus,.field select:focus,.field textarea:focus{outline:3px solid rgba(14,159,142,.30);border-color:var(--teal-700)}
.field textarea{min-height:92px;resize:vertical}
.field .req{color:#b23b3b}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.form .consent{font-size:.8rem;color:var(--muted);margin:.4rem 0 1rem}
.form__msg{display:none;background:var(--sky);border:1px solid var(--blue);color:var(--deep);border-radius:10px;padding:.8rem 1rem;font-size:.9rem;font-weight:600;margin-bottom:1rem}
.form__msg.show{display:block}

/* Footer */
.footer{background:var(--navy);color:#c4d3df;font-size:.94rem}
.footer a{color:#dbe6f0;text-decoration:none}
.footer a:hover{color:#fff}
.footer__top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.2fr;gap:34px;padding:58px 0 34px}
.footer__logo{display:inline-block;background:#fff;border-radius:12px;padding:10px 14px;margin-bottom:1rem}
.footer__logo img{height:44px;width:auto;max-width:170px;object-fit:contain;display:block}
.footer p{color:#b6c7d4;font-size:.92rem}
.footer h4{color:#fff;font-size:.82rem;letter-spacing:.12em;text-transform:uppercase;margin:0 0 1rem;font-weight:800}
.footer ul{list-style:none;padding:0;margin:0;display:grid;gap:.55rem}
.footer .nap li{display:flex;gap:.6rem;align-items:flex-start;margin-bottom:.55rem}
.footer .nap i{color:var(--hl);width:18px;margin-top:.2rem;flex:none}
.footer__socials{display:flex;gap:.55rem;margin-top:1rem}
.footer__socials a{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:rgba(255,255,255,.08);color:#e7eef6}
.footer__socials a:hover{background:var(--teal-700);color:#fff}
.footer__bottom{border-top:1px solid rgba(255,255,255,.12);padding:18px 0;display:flex;flex-wrap:wrap;gap:.6rem 1.4rem;align-items:center;justify-content:space-between;font-size:.85rem;color:#9fb4c4}
.footer__bottom a{color:#c4d3df}
.footer__legal{display:flex;flex-wrap:wrap;gap:.4rem 1.2rem}

/* Mobile call bar */
.mcall{position:fixed;left:0;right:0;bottom:0;z-index:90;display:none;grid-template-columns:1fr 1fr;background:#fff;border-top:1px solid var(--line);box-shadow:0 -8px 24px -14px rgba(11,36,64,.5)}
.mcall a{display:flex;align-items:center;justify-content:center;gap:.5rem;padding:.9rem;font-weight:800;text-decoration:none;font-size:.95rem}
.mcall a.call{color:var(--navy)}
.mcall a.enq{background:var(--teal-700);color:#fff}

/* Responsive */
@media (max-width:960px){
  .hero .wrap,.matching .wrap,.cta .wrap{grid-template-columns:1fr;gap:34px}
  .hero__media{max-width:520px}
  .trustbar .grid{grid-template-columns:repeat(2,1fr)}
  .steps{grid-template-columns:1fr 1fr}
  .why-grid,.rev-grid{grid-template-columns:1fr 1fr}
  .footer__top{grid-template-columns:1fr 1fr}
  .nav,.header__phone{display:none}
  .burger{display:inline-flex;align-items:center;justify-content:center}
  .mcall{display:grid}
  body{padding-bottom:56px}
}
@media (max-width:620px){
  .section{padding:56px 0}
  .svc-grid,.match-grid,.cov-grid,.why-grid,.rev-grid,.steps,.trustbar .grid{grid-template-columns:1fr}
  .matchcard{position:static;width:100%;margin-top:14px}
  .util .wrap{justify-content:flex-start}
  .footer__top{grid-template-columns:1fr}
  h2{font-size:1.6rem}
}
.mnav{position:fixed;inset:0;z-index:120;background:rgba(6,18,32,.55);display:none}
.mnav.open{display:block}
.mnav__panel{position:absolute;top:0;right:0;height:100%;width:min(330px,86vw);background:#fff;padding:20px;overflow-y:auto;box-shadow:var(--shadow)}
.mnav__panel a{display:block;padding:.8rem .4rem;border-bottom:1px solid var(--line);color:var(--ink);text-decoration:none;font-weight:700}
.mnav__panel a.sub{padding-left:1.3rem;font-weight:600;font-size:.94rem;color:var(--body)}
.mnav__close{background:var(--mist);border:0;border-radius:10px;width:44px;height:44px;font-size:1.1rem;float:right;margin-bottom:.5rem;cursor:pointer;color:var(--navy)}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}

:root{
  /* Brand palette v5, sampled from the approved logo: blue #0088C0, teal #00A890, grey #888888 */
  --blue:#0088C0; --blue-600:#0A78AC; --blue-700:#0A6E9C; --blue-800:#0A587F; --deep:#0A3A52;
  --navy:#0A3A52; --navy-800:#0A3A52; --ink:#12303F; --grey:#888888;
  --teal:#00A890; --teal-600:#0A8E7C; --teal-700:#0A7E6E; --teal-800:#0A6357; --teal-100:#D6EFEA;
  --amber:#0A6E9C; --amber-700:#0A6E9C; --amber-100:#E6F3FB; --hl:#86E6D8;
  --cream:#F3F7F9; --mist:#E7F4F1; --sky:#E6F3FB; --slate:#EEF5F9; --line:#D3E4EC;
  --body:#33474F; --muted:#5F7178; --white:#ffffff;
  --maxw:1180px; --radius:16px; --radius-sm:10px;
  --shadow:0 18px 44px -20px rgba(10,58,82,.42); --shadow-sm:0 8px 22px -14px rgba(10,58,82,.4);
  --font-body:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --font-display:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font-body);color:var(--body);background:var(--white);
  font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3,h4{font-family:var(--font-display);color:var(--ink);line-height:1.14;margin:0 0 .5em;font-weight:800;letter-spacing:-.02em}
h2{font-size:clamp(1.7rem,3.6vw,2.5rem)}
h3{font-size:1.26rem;font-weight:700;letter-spacing:-.01em}
p{margin:0 0 1rem}
a{color:var(--teal-700);text-decoration-thickness:1px;text-underline-offset:2px}
a:hover{color:var(--teal-800)}
.vh{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.hero__sub a{color:#fff;text-decoration:underline;text-underline-offset:3px;font-weight:600}
.hero__sub a:hover{color:var(--hl)}
img{max-width:100%;display:block}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 22px}
.section{padding:76px 0}
.section--tight{padding:56px 0}
.eyebrow{display:inline-flex;align-items:center;gap:.5rem;font-weight:700;font-size:.78rem;
  letter-spacing:.14em;text-transform:uppercase;color:var(--teal-700);margin:0 0 .9rem}
.eyebrow::before{content:"";width:26px;height:2px;background:var(--amber);border-radius:2px}
.lead{font-size:1.12rem;color:var(--body);max-width:60ch}
.center{text-align:center}
.center .lead{margin-left:auto;margin-right:auto}

/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.55rem;font-weight:700;
  font-size:1rem;padding:.92rem 1.5rem;border-radius:999px;border:2px solid transparent;cursor:pointer;
  text-decoration:none;transition:transform .15s ease,background .2s ease,box-shadow .2s ease;line-height:1}
.btn:hover{transform:translateY(-2px)}
.btn--primary{background:var(--teal-700);color:#fff;box-shadow:var(--shadow-sm)}
.btn--primary:hover{background:var(--teal-800);color:#fff}
.btn--light{background:var(--cream);color:var(--navy)}
.btn--light:hover{background:#fff;color:var(--navy)}
.btn--ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn--ghost:hover{background:rgba(255,255,255,.12);color:#fff}
.btn--outline{background:transparent;color:var(--teal-700);border-color:var(--teal-700)}
.btn--outline:hover{background:var(--mist);color:var(--teal-800)}

.skip{position:absolute;left:-999px;top:0;background:var(--navy);color:#fff;padding:.7rem 1.1rem;z-index:200;border-radius:0 0 8px 0}
.skip:focus{left:0;color:#fff}

/* Utility bar */
.util{background:var(--navy);color:#cddbe8;font-size:.86rem}
.util .wrap{display:flex;flex-wrap:wrap;gap:.4rem 1.4rem;align-items:center;justify-content:space-between;padding-top:.5rem;padding-bottom:.5rem}
.util a{color:#e7eef6;text-decoration:none}
.util a:hover{color:#fff}
.util .util__group{display:flex;flex-wrap:wrap;gap:.3rem 1.3rem;align-items:center}
.util i{color:var(--hl);margin-right:.4rem}
.util__reg{font-weight:700;color:#fff}

/* Header */
.site-header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.93);backdrop-filter:saturate(1.4) blur(8px);
  border-bottom:1px solid var(--line)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding-top:.55rem;padding-bottom:.55rem}
.brand{display:inline-flex;align-items:center;text-decoration:none}
.brand img{height:56px;width:auto;max-width:210px;object-fit:contain;display:block}
.nav{display:flex;align-items:center;gap:.35rem}
.nav a{color:var(--ink);text-decoration:none;font-weight:600;font-size:.97rem;padding:.5rem .7rem;border-radius:8px}
.nav a:hover{background:var(--mist);color:var(--teal-800)}
.nav__has{position:relative}
.nav__panel{position:absolute;top:calc(100% + 6px);left:0;background:#fff;border:1px solid var(--line);border-radius:12px;
  box-shadow:var(--shadow);padding:.5rem;min-width:255px;display:none;z-index:20}
.nav__has:hover .nav__panel,.nav__has:focus-within .nav__panel{display:block}
.nav__panel a{display:block;padding:.55rem .7rem;font-size:.92rem}
.header__cta{display:flex;align-items:center;gap:.6rem}
.header__phone{display:inline-flex;align-items:center;gap:.45rem;font-weight:700;color:var(--navy);text-decoration:none;font-size:.95rem}
.header__phone i{color:var(--teal-700)}
.burger{display:none;background:var(--mist);border:1px solid var(--line);border-radius:10px;width:46px;height:46px;font-size:1.2rem;color:var(--navy);cursor:pointer}

/* Hero */
.hero{position:relative;color:#e9f3f1;background:linear-gradient(120deg,#0A3A52 0%,#0A6E9C 46%,#00A890 120%);overflow:hidden}
.hero::after{content:"";position:absolute;right:-8%;top:-30%;width:520px;height:520px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,rgba(0,168,144,.30),rgba(0,168,144,0) 62%);pointer-events:none}
.hero .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1.08fr .92fr;gap:48px;align-items:center;padding-top:70px;padding-bottom:78px}
.hero__eyebrow{color:var(--hl)}
.hero h1{color:#fff;font-size:clamp(2.15rem,5vw,3.4rem);font-weight:800;margin-bottom:.4em;letter-spacing:-.025em}
.hero h1 .hl{color:var(--hl)}
.hero__sub{font-size:1.15rem;color:#dcebe8;max-width:52ch;margin-bottom:1.5rem}
.hero__cta{display:flex;flex-wrap:wrap;gap:.8rem;margin-bottom:1.6rem}
.hero__chips{display:flex;flex-wrap:wrap;gap:.5rem}
.chip{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.22);
  border-radius:999px;padding:.42rem .8rem;font-size:.82rem;font-weight:600;color:#eef7f4}
.chip i{color:var(--hl)}

.hero__media{position:relative}
.hero__ph{position:relative;border-radius:22px;overflow:hidden;box-shadow:0 30px 60px -28px rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.2)}
.ph{position:relative;background:
    repeating-linear-gradient(45deg,rgba(255,255,255,.05) 0 12px,rgba(255,255,255,.09) 12px 24px),
    linear-gradient(135deg,#0A78AC,#0A7E6E);
  color:#eafaf6;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:.45rem;padding:22px}
.ph--light{background:
    repeating-linear-gradient(45deg,rgba(11,36,64,.05) 0 12px,rgba(11,36,64,.09) 12px 24px),
    linear-gradient(135deg,#E6F3FB,#E7F4F1);color:var(--teal-800)}
.ph i.ph__ico{font-size:1.9rem;opacity:.9}
.ph__label{font-weight:700;font-size:.82rem;letter-spacing:.08em;text-transform:uppercase}
.ph__meta{font-size:.75rem;opacity:.9;max-width:36ch;line-height:1.4}
.hero__ph .ph{aspect-ratio:4/3}
.matchcard{position:absolute;left:-18px;bottom:-22px;background:#fff;color:var(--ink);border-radius:16px;
  box-shadow:var(--shadow);padding:14px 16px;width:min(300px,78%);border:1px solid var(--line)}
.matchcard .mc-title{font-size:.8rem;text-transform:uppercase;letter-spacing:.1em;color:var(--teal-700);margin:0 0 .55rem;font-weight:800}
.matchcard ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:.5rem}
.matchcard li{display:flex;align-items:center;gap:.5rem;font-size:.86rem;font-weight:600;color:var(--body)}
.matchcard li i{width:26px;height:26px;display:grid;place-items:center;border-radius:8px;background:var(--mist);color:var(--teal-700);font-size:.8rem}

/* Trust bar */
.trustbar{background:var(--cream);border-bottom:1px solid var(--line)}
.trustbar .grid{display:grid;grid-template-columns:repeat(5,1fr);gap:18px}
.trust{display:flex;gap:.7rem;align-items:flex-start}
.trust i{flex:none;width:40px;height:40px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.05rem}
.trust b{display:block;color:var(--ink);font-size:.95rem;line-height:1.25}
.trust span{font-size:.83rem;color:var(--muted)}

/* Services */
.svc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:36px}
.svc{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px;box-shadow:var(--shadow-sm);transition:transform .18s ease,box-shadow .2s ease;overflow:hidden}
.svc::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:linear-gradient(var(--blue),var(--teal))}
.svc:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.svc__ico{width:52px;height:52px;display:grid;place-items:center;border-radius:13px;background:var(--mist);color:var(--teal-700);font-size:1.3rem;margin-bottom:14px}
.svc h3{margin-bottom:.4rem}
.svc p{font-size:.96rem;margin-bottom:1rem}
.svc a.svc__link{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}
.svc a.svc__link i{transition:transform .15s ease}
.svc a.svc__link:hover i{transform:translateX(3px)}
.svc-more{margin-top:22px;display:flex;flex-wrap:wrap;gap:.6rem 1.1rem;align-items:center;font-size:.95rem}
.svc-more span{font-weight:700;color:var(--ink)}
.callout{margin-top:26px;display:flex;gap:18px;align-items:center;flex-wrap:wrap;justify-content:space-between;
  background:linear-gradient(120deg,#0A3A52,#0A7E6E);color:#e9f3f1;border-radius:var(--radius);padding:24px 26px;
  border:1px solid rgba(255,255,255,.14);box-shadow:var(--shadow-sm);position:relative;overflow:hidden}
.callout::after{content:"";position:absolute;right:-40px;top:-40px;width:180px;height:180px;border-radius:50%;
  background:radial-gradient(circle,rgba(0,168,144,.32),transparent 65%)}
.callout .callout__t{position:relative;z-index:2;max-width:64ch}
.callout h3{color:#fff;margin-bottom:.25rem}
.callout p{margin:0;color:#d7e6e2;font-size:.96rem}
.callout .btn{position:relative;z-index:2}

/* Matching */
.matching{background:var(--navy);color:#e3eef1;position:relative;overflow:hidden}
.matching::before{content:"";position:absolute;inset:0;background:radial-gradient(1000px 420px at 82% -10%,rgba(0,168,144,.34),transparent 60%);pointer-events:none}
.matching .wrap{position:relative;z-index:2;display:grid;grid-template-columns:.95fr 1.05fr;gap:46px;align-items:center}
.matching h2{color:#fff}
.matching .eyebrow{color:var(--hl)}
.matching .lead{color:#c6d7db}
.match-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.match{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:14px;padding:18px}
.match i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:rgba(134,230,216,.16);color:var(--hl);font-size:1.1rem;margin-bottom:10px}
.match b{display:block;color:#fff;font-size:1rem;margin-bottom:.2rem}
.match span{font-size:.88rem;color:#bfd3d7}

/* Steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:40px;counter-reset:step}
.step{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px 22px;box-shadow:var(--shadow-sm)}
.step__n{counter-increment:step;width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:var(--amber-100);color:var(--amber-700);font-size:1.3rem;font-weight:800;margin-bottom:14px}
.step__n::before{content:counter(step)}
.step h3{font-size:1.1rem;margin-bottom:.35rem}
.step p{font-size:.92rem;margin:0}
.pill-note{margin-top:26px;display:inline-flex;align-items:center;gap:.6rem;background:var(--mist);border:1px solid var(--line);border-radius:999px;padding:.6rem 1.1rem;font-weight:600;color:var(--teal-800);font-size:.95rem}
.pill-note i{color:var(--teal-700)}

/* Coverage */
.coverage{background:var(--slate)}
.cov-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:34px}
.cov{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:28px;box-shadow:var(--shadow-sm)}
.cov__head{display:flex;align-items:center;gap:.7rem;margin-bottom:.4rem}
.cov__head i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.1rem}
.cov__head h3{margin:0}
.cov__head span{font-size:.82rem;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.08em}
.cov ul{list-style:none;padding:0;margin:.7rem 0 1rem;display:flex;flex-wrap:wrap;gap:.5rem}
.cov li{background:var(--mist);border:1px solid var(--line);border-radius:999px;font-size:.85rem;font-weight:600;color:var(--teal-800);overflow:hidden;transition:background .15s ease,border-color .15s ease}
.cov li:hover{background:var(--teal-100);border-color:var(--teal-700)}
.cov li a{display:block;padding:.32rem .75rem;color:var(--teal-800);text-decoration:none}
.cov a{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}

/* Reviews */
.rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:34px}
.rev{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm);position:relative}
.rev .quo{font-size:1.6rem;color:var(--teal);opacity:.5}
.rev p{color:var(--muted);font-size:.95rem;font-style:italic}
.rev .rev__ph{display:flex;align-items:center;gap:.7rem;margin-top:14px;border-top:1px dashed var(--line);padding-top:14px}
.rev .rev__av{width:42px;height:42px;border-radius:50%;background:var(--mist);display:grid;place-items:center;color:var(--teal-700)}
.rev .rev__meta b{display:block;color:var(--ink);font-size:.9rem}
.rev .rev__meta span{font-size:.78rem;color:var(--muted)}
.rev-note{margin-top:22px;text-align:center;font-size:.92rem;color:var(--muted)}

/* Why */
.why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:36px}
.why{display:flex;gap:.9rem;align-items:flex-start;background:var(--cream);border:1px solid var(--line);border-radius:14px;padding:22px}
.why i{flex:none;width:46px;height:46px;display:grid;place-items:center;border-radius:12px;background:var(--teal-700);color:#fff;font-size:1.1rem}
.why b{display:block;color:var(--ink);font-size:1.02rem;margin-bottom:.2rem}
.why span{font-size:.9rem;color:var(--muted)}

/* FAQ */
.faq{max-width:820px;margin:34px auto 0}
.qa{border:1px solid var(--line);border-radius:12px;margin-bottom:12px;background:#fff;overflow:hidden}
.qa__q{width:100%;text-align:left;background:none;border:0;padding:18px 20px;font-family:var(--font-body);font-weight:700;font-size:1.03rem;color:var(--ink);display:flex;justify-content:space-between;align-items:center;gap:1rem;cursor:pointer}
.qa__q i{color:var(--teal-700);transition:transform .2s ease;flex:none}
.qa__q[aria-expanded="true"] i{transform:rotate(45deg)}
.qa__a{padding:0 20px;max-height:0;overflow:hidden;transition:max-height .25s ease,padding .25s ease}
.qa__a p{margin:0 0 16px}
.qa__q[aria-expanded="true"]+.qa__a{padding:2px 20px 4px}

/* CTA + form */
.cta{background:linear-gradient(135deg,#0A3A52 0%,#0A6E9C 50%,#00A890 130%);color:#e9f3f1;position:relative;overflow:hidden}
.cta::after{content:"";position:absolute;left:-6%;bottom:-40%;width:460px;height:460px;border-radius:50%;background:radial-gradient(circle,rgba(0,168,144,.24),transparent 62%);pointer-events:none}
.cta .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
.cta h2{color:#fff}
.cta .eyebrow{color:var(--hl)}
.cta__points{list-style:none;padding:0;margin:1.2rem 0 0;display:grid;gap:.6rem}
.cta__points li{display:flex;gap:.6rem;align-items:flex-start;color:#d7e6e2;font-size:.98rem}
.cta__points i{color:var(--hl);margin-top:.2rem}
.cta__calls{display:flex;flex-wrap:wrap;gap:.7rem;margin-top:1.4rem}
.callbtn{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.24);color:#fff;text-decoration:none;border-radius:12px;padding:.7rem 1rem;font-weight:700;font-size:.95rem}
.callbtn i{color:var(--hl)}
.callbtn:hover{background:rgba(255,255,255,.18);color:#fff}
.form{background:#fff;border-radius:20px;padding:26px;box-shadow:var(--shadow);color:var(--body)}
.form h3{color:var(--ink)}
.form .fnote{font-size:.86rem;color:var(--muted);margin-bottom:1.1rem}
.field{margin-bottom:14px}
.field label{display:block;font-weight:700;font-size:.88rem;color:var(--ink);margin-bottom:.35rem}
.field input,.field select,.field textarea{width:100%;padding:.72rem .85rem;border:1.5px solid var(--line);border-radius:10px;font-family:inherit;font-size:.97rem;color:var(--ink);background:#fff}
.field input:focus,.field select:focus,.field textarea:focus{outline:3px solid rgba(14,159,142,.30);border-color:var(--teal-700)}
.field textarea{min-height:92px;resize:vertical}
.field .req{color:#b23b3b}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.form .consent{font-size:.8rem;color:var(--muted);margin:.4rem 0 1rem}
.form__msg{display:none;background:var(--sky);border:1px solid var(--blue);color:var(--deep);border-radius:10px;padding:.8rem 1rem;font-size:.9rem;font-weight:600;margin-bottom:1rem}
.form__msg.show{display:block}

/* Footer */
.footer{background:var(--navy);color:#c4d3df;font-size:.94rem}
.footer a{color:#dbe6f0;text-decoration:none}
.footer a:hover{color:#fff}
.footer__top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.2fr;gap:34px;padding:58px 0 34px}
.footer__logo{display:inline-block;background:#fff;border-radius:12px;padding:10px 14px;margin-bottom:1rem}
.footer__logo img{height:44px;width:auto;max-width:170px;object-fit:contain;display:block}
.footer p{color:#b6c7d4;font-size:.92rem}
.footer h4{color:#fff;font-size:.82rem;letter-spacing:.12em;text-transform:uppercase;margin:0 0 1rem;font-weight:800}
.footer ul{list-style:none;padding:0;margin:0;display:grid;gap:.55rem}
.footer .nap li{display:flex;gap:.6rem;align-items:flex-start;margin-bottom:.55rem}
.footer .nap i{color:var(--hl);width:18px;margin-top:.2rem;flex:none}
.footer__socials{display:flex;gap:.55rem;margin-top:1rem}
.footer__socials a{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:rgba(255,255,255,.08);color:#e7eef6}
.footer__socials a:hover{background:var(--teal-700);color:#fff}
.footer__bottom{border-top:1px solid rgba(255,255,255,.12);padding:18px 0;display:flex;flex-wrap:wrap;gap:.6rem 1.4rem;align-items:center;justify-content:space-between;font-size:.85rem;color:#9fb4c4}
.footer__bottom a{color:#c4d3df}
.footer__legal{display:flex;flex-wrap:wrap;gap:.4rem 1.2rem}

/* Mobile call bar */
.mcall{position:fixed;left:0;right:0;bottom:0;z-index:90;display:none;grid-template-columns:1fr 1fr;background:#fff;border-top:1px solid var(--line);box-shadow:0 -8px 24px -14px rgba(11,36,64,.5)}
.mcall a{display:flex;align-items:center;justify-content:center;gap:.5rem;padding:.9rem;font-weight:800;text-decoration:none;font-size:.95rem}
.mcall a.call{color:var(--navy)}
.mcall a.enq{background:var(--teal-700);color:#fff}

/* Responsive */
@media (max-width:960px){
  .hero .wrap,.matching .wrap,.cta .wrap{grid-template-columns:1fr;gap:34px}
  .hero__media{max-width:520px}
  .trustbar .grid{grid-template-columns:repeat(2,1fr)}
  .steps{grid-template-columns:1fr 1fr}
  .why-grid,.rev-grid{grid-template-columns:1fr 1fr}
  .footer__top{grid-template-columns:1fr 1fr}
  .nav,.header__phone{display:none}
  .burger{display:inline-flex;align-items:center;justify-content:center}
  .mcall{display:grid}
  body{padding-bottom:56px}
}
@media (max-width:620px){
  .section{padding:56px 0}
  .svc-grid,.match-grid,.cov-grid,.why-grid,.rev-grid,.steps,.trustbar .grid{grid-template-columns:1fr}
  .matchcard{position:static;width:100%;margin-top:14px}
  .util .wrap{justify-content:flex-start}
  .footer__top{grid-template-columns:1fr}
  h2{font-size:1.6rem}
}
.mnav{position:fixed;inset:0;z-index:120;background:rgba(6,18,32,.55);display:none}
.mnav.open{display:block}
.mnav__panel{position:absolute;top:0;right:0;height:100%;width:min(330px,86vw);background:#fff;padding:20px;overflow-y:auto;box-shadow:var(--shadow)}
.mnav__panel a{display:block;padding:.8rem .4rem;border-bottom:1px solid var(--line);color:var(--ink);text-decoration:none;font-weight:700}
.mnav__panel a.sub{padding-left:1.3rem;font-weight:600;font-size:.94rem;color:var(--body)}
.mnav__close{background:var(--mist);border:0;border-radius:10px;width:44px;height:44px;font-size:1.1rem;float:right;margin-bottom:.5rem;cursor:pointer;color:var(--navy)}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}

:root{
  /* Brand palette v5, sampled from the approved logo: blue #0088C0, teal #00A890, grey #888888 */
  --blue:#0088C0; --blue-600:#0A78AC; --blue-700:#0A6E9C; --blue-800:#0A587F; --deep:#0A3A52;
  --navy:#0A3A52; --navy-800:#0A3A52; --ink:#12303F; --grey:#888888;
  --teal:#00A890; --teal-600:#0A8E7C; --teal-700:#0A7E6E; --teal-800:#0A6357; --teal-100:#D6EFEA;
  --amber:#0A6E9C; --amber-700:#0A6E9C; --amber-100:#E6F3FB; --hl:#86E6D8;
  --cream:#F3F7F9; --mist:#E7F4F1; --sky:#E6F3FB; --slate:#EEF5F9; --line:#D3E4EC;
  --body:#33474F; --muted:#5F7178; --white:#ffffff;
  --maxw:1180px; --radius:16px; --radius-sm:10px;
  --shadow:0 18px 44px -20px rgba(10,58,82,.42); --shadow-sm:0 8px 22px -14px rgba(10,58,82,.4);
  --font-body:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --font-display:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font-body);color:var(--body);background:var(--white);
  font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3,h4{font-family:var(--font-display);color:var(--ink);line-height:1.14;margin:0 0 .5em;font-weight:800;letter-spacing:-.02em}
h2{font-size:clamp(1.7rem,3.6vw,2.5rem)}
h3{font-size:1.26rem;font-weight:700;letter-spacing:-.01em}
p{margin:0 0 1rem}
a{color:var(--teal-700);text-decoration-thickness:1px;text-underline-offset:2px}
a:hover{color:var(--teal-800)}
.vh{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.hero__sub a{color:#fff;text-decoration:underline;text-underline-offset:3px;font-weight:600}
.hero__sub a:hover{color:var(--hl)}
img{max-width:100%;display:block}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 22px}
.section{padding:76px 0}
.section--tight{padding:56px 0}
.eyebrow{display:inline-flex;align-items:center;gap:.5rem;font-weight:700;font-size:.78rem;
  letter-spacing:.14em;text-transform:uppercase;color:var(--teal-700);margin:0 0 .9rem}
.eyebrow::before{content:"";width:26px;height:2px;background:var(--amber);border-radius:2px}
.lead{font-size:1.12rem;color:var(--body);max-width:60ch}
.center{text-align:center}
.center .lead{margin-left:auto;margin-right:auto}

/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.55rem;font-weight:700;
  font-size:1rem;padding:.92rem 1.5rem;border-radius:999px;border:2px solid transparent;cursor:pointer;
  text-decoration:none;transition:transform .15s ease,background .2s ease,box-shadow .2s ease;line-height:1}
.btn:hover{transform:translateY(-2px)}
.btn--primary{background:var(--teal-700);color:#fff;box-shadow:var(--shadow-sm)}
.btn--primary:hover{background:var(--teal-800);color:#fff}
.btn--light{background:var(--cream);color:var(--navy)}
.btn--light:hover{background:#fff;color:var(--navy)}
.btn--ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn--ghost:hover{background:rgba(255,255,255,.12);color:#fff}
.btn--outline{background:transparent;color:var(--teal-700);border-color:var(--teal-700)}
.btn--outline:hover{background:var(--mist);color:var(--teal-800)}

.skip{position:absolute;left:-999px;top:0;background:var(--navy);color:#fff;padding:.7rem 1.1rem;z-index:200;border-radius:0 0 8px 0}
.skip:focus{left:0;color:#fff}

/* Utility bar */
.util{background:var(--navy);color:#cddbe8;font-size:.86rem}
.util .wrap{display:flex;flex-wrap:wrap;gap:.4rem 1.4rem;align-items:center;justify-content:space-between;padding-top:.5rem;padding-bottom:.5rem}
.util a{color:#e7eef6;text-decoration:none}
.util a:hover{color:#fff}
.util .util__group{display:flex;flex-wrap:wrap;gap:.3rem 1.3rem;align-items:center}
.util i{color:var(--hl);margin-right:.4rem}
.util__reg{font-weight:700;color:#fff}

/* Header */
.site-header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.93);backdrop-filter:saturate(1.4) blur(8px);
  border-bottom:1px solid var(--line)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding-top:.55rem;padding-bottom:.55rem}
.brand{display:inline-flex;align-items:center;text-decoration:none}
.brand img{height:56px;width:auto;max-width:210px;object-fit:contain;display:block}
.nav{display:flex;align-items:center;gap:.35rem}
.nav a{color:var(--ink);text-decoration:none;font-weight:600;font-size:.97rem;padding:.5rem .7rem;border-radius:8px}
.nav a:hover{background:var(--mist);color:var(--teal-800)}
.nav__has{position:relative}
.nav__panel{position:absolute;top:calc(100% + 6px);left:0;background:#fff;border:1px solid var(--line);border-radius:12px;
  box-shadow:var(--shadow);padding:.5rem;min-width:255px;display:none;z-index:20}
.nav__has:hover .nav__panel,.nav__has:focus-within .nav__panel{display:block}
.nav__panel a{display:block;padding:.55rem .7rem;font-size:.92rem}
.header__cta{display:flex;align-items:center;gap:.6rem}
.header__phone{display:inline-flex;align-items:center;gap:.45rem;font-weight:700;color:var(--navy);text-decoration:none;font-size:.95rem}
.header__phone i{color:var(--teal-700)}
.burger{display:none;background:var(--mist);border:1px solid var(--line);border-radius:10px;width:46px;height:46px;font-size:1.2rem;color:var(--navy);cursor:pointer}

/* Hero */
.hero{position:relative;color:#e9f3f1;background:linear-gradient(120deg,#0A3A52 0%,#0A6E9C 46%,#00A890 120%);overflow:hidden}
.hero::after{content:"";position:absolute;right:-8%;top:-30%;width:520px;height:520px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,rgba(0,168,144,.30),rgba(0,168,144,0) 62%);pointer-events:none}
.hero .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1.08fr .92fr;gap:48px;align-items:center;padding-top:70px;padding-bottom:78px}
.hero__eyebrow{color:var(--hl)}
.hero h1{color:#fff;font-size:clamp(2.15rem,5vw,3.4rem);font-weight:800;margin-bottom:.4em;letter-spacing:-.025em}
.hero h1 .hl{color:var(--hl)}
.hero__sub{font-size:1.15rem;color:#dcebe8;max-width:52ch;margin-bottom:1.5rem}
.hero__cta{display:flex;flex-wrap:wrap;gap:.8rem;margin-bottom:1.6rem}
.hero__chips{display:flex;flex-wrap:wrap;gap:.5rem}
.chip{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.22);
  border-radius:999px;padding:.42rem .8rem;font-size:.82rem;font-weight:600;color:#eef7f4}
.chip i{color:var(--hl)}

.hero__media{position:relative}
.hero__ph{position:relative;border-radius:22px;overflow:hidden;box-shadow:0 30px 60px -28px rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.2)}
.ph{position:relative;background:
    repeating-linear-gradient(45deg,rgba(255,255,255,.05) 0 12px,rgba(255,255,255,.09) 12px 24px),
    linear-gradient(135deg,#0A78AC,#0A7E6E);
  color:#eafaf6;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:.45rem;padding:22px}
.ph--light{background:
    repeating-linear-gradient(45deg,rgba(11,36,64,.05) 0 12px,rgba(11,36,64,.09) 12px 24px),
    linear-gradient(135deg,#E6F3FB,#E7F4F1);color:var(--teal-800)}
.ph i.ph__ico{font-size:1.9rem;opacity:.9}
.ph__label{font-weight:700;font-size:.82rem;letter-spacing:.08em;text-transform:uppercase}
.ph__meta{font-size:.75rem;opacity:.9;max-width:36ch;line-height:1.4}
.hero__ph .ph{aspect-ratio:4/3}
.matchcard{position:absolute;left:-18px;bottom:-22px;background:#fff;color:var(--ink);border-radius:16px;
  box-shadow:var(--shadow);padding:14px 16px;width:min(300px,78%);border:1px solid var(--line)}
.matchcard .mc-title{font-size:.8rem;text-transform:uppercase;letter-spacing:.1em;color:var(--teal-700);margin:0 0 .55rem;font-weight:800}
.matchcard ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:.5rem}
.matchcard li{display:flex;align-items:center;gap:.5rem;font-size:.86rem;font-weight:600;color:var(--body)}
.matchcard li i{width:26px;height:26px;display:grid;place-items:center;border-radius:8px;background:var(--mist);color:var(--teal-700);font-size:.8rem}

/* Trust bar */
.trustbar{background:var(--cream);border-bottom:1px solid var(--line)}
.trustbar .grid{display:grid;grid-template-columns:repeat(5,1fr);gap:18px}
.trust{display:flex;gap:.7rem;align-items:flex-start}
.trust i{flex:none;width:40px;height:40px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.05rem}
.trust b{display:block;color:var(--ink);font-size:.95rem;line-height:1.25}
.trust span{font-size:.83rem;color:var(--muted)}

/* Services */
.svc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:36px}
.svc{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px;box-shadow:var(--shadow-sm);transition:transform .18s ease,box-shadow .2s ease;overflow:hidden}
.svc::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:linear-gradient(var(--blue),var(--teal))}
.svc:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.svc__ico{width:52px;height:52px;display:grid;place-items:center;border-radius:13px;background:var(--mist);color:var(--teal-700);font-size:1.3rem;margin-bottom:14px}
.svc h3{margin-bottom:.4rem}
.svc p{font-size:.96rem;margin-bottom:1rem}
.svc a.svc__link{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}
.svc a.svc__link i{transition:transform .15s ease}
.svc a.svc__link:hover i{transform:translateX(3px)}
.svc-more{margin-top:22px;display:flex;flex-wrap:wrap;gap:.6rem 1.1rem;align-items:center;font-size:.95rem}
.svc-more span{font-weight:700;color:var(--ink)}
.callout{margin-top:26px;display:flex;gap:18px;align-items:center;flex-wrap:wrap;justify-content:space-between;
  background:linear-gradient(120deg,#0A3A52,#0A7E6E);color:#e9f3f1;border-radius:var(--radius);padding:24px 26px;
  border:1px solid rgba(255,255,255,.14);box-shadow:var(--shadow-sm);position:relative;overflow:hidden}
.callout::after{content:"";position:absolute;right:-40px;top:-40px;width:180px;height:180px;border-radius:50%;
  background:radial-gradient(circle,rgba(0,168,144,.32),transparent 65%)}
.callout .callout__t{position:relative;z-index:2;max-width:64ch}
.callout h3{color:#fff;margin-bottom:.25rem}
.callout p{margin:0;color:#d7e6e2;font-size:.96rem}
.callout .btn{position:relative;z-index:2}

/* Matching */
.matching{background:var(--navy);color:#e3eef1;position:relative;overflow:hidden}
.matching::before{content:"";position:absolute;inset:0;background:radial-gradient(1000px 420px at 82% -10%,rgba(0,168,144,.34),transparent 60%);pointer-events:none}
.matching .wrap{position:relative;z-index:2;display:grid;grid-template-columns:.95fr 1.05fr;gap:46px;align-items:center}
.matching h2{color:#fff}
.matching .eyebrow{color:var(--hl)}
.matching .lead{color:#c6d7db}
.match-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.match{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:14px;padding:18px}
.match i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:rgba(134,230,216,.16);color:var(--hl);font-size:1.1rem;margin-bottom:10px}
.match b{display:block;color:#fff;font-size:1rem;margin-bottom:.2rem}
.match span{font-size:.88rem;color:#bfd3d7}

/* Steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:40px;counter-reset:step}
.step{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px 22px;box-shadow:var(--shadow-sm)}
.step__n{counter-increment:step;width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:var(--amber-100);color:var(--amber-700);font-size:1.3rem;font-weight:800;margin-bottom:14px}
.step__n::before{content:counter(step)}
.step h3{font-size:1.1rem;margin-bottom:.35rem}
.step p{font-size:.92rem;margin:0}
.pill-note{margin-top:26px;display:inline-flex;align-items:center;gap:.6rem;background:var(--mist);border:1px solid var(--line);border-radius:999px;padding:.6rem 1.1rem;font-weight:600;color:var(--teal-800);font-size:.95rem}
.pill-note i{color:var(--teal-700)}

/* Coverage */
.coverage{background:var(--slate)}
.cov-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:34px}
.cov{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:28px;box-shadow:var(--shadow-sm)}
.cov__head{display:flex;align-items:center;gap:.7rem;margin-bottom:.4rem}
.cov__head i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.1rem}
.cov__head h3{margin:0}
.cov__head span{font-size:.82rem;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.08em}
.cov ul{list-style:none;padding:0;margin:.7rem 0 1rem;display:flex;flex-wrap:wrap;gap:.5rem}
.cov li{background:var(--mist);border:1px solid var(--line);border-radius:999px;font-size:.85rem;font-weight:600;color:var(--teal-800);overflow:hidden;transition:background .15s ease,border-color .15s ease}
.cov li:hover{background:var(--teal-100);border-color:var(--teal-700)}
.cov li a{display:block;padding:.32rem .75rem;color:var(--teal-800);text-decoration:none}
.cov a{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}

/* Reviews */
.rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:34px}
.rev{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm);position:relative}
.rev .quo{font-size:1.6rem;color:var(--teal);opacity:.5}
.rev p{color:var(--muted);font-size:.95rem;font-style:italic}
.rev .rev__ph{display:flex;align-items:center;gap:.7rem;margin-top:14px;border-top:1px dashed var(--line);padding-top:14px}
.rev .rev__av{width:42px;height:42px;border-radius:50%;background:var(--mist);display:grid;place-items:center;color:var(--teal-700)}
.rev .rev__meta b{display:block;color:var(--ink);font-size:.9rem}
.rev .rev__meta span{font-size:.78rem;color:var(--muted)}
.rev-note{margin-top:22px;text-align:center;font-size:.92rem;color:var(--muted)}

/* Why */
.why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:36px}
.why{display:flex;gap:.9rem;align-items:flex-start;background:var(--cream);border:1px solid var(--line);border-radius:14px;padding:22px}
.why i{flex:none;width:46px;height:46px;display:grid;place-items:center;border-radius:12px;background:var(--teal-700);color:#fff;font-size:1.1rem}
.why b{display:block;color:var(--ink);font-size:1.02rem;margin-bottom:.2rem}
.why span{font-size:.9rem;color:var(--muted)}

/* FAQ */
.faq{max-width:820px;margin:34px auto 0}
.qa{border:1px solid var(--line);border-radius:12px;margin-bottom:12px;background:#fff;overflow:hidden}
.qa__q{width:100%;text-align:left;background:none;border:0;padding:18px 20px;font-family:var(--font-body);font-weight:700;font-size:1.03rem;color:var(--ink);display:flex;justify-content:space-between;align-items:center;gap:1rem;cursor:pointer}
.qa__q i{color:var(--teal-700);transition:transform .2s ease;flex:none}
.qa__q[aria-expanded="true"] i{transform:rotate(45deg)}
.qa__a{padding:0 20px;max-height:0;overflow:hidden;transition:max-height .25s ease,padding .25s ease}
.qa__a p{margin:0 0 16px}
.qa__q[aria-expanded="true"]+.qa__a{padding:2px 20px 4px}

/* CTA + form */
.cta{background:linear-gradient(135deg,#0A3A52 0%,#0A6E9C 50%,#00A890 130%);color:#e9f3f1;position:relative;overflow:hidden}
.cta::after{content:"";position:absolute;left:-6%;bottom:-40%;width:460px;height:460px;border-radius:50%;background:radial-gradient(circle,rgba(0,168,144,.24),transparent 62%);pointer-events:none}
.cta .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
.cta h2{color:#fff}
.cta .eyebrow{color:var(--hl)}
.cta__points{list-style:none;padding:0;margin:1.2rem 0 0;display:grid;gap:.6rem}
.cta__points li{display:flex;gap:.6rem;align-items:flex-start;color:#d7e6e2;font-size:.98rem}
.cta__points i{color:var(--hl);margin-top:.2rem}
.cta__calls{display:flex;flex-wrap:wrap;gap:.7rem;margin-top:1.4rem}
.callbtn{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.24);color:#fff;text-decoration:none;border-radius:12px;padding:.7rem 1rem;font-weight:700;font-size:.95rem}
.callbtn i{color:var(--hl)}
.callbtn:hover{background:rgba(255,255,255,.18);color:#fff}
.form{background:#fff;border-radius:20px;padding:26px;box-shadow:var(--shadow);color:var(--body)}
.form h3{color:var(--ink)}
.form .fnote{font-size:.86rem;color:var(--muted);margin-bottom:1.1rem}
.field{margin-bottom:14px}
.field label{display:block;font-weight:700;font-size:.88rem;color:var(--ink);margin-bottom:.35rem}
.field input,.field select,.field textarea{width:100%;padding:.72rem .85rem;border:1.5px solid var(--line);border-radius:10px;font-family:inherit;font-size:.97rem;color:var(--ink);background:#fff}
.field input:focus,.field select:focus,.field textarea:focus{outline:3px solid rgba(14,159,142,.30);border-color:var(--teal-700)}
.field textarea{min-height:92px;resize:vertical}
.field .req{color:#b23b3b}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.form .consent{font-size:.8rem;color:var(--muted);margin:.4rem 0 1rem}
.form__msg{display:none;background:var(--sky);border:1px solid var(--blue);color:var(--deep);border-radius:10px;padding:.8rem 1rem;font-size:.9rem;font-weight:600;margin-bottom:1rem}
.form__msg.show{display:block}

/* Footer */
.footer{background:var(--navy);color:#c4d3df;font-size:.94rem}
.footer a{color:#dbe6f0;text-decoration:none}
.footer a:hover{color:#fff}
.footer__top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.2fr;gap:34px;padding:58px 0 34px}
.footer__logo{display:inline-block;background:#fff;border-radius:12px;padding:10px 14px;margin-bottom:1rem}
.footer__logo img{height:44px;width:auto;max-width:170px;object-fit:contain;display:block}
.footer p{color:#b6c7d4;font-size:.92rem}
.footer h4{color:#fff;font-size:.82rem;letter-spacing:.12em;text-transform:uppercase;margin:0 0 1rem;font-weight:800}
.footer ul{list-style:none;padding:0;margin:0;display:grid;gap:.55rem}
.footer .nap li{display:flex;gap:.6rem;align-items:flex-start;margin-bottom:.55rem}
.footer .nap i{color:var(--hl);width:18px;margin-top:.2rem;flex:none}
.footer__socials{display:flex;gap:.55rem;margin-top:1rem}
.footer__socials a{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:rgba(255,255,255,.08);color:#e7eef6}
.footer__socials a:hover{background:var(--teal-700);color:#fff}
.footer__bottom{border-top:1px solid rgba(255,255,255,.12);padding:18px 0;display:flex;flex-wrap:wrap;gap:.6rem 1.4rem;align-items:center;justify-content:space-between;font-size:.85rem;color:#9fb4c4}
.footer__bottom a{color:#c4d3df}
.footer__legal{display:flex;flex-wrap:wrap;gap:.4rem 1.2rem}

/* Mobile call bar */
.mcall{position:fixed;left:0;right:0;bottom:0;z-index:90;display:none;grid-template-columns:1fr 1fr;background:#fff;border-top:1px solid var(--line);box-shadow:0 -8px 24px -14px rgba(11,36,64,.5)}
.mcall a{display:flex;align-items:center;justify-content:center;gap:.5rem;padding:.9rem;font-weight:800;text-decoration:none;font-size:.95rem}
.mcall a.call{color:var(--navy)}
.mcall a.enq{background:var(--teal-700);color:#fff}

/* Responsive */
@media (max-width:960px){
  .hero .wrap,.matching .wrap,.cta .wrap{grid-template-columns:1fr;gap:34px}
  .hero__media{max-width:520px}
  .trustbar .grid{grid-template-columns:repeat(2,1fr)}
  .steps{grid-template-columns:1fr 1fr}
  .why-grid,.rev-grid{grid-template-columns:1fr 1fr}
  .footer__top{grid-template-columns:1fr 1fr}
  .nav,.header__phone{display:none}
  .burger{display:inline-flex;align-items:center;justify-content:center}
  .mcall{display:grid}
  body{padding-bottom:56px}
}
@media (max-width:620px){
  .section{padding:56px 0}
  .svc-grid,.match-grid,.cov-grid,.why-grid,.rev-grid,.steps,.trustbar .grid{grid-template-columns:1fr}
  .matchcard{position:static;width:100%;margin-top:14px}
  .util .wrap{justify-content:flex-start}
  .footer__top{grid-template-columns:1fr}
  h2{font-size:1.6rem}
}
.mnav{position:fixed;inset:0;z-index:120;background:rgba(6,18,32,.55);display:none}
.mnav.open{display:block}
.mnav__panel{position:absolute;top:0;right:0;height:100%;width:min(330px,86vw);background:#fff;padding:20px;overflow-y:auto;box-shadow:var(--shadow)}
.mnav__panel a{display:block;padding:.8rem .4rem;border-bottom:1px solid var(--line);color:var(--ink);text-decoration:none;font-weight:700}
.mnav__panel a.sub{padding-left:1.3rem;font-weight:600;font-size:.94rem;color:var(--body)}
.mnav__close{background:var(--mist);border:0;border-radius:10px;width:44px;height:44px;font-size:1.1rem;float:right;margin-bottom:.5rem;cursor:pointer;color:var(--navy)}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}

:root{
  /* Brand palette v5, sampled from the approved logo: blue #0088C0, teal #00A890, grey #888888 */
  --blue:#0088C0; --blue-600:#0A78AC; --blue-700:#0A6E9C; --blue-800:#0A587F; --deep:#0A3A52;
  --navy:#0A3A52; --navy-800:#0A3A52; --ink:#12303F; --grey:#888888;
  --teal:#00A890; --teal-600:#0A8E7C; --teal-700:#0A7E6E; --teal-800:#0A6357; --teal-100:#D6EFEA;
  --amber:#0A6E9C; --amber-700:#0A6E9C; --amber-100:#E6F3FB; --hl:#86E6D8;
  --cream:#F3F7F9; --mist:#E7F4F1; --sky:#E6F3FB; --slate:#EEF5F9; --line:#D3E4EC;
  --body:#33474F; --muted:#5F7178; --white:#ffffff;
  --maxw:1180px; --radius:16px; --radius-sm:10px;
  --shadow:0 18px 44px -20px rgba(10,58,82,.42); --shadow-sm:0 8px 22px -14px rgba(10,58,82,.4);
  --font-body:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --font-display:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font-body);color:var(--body);background:var(--white);
  font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3,h4{font-family:var(--font-display);color:var(--ink);line-height:1.14;margin:0 0 .5em;font-weight:800;letter-spacing:-.02em}
h2{font-size:clamp(1.7rem,3.6vw,2.5rem)}
h3{font-size:1.26rem;font-weight:700;letter-spacing:-.01em}
p{margin:0 0 1rem}
a{color:var(--teal-700);text-decoration-thickness:1px;text-underline-offset:2px}
a:hover{color:var(--teal-800)}
.vh{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.hero__sub a{color:#fff;text-decoration:underline;text-underline-offset:3px;font-weight:600}
.hero__sub a:hover{color:var(--hl)}
img{max-width:100%;display:block}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 22px}
.section{padding:76px 0}
.section--tight{padding:56px 0}
.eyebrow{display:inline-flex;align-items:center;gap:.5rem;font-weight:700;font-size:.78rem;
  letter-spacing:.14em;text-transform:uppercase;color:var(--teal-700);margin:0 0 .9rem}
.eyebrow::before{content:"";width:26px;height:2px;background:var(--amber);border-radius:2px}
.lead{font-size:1.12rem;color:var(--body);max-width:60ch}
.center{text-align:center}
.center .lead{margin-left:auto;margin-right:auto}

/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.55rem;font-weight:700;
  font-size:1rem;padding:.92rem 1.5rem;border-radius:999px;border:2px solid transparent;cursor:pointer;
  text-decoration:none;transition:transform .15s ease,background .2s ease,box-shadow .2s ease;line-height:1}
.btn:hover{transform:translateY(-2px)}
.btn--primary{background:var(--teal-700);color:#fff;box-shadow:var(--shadow-sm)}
.btn--primary:hover{background:var(--teal-800);color:#fff}
.btn--light{background:var(--cream);color:var(--navy)}
.btn--light:hover{background:#fff;color:var(--navy)}
.btn--ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn--ghost:hover{background:rgba(255,255,255,.12);color:#fff}
.btn--outline{background:transparent;color:var(--teal-700);border-color:var(--teal-700)}
.btn--outline:hover{background:var(--mist);color:var(--teal-800)}

.skip{position:absolute;left:-999px;top:0;background:var(--navy);color:#fff;padding:.7rem 1.1rem;z-index:200;border-radius:0 0 8px 0}
.skip:focus{left:0;color:#fff}

/* Utility bar */
.util{background:var(--navy);color:#cddbe8;font-size:.86rem}
.util .wrap{display:flex;flex-wrap:wrap;gap:.4rem 1.4rem;align-items:center;justify-content:space-between;padding-top:.5rem;padding-bottom:.5rem}
.util a{color:#e7eef6;text-decoration:none}
.util a:hover{color:#fff}
.util .util__group{display:flex;flex-wrap:wrap;gap:.3rem 1.3rem;align-items:center}
.util i{color:var(--hl);margin-right:.4rem}
.util__reg{font-weight:700;color:#fff}

/* Header */
.site-header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.93);backdrop-filter:saturate(1.4) blur(8px);
  border-bottom:1px solid var(--line)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding-top:.55rem;padding-bottom:.55rem}
.brand{display:inline-flex;align-items:center;text-decoration:none}
.brand img{height:56px;width:auto;max-width:210px;object-fit:contain;display:block}
.nav{display:flex;align-items:center;gap:.35rem}
.nav a{color:var(--ink);text-decoration:none;font-weight:600;font-size:.97rem;padding:.5rem .7rem;border-radius:8px}
.nav a:hover{background:var(--mist);color:var(--teal-800)}
.nav__has{position:relative}
.nav__panel{position:absolute;top:calc(100% + 6px);left:0;background:#fff;border:1px solid var(--line);border-radius:12px;
  box-shadow:var(--shadow);padding:.5rem;min-width:255px;display:none;z-index:20}
.nav__has:hover .nav__panel,.nav__has:focus-within .nav__panel{display:block}
.nav__panel a{display:block;padding:.55rem .7rem;font-size:.92rem}
.header__cta{display:flex;align-items:center;gap:.6rem}
.header__phone{display:inline-flex;align-items:center;gap:.45rem;font-weight:700;color:var(--navy);text-decoration:none;font-size:.95rem}
.header__phone i{color:var(--teal-700)}
.burger{display:none;background:var(--mist);border:1px solid var(--line);border-radius:10px;width:46px;height:46px;font-size:1.2rem;color:var(--navy);cursor:pointer}

/* Hero */
.hero{position:relative;color:#e9f3f1;background:linear-gradient(120deg,#0A3A52 0%,#0A6E9C 46%,#00A890 120%);overflow:hidden}
.hero::after{content:"";position:absolute;right:-8%;top:-30%;width:520px;height:520px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,rgba(0,168,144,.30),rgba(0,168,144,0) 62%);pointer-events:none}
.hero .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1.08fr .92fr;gap:48px;align-items:center;padding-top:70px;padding-bottom:78px}
.hero__eyebrow{color:var(--hl)}
.hero h1{color:#fff;font-size:clamp(2.15rem,5vw,3.4rem);font-weight:800;margin-bottom:.4em;letter-spacing:-.025em}
.hero h1 .hl{color:var(--hl)}
.hero__sub{font-size:1.15rem;color:#dcebe8;max-width:52ch;margin-bottom:1.5rem}
.hero__cta{display:flex;flex-wrap:wrap;gap:.8rem;margin-bottom:1.6rem}
.hero__chips{display:flex;flex-wrap:wrap;gap:.5rem}
.chip{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.22);
  border-radius:999px;padding:.42rem .8rem;font-size:.82rem;font-weight:600;color:#eef7f4}
.chip i{color:var(--hl)}

.hero__media{position:relative}
.hero__ph{position:relative;border-radius:22px;overflow:hidden;box-shadow:0 30px 60px -28px rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.2)}
.ph{position:relative;background:
    repeating-linear-gradient(45deg,rgba(255,255,255,.05) 0 12px,rgba(255,255,255,.09) 12px 24px),
    linear-gradient(135deg,#0A78AC,#0A7E6E);
  color:#eafaf6;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:.45rem;padding:22px}
.ph--light{background:
    repeating-linear-gradient(45deg,rgba(11,36,64,.05) 0 12px,rgba(11,36,64,.09) 12px 24px),
    linear-gradient(135deg,#E6F3FB,#E7F4F1);color:var(--teal-800)}
.ph i.ph__ico{font-size:1.9rem;opacity:.9}
.ph__label{font-weight:700;font-size:.82rem;letter-spacing:.08em;text-transform:uppercase}
.ph__meta{font-size:.75rem;opacity:.9;max-width:36ch;line-height:1.4}
.hero__ph .ph{aspect-ratio:4/3}
.matchcard{position:absolute;left:-18px;bottom:-22px;background:#fff;color:var(--ink);border-radius:16px;
  box-shadow:var(--shadow);padding:14px 16px;width:min(300px,78%);border:1px solid var(--line)}
.matchcard .mc-title{font-size:.8rem;text-transform:uppercase;letter-spacing:.1em;color:var(--teal-700);margin:0 0 .55rem;font-weight:800}
.matchcard ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:.5rem}
.matchcard li{display:flex;align-items:center;gap:.5rem;font-size:.86rem;font-weight:600;color:var(--body)}
.matchcard li i{width:26px;height:26px;display:grid;place-items:center;border-radius:8px;background:var(--mist);color:var(--teal-700);font-size:.8rem}

/* Trust bar */
.trustbar{background:var(--cream);border-bottom:1px solid var(--line)}
.trustbar .grid{display:grid;grid-template-columns:repeat(5,1fr);gap:18px}
.trust{display:flex;gap:.7rem;align-items:flex-start}
.trust i{flex:none;width:40px;height:40px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.05rem}
.trust b{display:block;color:var(--ink);font-size:.95rem;line-height:1.25}
.trust span{font-size:.83rem;color:var(--muted)}

/* Services */
.svc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:36px}
.svc{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px;box-shadow:var(--shadow-sm);transition:transform .18s ease,box-shadow .2s ease;overflow:hidden}
.svc::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:linear-gradient(var(--blue),var(--teal))}
.svc:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.svc__ico{width:52px;height:52px;display:grid;place-items:center;border-radius:13px;background:var(--mist);color:var(--teal-700);font-size:1.3rem;margin-bottom:14px}
.svc h3{margin-bottom:.4rem}
.svc p{font-size:.96rem;margin-bottom:1rem}
.svc a.svc__link{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}
.svc a.svc__link i{transition:transform .15s ease}
.svc a.svc__link:hover i{transform:translateX(3px)}
.svc-more{margin-top:22px;display:flex;flex-wrap:wrap;gap:.6rem 1.1rem;align-items:center;font-size:.95rem}
.svc-more span{font-weight:700;color:var(--ink)}
.callout{margin-top:26px;display:flex;gap:18px;align-items:center;flex-wrap:wrap;justify-content:space-between;
  background:linear-gradient(120deg,#0A3A52,#0A7E6E);color:#e9f3f1;border-radius:var(--radius);padding:24px 26px;
  border:1px solid rgba(255,255,255,.14);box-shadow:var(--shadow-sm);position:relative;overflow:hidden}
.callout::after{content:"";position:absolute;right:-40px;top:-40px;width:180px;height:180px;border-radius:50%;
  background:radial-gradient(circle,rgba(0,168,144,.32),transparent 65%)}
.callout .callout__t{position:relative;z-index:2;max-width:64ch}
.callout h3{color:#fff;margin-bottom:.25rem}
.callout p{margin:0;color:#d7e6e2;font-size:.96rem}
.callout .btn{position:relative;z-index:2}

/* Matching */
.matching{background:var(--navy);color:#e3eef1;position:relative;overflow:hidden}
.matching::before{content:"";position:absolute;inset:0;background:radial-gradient(1000px 420px at 82% -10%,rgba(0,168,144,.34),transparent 60%);pointer-events:none}
.matching .wrap{position:relative;z-index:2;display:grid;grid-template-columns:.95fr 1.05fr;gap:46px;align-items:center}
.matching h2{color:#fff}
.matching .eyebrow{color:var(--hl)}
.matching .lead{color:#c6d7db}
.match-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.match{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:14px;padding:18px}
.match i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:rgba(134,230,216,.16);color:var(--hl);font-size:1.1rem;margin-bottom:10px}
.match b{display:block;color:#fff;font-size:1rem;margin-bottom:.2rem}
.match span{font-size:.88rem;color:#bfd3d7}

/* Steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:40px;counter-reset:step}
.step{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px 22px;box-shadow:var(--shadow-sm)}
.step__n{counter-increment:step;width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:var(--amber-100);color:var(--amber-700);font-size:1.3rem;font-weight:800;margin-bottom:14px}
.step__n::before{content:counter(step)}
.step h3{font-size:1.1rem;margin-bottom:.35rem}
.step p{font-size:.92rem;margin:0}
.pill-note{margin-top:26px;display:inline-flex;align-items:center;gap:.6rem;background:var(--mist);border:1px solid var(--line);border-radius:999px;padding:.6rem 1.1rem;font-weight:600;color:var(--teal-800);font-size:.95rem}
.pill-note i{color:var(--teal-700)}

/* Coverage */
.coverage{background:var(--slate)}
.cov-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:34px}
.cov{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:28px;box-shadow:var(--shadow-sm)}
.cov__head{display:flex;align-items:center;gap:.7rem;margin-bottom:.4rem}
.cov__head i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.1rem}
.cov__head h3{margin:0}
.cov__head span{font-size:.82rem;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.08em}
.cov ul{list-style:none;padding:0;margin:.7rem 0 1rem;display:flex;flex-wrap:wrap;gap:.5rem}
.cov li{background:var(--mist);border:1px solid var(--line);border-radius:999px;font-size:.85rem;font-weight:600;color:var(--teal-800);overflow:hidden;transition:background .15s ease,border-color .15s ease}
.cov li:hover{background:var(--teal-100);border-color:var(--teal-700)}
.cov li a{display:block;padding:.32rem .75rem;color:var(--teal-800);text-decoration:none}
.cov a{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}

/* Reviews */
.rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:34px}
.rev{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm);position:relative}
.rev .quo{font-size:1.6rem;color:var(--teal);opacity:.5}
.rev p{color:var(--muted);font-size:.95rem;font-style:italic}
.rev .rev__ph{display:flex;align-items:center;gap:.7rem;margin-top:14px;border-top:1px dashed var(--line);padding-top:14px}
.rev .rev__av{width:42px;height:42px;border-radius:50%;background:var(--mist);display:grid;place-items:center;color:var(--teal-700)}
.rev .rev__meta b{display:block;color:var(--ink);font-size:.9rem}
.rev .rev__meta span{font-size:.78rem;color:var(--muted)}
.rev-note{margin-top:22px;text-align:center;font-size:.92rem;color:var(--muted)}

/* Why */
.why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:36px}
.why{display:flex;gap:.9rem;align-items:flex-start;background:var(--cream);border:1px solid var(--line);border-radius:14px;padding:22px}
.why i{flex:none;width:46px;height:46px;display:grid;place-items:center;border-radius:12px;background:var(--teal-700);color:#fff;font-size:1.1rem}
.why b{display:block;color:var(--ink);font-size:1.02rem;margin-bottom:.2rem}
.why span{font-size:.9rem;color:var(--muted)}

/* FAQ */
.faq{max-width:820px;margin:34px auto 0}
.qa{border:1px solid var(--line);border-radius:12px;margin-bottom:12px;background:#fff;overflow:hidden}
.qa__q{width:100%;text-align:left;background:none;border:0;padding:18px 20px;font-family:var(--font-body);font-weight:700;font-size:1.03rem;color:var(--ink);display:flex;justify-content:space-between;align-items:center;gap:1rem;cursor:pointer}
.qa__q i{color:var(--teal-700);transition:transform .2s ease;flex:none}
.qa__q[aria-expanded="true"] i{transform:rotate(45deg)}
.qa__a{padding:0 20px;max-height:0;overflow:hidden;transition:max-height .25s ease,padding .25s ease}
.qa__a p{margin:0 0 16px}
.qa__q[aria-expanded="true"]+.qa__a{padding:2px 20px 4px}

/* CTA + form */
.cta{background:linear-gradient(135deg,#0A3A52 0%,#0A6E9C 50%,#00A890 130%);color:#e9f3f1;position:relative;overflow:hidden}
.cta::after{content:"";position:absolute;left:-6%;bottom:-40%;width:460px;height:460px;border-radius:50%;background:radial-gradient(circle,rgba(0,168,144,.24),transparent 62%);pointer-events:none}
.cta .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
.cta h2{color:#fff}
.cta .eyebrow{color:var(--hl)}
.cta__points{list-style:none;padding:0;margin:1.2rem 0 0;display:grid;gap:.6rem}
.cta__points li{display:flex;gap:.6rem;align-items:flex-start;color:#d7e6e2;font-size:.98rem}
.cta__points i{color:var(--hl);margin-top:.2rem}
.cta__calls{display:flex;flex-wrap:wrap;gap:.7rem;margin-top:1.4rem}
.callbtn{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.24);color:#fff;text-decoration:none;border-radius:12px;padding:.7rem 1rem;font-weight:700;font-size:.95rem}
.callbtn i{color:var(--hl)}
.callbtn:hover{background:rgba(255,255,255,.18);color:#fff}
.form{background:#fff;border-radius:20px;padding:26px;box-shadow:var(--shadow);color:var(--body)}
.form h3{color:var(--ink)}
.form .fnote{font-size:.86rem;color:var(--muted);margin-bottom:1.1rem}
.field{margin-bottom:14px}
.field label{display:block;font-weight:700;font-size:.88rem;color:var(--ink);margin-bottom:.35rem}
.field input,.field select,.field textarea{width:100%;padding:.72rem .85rem;border:1.5px solid var(--line);border-radius:10px;font-family:inherit;font-size:.97rem;color:var(--ink);background:#fff}
.field input:focus,.field select:focus,.field textarea:focus{outline:3px solid rgba(14,159,142,.30);border-color:var(--teal-700)}
.field textarea{min-height:92px;resize:vertical}
.field .req{color:#b23b3b}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.form .consent{font-size:.8rem;color:var(--muted);margin:.4rem 0 1rem}
.form__msg{display:none;background:var(--sky);border:1px solid var(--blue);color:var(--deep);border-radius:10px;padding:.8rem 1rem;font-size:.9rem;font-weight:600;margin-bottom:1rem}
.form__msg.show{display:block}

/* Footer */
.footer{background:var(--navy);color:#c4d3df;font-size:.94rem}
.footer a{color:#dbe6f0;text-decoration:none}
.footer a:hover{color:#fff}
.footer__top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.2fr;gap:34px;padding:58px 0 34px}
.footer__logo{display:inline-block;background:#fff;border-radius:12px;padding:10px 14px;margin-bottom:1rem}
.footer__logo img{height:44px;width:auto;max-width:170px;object-fit:contain;display:block}
.footer p{color:#b6c7d4;font-size:.92rem}
.footer h4{color:#fff;font-size:.82rem;letter-spacing:.12em;text-transform:uppercase;margin:0 0 1rem;font-weight:800}
.footer ul{list-style:none;padding:0;margin:0;display:grid;gap:.55rem}
.footer .nap li{display:flex;gap:.6rem;align-items:flex-start;margin-bottom:.55rem}
.footer .nap i{color:var(--hl);width:18px;margin-top:.2rem;flex:none}
.footer__socials{display:flex;gap:.55rem;margin-top:1rem}
.footer__socials a{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:rgba(255,255,255,.08);color:#e7eef6}
.footer__socials a:hover{background:var(--teal-700);color:#fff}
.footer__bottom{border-top:1px solid rgba(255,255,255,.12);padding:18px 0;display:flex;flex-wrap:wrap;gap:.6rem 1.4rem;align-items:center;justify-content:space-between;font-size:.85rem;color:#9fb4c4}
.footer__bottom a{color:#c4d3df}
.footer__legal{display:flex;flex-wrap:wrap;gap:.4rem 1.2rem}

/* Mobile call bar */
.mcall{position:fixed;left:0;right:0;bottom:0;z-index:90;display:none;grid-template-columns:1fr 1fr;background:#fff;border-top:1px solid var(--line);box-shadow:0 -8px 24px -14px rgba(11,36,64,.5)}
.mcall a{display:flex;align-items:center;justify-content:center;gap:.5rem;padding:.9rem;font-weight:800;text-decoration:none;font-size:.95rem}
.mcall a.call{color:var(--navy)}
.mcall a.enq{background:var(--teal-700);color:#fff}

/* Responsive */
@media (max-width:960px){
  .hero .wrap,.matching .wrap,.cta .wrap{grid-template-columns:1fr;gap:34px}
  .hero__media{max-width:520px}
  .trustbar .grid{grid-template-columns:repeat(2,1fr)}
  .steps{grid-template-columns:1fr 1fr}
  .why-grid,.rev-grid{grid-template-columns:1fr 1fr}
  .footer__top{grid-template-columns:1fr 1fr}
  .nav,.header__phone{display:none}
  .burger{display:inline-flex;align-items:center;justify-content:center}
  .mcall{display:grid}
  body{padding-bottom:56px}
}
@media (max-width:620px){
  .section{padding:56px 0}
  .svc-grid,.match-grid,.cov-grid,.why-grid,.rev-grid,.steps,.trustbar .grid{grid-template-columns:1fr}
  .matchcard{position:static;width:100%;margin-top:14px}
  .util .wrap{justify-content:flex-start}
  .footer__top{grid-template-columns:1fr}
  h2{font-size:1.6rem}
}
.mnav{position:fixed;inset:0;z-index:120;background:rgba(6,18,32,.55);display:none}
.mnav.open{display:block}
.mnav__panel{position:absolute;top:0;right:0;height:100%;width:min(330px,86vw);background:#fff;padding:20px;overflow-y:auto;box-shadow:var(--shadow)}
.mnav__panel a{display:block;padding:.8rem .4rem;border-bottom:1px solid var(--line);color:var(--ink);text-decoration:none;font-weight:700}
.mnav__panel a.sub{padding-left:1.3rem;font-weight:600;font-size:.94rem;color:var(--body)}
.mnav__close{background:var(--mist);border:0;border-radius:10px;width:44px;height:44px;font-size:1.1rem;float:right;margin-bottom:.5rem;cursor:pointer;color:var(--navy)}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}

:root{
  /* Brand palette v5, sampled from the approved logo: blue #0088C0, teal #00A890, grey #888888 */
  --blue:#0088C0; --blue-600:#0A78AC; --blue-700:#0A6E9C; --blue-800:#0A587F; --deep:#0A3A52;
  --navy:#0A3A52; --navy-800:#0A3A52; --ink:#12303F; --grey:#888888;
  --teal:#00A890; --teal-600:#0A8E7C; --teal-700:#0A7E6E; --teal-800:#0A6357; --teal-100:#D6EFEA;
  --amber:#0A6E9C; --amber-700:#0A6E9C; --amber-100:#E6F3FB; --hl:#86E6D8;
  --cream:#F3F7F9; --mist:#E7F4F1; --sky:#E6F3FB; --slate:#EEF5F9; --line:#D3E4EC;
  --body:#33474F; --muted:#5F7178; --white:#ffffff;
  --maxw:1180px; --radius:16px; --radius-sm:10px;
  --shadow:0 18px 44px -20px rgba(10,58,82,.42); --shadow-sm:0 8px 22px -14px rgba(10,58,82,.4);
  --font-body:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --font-display:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font-body);color:var(--body);background:var(--white);
  font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3,h4{font-family:var(--font-display);color:var(--ink);line-height:1.14;margin:0 0 .5em;font-weight:800;letter-spacing:-.02em}
h2{font-size:clamp(1.7rem,3.6vw,2.5rem)}
h3{font-size:1.26rem;font-weight:700;letter-spacing:-.01em}
p{margin:0 0 1rem}
a{color:var(--teal-700);text-decoration-thickness:1px;text-underline-offset:2px}
a:hover{color:var(--teal-800)}
.vh{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.hero__sub a{color:#fff;text-decoration:underline;text-underline-offset:3px;font-weight:600}
.hero__sub a:hover{color:var(--hl)}
img{max-width:100%;display:block}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 22px}
.section{padding:76px 0}
.section--tight{padding:56px 0}
.eyebrow{display:inline-flex;align-items:center;gap:.5rem;font-weight:700;font-size:.78rem;
  letter-spacing:.14em;text-transform:uppercase;color:var(--teal-700);margin:0 0 .9rem}
.eyebrow::before{content:"";width:26px;height:2px;background:var(--amber);border-radius:2px}
.lead{font-size:1.12rem;color:var(--body);max-width:60ch}
.center{text-align:center}
.center .lead{margin-left:auto;margin-right:auto}

/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.55rem;font-weight:700;
  font-size:1rem;padding:.92rem 1.5rem;border-radius:999px;border:2px solid transparent;cursor:pointer;
  text-decoration:none;transition:transform .15s ease,background .2s ease,box-shadow .2s ease;line-height:1}
.btn:hover{transform:translateY(-2px)}
.btn--primary{background:var(--teal-700);color:#fff;box-shadow:var(--shadow-sm)}
.btn--primary:hover{background:var(--teal-800);color:#fff}
.btn--light{background:var(--cream);color:var(--navy)}
.btn--light:hover{background:#fff;color:var(--navy)}
.btn--ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn--ghost:hover{background:rgba(255,255,255,.12);color:#fff}
.btn--outline{background:transparent;color:var(--teal-700);border-color:var(--teal-700)}
.btn--outline:hover{background:var(--mist);color:var(--teal-800)}

.skip{position:absolute;left:-999px;top:0;background:var(--navy);color:#fff;padding:.7rem 1.1rem;z-index:200;border-radius:0 0 8px 0}
.skip:focus{left:0;color:#fff}

/* Utility bar */
.util{background:var(--navy);color:#cddbe8;font-size:.86rem}
.util .wrap{display:flex;flex-wrap:wrap;gap:.4rem 1.4rem;align-items:center;justify-content:space-between;padding-top:.5rem;padding-bottom:.5rem}
.util a{color:#e7eef6;text-decoration:none}
.util a:hover{color:#fff}
.util .util__group{display:flex;flex-wrap:wrap;gap:.3rem 1.3rem;align-items:center}
.util i{color:var(--hl);margin-right:.4rem}
.util__reg{font-weight:700;color:#fff}

/* Header */
.site-header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.93);backdrop-filter:saturate(1.4) blur(8px);
  border-bottom:1px solid var(--line)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding-top:.55rem;padding-bottom:.55rem}
.brand{display:inline-flex;align-items:center;text-decoration:none}
.brand img{height:56px;width:auto;max-width:210px;object-fit:contain;display:block}
.nav{display:flex;align-items:center;gap:.35rem}
.nav a{color:var(--ink);text-decoration:none;font-weight:600;font-size:.97rem;padding:.5rem .7rem;border-radius:8px}
.nav a:hover{background:var(--mist);color:var(--teal-800)}
.nav__has{position:relative}
.nav__panel{position:absolute;top:calc(100% + 6px);left:0;background:#fff;border:1px solid var(--line);border-radius:12px;
  box-shadow:var(--shadow);padding:.5rem;min-width:255px;display:none;z-index:20}
.nav__has:hover .nav__panel,.nav__has:focus-within .nav__panel{display:block}
.nav__panel a{display:block;padding:.55rem .7rem;font-size:.92rem}
.header__cta{display:flex;align-items:center;gap:.6rem}
.header__phone{display:inline-flex;align-items:center;gap:.45rem;font-weight:700;color:var(--navy);text-decoration:none;font-size:.95rem}
.header__phone i{color:var(--teal-700)}
.burger{display:none;background:var(--mist);border:1px solid var(--line);border-radius:10px;width:46px;height:46px;font-size:1.2rem;color:var(--navy);cursor:pointer}

/* Hero */
.hero{position:relative;color:#e9f3f1;background:linear-gradient(120deg,#0A3A52 0%,#0A6E9C 46%,#00A890 120%);overflow:hidden}
.hero::after{content:"";position:absolute;right:-8%;top:-30%;width:520px;height:520px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,rgba(0,168,144,.30),rgba(0,168,144,0) 62%);pointer-events:none}
.hero .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1.08fr .92fr;gap:48px;align-items:center;padding-top:70px;padding-bottom:78px}
.hero__eyebrow{color:var(--hl)}
.hero h1{color:#fff;font-size:clamp(2.15rem,5vw,3.4rem);font-weight:800;margin-bottom:.4em;letter-spacing:-.025em}
.hero h1 .hl{color:var(--hl)}
.hero__sub{font-size:1.15rem;color:#dcebe8;max-width:52ch;margin-bottom:1.5rem}
.hero__cta{display:flex;flex-wrap:wrap;gap:.8rem;margin-bottom:1.6rem}
.hero__chips{display:flex;flex-wrap:wrap;gap:.5rem}
.chip{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.22);
  border-radius:999px;padding:.42rem .8rem;font-size:.82rem;font-weight:600;color:#eef7f4}
.chip i{color:var(--hl)}

.hero__media{position:relative}
.hero__ph{position:relative;border-radius:22px;overflow:hidden;box-shadow:0 30px 60px -28px rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.2)}
.ph{position:relative;background:
    repeating-linear-gradient(45deg,rgba(255,255,255,.05) 0 12px,rgba(255,255,255,.09) 12px 24px),
    linear-gradient(135deg,#0A78AC,#0A7E6E);
  color:#eafaf6;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:.45rem;padding:22px}
.ph--light{background:
    repeating-linear-gradient(45deg,rgba(11,36,64,.05) 0 12px,rgba(11,36,64,.09) 12px 24px),
    linear-gradient(135deg,#E6F3FB,#E7F4F1);color:var(--teal-800)}
.ph i.ph__ico{font-size:1.9rem;opacity:.9}
.ph__label{font-weight:700;font-size:.82rem;letter-spacing:.08em;text-transform:uppercase}
.ph__meta{font-size:.75rem;opacity:.9;max-width:36ch;line-height:1.4}
.hero__ph .ph{aspect-ratio:4/3}
.matchcard{position:absolute;left:-18px;bottom:-22px;background:#fff;color:var(--ink);border-radius:16px;
  box-shadow:var(--shadow);padding:14px 16px;width:min(300px,78%);border:1px solid var(--line)}
.matchcard .mc-title{font-size:.8rem;text-transform:uppercase;letter-spacing:.1em;color:var(--teal-700);margin:0 0 .55rem;font-weight:800}
.matchcard ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:.5rem}
.matchcard li{display:flex;align-items:center;gap:.5rem;font-size:.86rem;font-weight:600;color:var(--body)}
.matchcard li i{width:26px;height:26px;display:grid;place-items:center;border-radius:8px;background:var(--mist);color:var(--teal-700);font-size:.8rem}

/* Trust bar */
.trustbar{background:var(--cream);border-bottom:1px solid var(--line)}
.trustbar .grid{display:grid;grid-template-columns:repeat(5,1fr);gap:18px}
.trust{display:flex;gap:.7rem;align-items:flex-start}
.trust i{flex:none;width:40px;height:40px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.05rem}
.trust b{display:block;color:var(--ink);font-size:.95rem;line-height:1.25}
.trust span{font-size:.83rem;color:var(--muted)}

/* Services */
.svc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:36px}
.svc{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px;box-shadow:var(--shadow-sm);transition:transform .18s ease,box-shadow .2s ease;overflow:hidden}
.svc::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:linear-gradient(var(--blue),var(--teal))}
.svc:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.svc__ico{width:52px;height:52px;display:grid;place-items:center;border-radius:13px;background:var(--mist);color:var(--teal-700);font-size:1.3rem;margin-bottom:14px}
.svc h3{margin-bottom:.4rem}
.svc p{font-size:.96rem;margin-bottom:1rem}
.svc a.svc__link{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}
.svc a.svc__link i{transition:transform .15s ease}
.svc a.svc__link:hover i{transform:translateX(3px)}
.svc-more{margin-top:22px;display:flex;flex-wrap:wrap;gap:.6rem 1.1rem;align-items:center;font-size:.95rem}
.svc-more span{font-weight:700;color:var(--ink)}
.callout{margin-top:26px;display:flex;gap:18px;align-items:center;flex-wrap:wrap;justify-content:space-between;
  background:linear-gradient(120deg,#0A3A52,#0A7E6E);color:#e9f3f1;border-radius:var(--radius);padding:24px 26px;
  border:1px solid rgba(255,255,255,.14);box-shadow:var(--shadow-sm);position:relative;overflow:hidden}
.callout::after{content:"";position:absolute;right:-40px;top:-40px;width:180px;height:180px;border-radius:50%;
  background:radial-gradient(circle,rgba(0,168,144,.32),transparent 65%)}
.callout .callout__t{position:relative;z-index:2;max-width:64ch}
.callout h3{color:#fff;margin-bottom:.25rem}
.callout p{margin:0;color:#d7e6e2;font-size:.96rem}
.callout .btn{position:relative;z-index:2}

/* Matching */
.matching{background:var(--navy);color:#e3eef1;position:relative;overflow:hidden}
.matching::before{content:"";position:absolute;inset:0;background:radial-gradient(1000px 420px at 82% -10%,rgba(0,168,144,.34),transparent 60%);pointer-events:none}
.matching .wrap{position:relative;z-index:2;display:grid;grid-template-columns:.95fr 1.05fr;gap:46px;align-items:center}
.matching h2{color:#fff}
.matching .eyebrow{color:var(--hl)}
.matching .lead{color:#c6d7db}
.match-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.match{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:14px;padding:18px}
.match i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:rgba(134,230,216,.16);color:var(--hl);font-size:1.1rem;margin-bottom:10px}
.match b{display:block;color:#fff;font-size:1rem;margin-bottom:.2rem}
.match span{font-size:.88rem;color:#bfd3d7}

/* Steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:40px;counter-reset:step}
.step{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px 22px;box-shadow:var(--shadow-sm)}
.step__n{counter-increment:step;width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:var(--amber-100);color:var(--amber-700);font-size:1.3rem;font-weight:800;margin-bottom:14px}
.step__n::before{content:counter(step)}
.step h3{font-size:1.1rem;margin-bottom:.35rem}
.step p{font-size:.92rem;margin:0}
.pill-note{margin-top:26px;display:inline-flex;align-items:center;gap:.6rem;background:var(--mist);border:1px solid var(--line);border-radius:999px;padding:.6rem 1.1rem;font-weight:600;color:var(--teal-800);font-size:.95rem}
.pill-note i{color:var(--teal-700)}

/* Coverage */
.coverage{background:var(--slate)}
.cov-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:34px}
.cov{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:28px;box-shadow:var(--shadow-sm)}
.cov__head{display:flex;align-items:center;gap:.7rem;margin-bottom:.4rem}
.cov__head i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.1rem}
.cov__head h3{margin:0}
.cov__head span{font-size:.82rem;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.08em}
.cov ul{list-style:none;padding:0;margin:.7rem 0 1rem;display:flex;flex-wrap:wrap;gap:.5rem}
.cov li{background:var(--mist);border:1px solid var(--line);border-radius:999px;font-size:.85rem;font-weight:600;color:var(--teal-800);overflow:hidden;transition:background .15s ease,border-color .15s ease}
.cov li:hover{background:var(--teal-100);border-color:var(--teal-700)}
.cov li a{display:block;padding:.32rem .75rem;color:var(--teal-800);text-decoration:none}
.cov a{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}

/* Reviews */
.rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:34px}
.rev{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm);position:relative}
.rev .quo{font-size:1.6rem;color:var(--teal);opacity:.5}
.rev p{color:var(--muted);font-size:.95rem;font-style:italic}
.rev .rev__ph{display:flex;align-items:center;gap:.7rem;margin-top:14px;border-top:1px dashed var(--line);padding-top:14px}
.rev .rev__av{width:42px;height:42px;border-radius:50%;background:var(--mist);display:grid;place-items:center;color:var(--teal-700)}
.rev .rev__meta b{display:block;color:var(--ink);font-size:.9rem}
.rev .rev__meta span{font-size:.78rem;color:var(--muted)}
.rev-note{margin-top:22px;text-align:center;font-size:.92rem;color:var(--muted)}

/* Why */
.why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:36px}
.why{display:flex;gap:.9rem;align-items:flex-start;background:var(--cream);border:1px solid var(--line);border-radius:14px;padding:22px}
.why i{flex:none;width:46px;height:46px;display:grid;place-items:center;border-radius:12px;background:var(--teal-700);color:#fff;font-size:1.1rem}
.why b{display:block;color:var(--ink);font-size:1.02rem;margin-bottom:.2rem}
.why span{font-size:.9rem;color:var(--muted)}

/* FAQ */
.faq{max-width:820px;margin:34px auto 0}
.qa{border:1px solid var(--line);border-radius:12px;margin-bottom:12px;background:#fff;overflow:hidden}
.qa__q{width:100%;text-align:left;background:none;border:0;padding:18px 20px;font-family:var(--font-body);font-weight:700;font-size:1.03rem;color:var(--ink);display:flex;justify-content:space-between;align-items:center;gap:1rem;cursor:pointer}
.qa__q i{color:var(--teal-700);transition:transform .2s ease;flex:none}
.qa__q[aria-expanded="true"] i{transform:rotate(45deg)}
.qa__a{padding:0 20px;max-height:0;overflow:hidden;transition:max-height .25s ease,padding .25s ease}
.qa__a p{margin:0 0 16px}
.qa__q[aria-expanded="true"]+.qa__a{padding:2px 20px 4px}

/* CTA + form */
.cta{background:linear-gradient(135deg,#0A3A52 0%,#0A6E9C 50%,#00A890 130%);color:#e9f3f1;position:relative;overflow:hidden}
.cta::after{content:"";position:absolute;left:-6%;bottom:-40%;width:460px;height:460px;border-radius:50%;background:radial-gradient(circle,rgba(0,168,144,.24),transparent 62%);pointer-events:none}
.cta .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
.cta h2{color:#fff}
.cta .eyebrow{color:var(--hl)}
.cta__points{list-style:none;padding:0;margin:1.2rem 0 0;display:grid;gap:.6rem}
.cta__points li{display:flex;gap:.6rem;align-items:flex-start;color:#d7e6e2;font-size:.98rem}
.cta__points i{color:var(--hl);margin-top:.2rem}
.cta__calls{display:flex;flex-wrap:wrap;gap:.7rem;margin-top:1.4rem}
.callbtn{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.24);color:#fff;text-decoration:none;border-radius:12px;padding:.7rem 1rem;font-weight:700;font-size:.95rem}
.callbtn i{color:var(--hl)}
.callbtn:hover{background:rgba(255,255,255,.18);color:#fff}
.form{background:#fff;border-radius:20px;padding:26px;box-shadow:var(--shadow);color:var(--body)}
.form h3{color:var(--ink)}
.form .fnote{font-size:.86rem;color:var(--muted);margin-bottom:1.1rem}
.field{margin-bottom:14px}
.field label{display:block;font-weight:700;font-size:.88rem;color:var(--ink);margin-bottom:.35rem}
.field input,.field select,.field textarea{width:100%;padding:.72rem .85rem;border:1.5px solid var(--line);border-radius:10px;font-family:inherit;font-size:.97rem;color:var(--ink);background:#fff}
.field input:focus,.field select:focus,.field textarea:focus{outline:3px solid rgba(14,159,142,.30);border-color:var(--teal-700)}
.field textarea{min-height:92px;resize:vertical}
.field .req{color:#b23b3b}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.form .consent{font-size:.8rem;color:var(--muted);margin:.4rem 0 1rem}
.form__msg{display:none;background:var(--sky);border:1px solid var(--blue);color:var(--deep);border-radius:10px;padding:.8rem 1rem;font-size:.9rem;font-weight:600;margin-bottom:1rem}
.form__msg.show{display:block}

/* Footer */
.footer{background:var(--navy);color:#c4d3df;font-size:.94rem}
.footer a{color:#dbe6f0;text-decoration:none}
.footer a:hover{color:#fff}
.footer__top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.2fr;gap:34px;padding:58px 0 34px}
.footer__logo{display:inline-block;background:#fff;border-radius:12px;padding:10px 14px;margin-bottom:1rem}
.footer__logo img{height:44px;width:auto;max-width:170px;object-fit:contain;display:block}
.footer p{color:#b6c7d4;font-size:.92rem}
.footer h4{color:#fff;font-size:.82rem;letter-spacing:.12em;text-transform:uppercase;margin:0 0 1rem;font-weight:800}
.footer ul{list-style:none;padding:0;margin:0;display:grid;gap:.55rem}
.footer .nap li{display:flex;gap:.6rem;align-items:flex-start;margin-bottom:.55rem}
.footer .nap i{color:var(--hl);width:18px;margin-top:.2rem;flex:none}
.footer__socials{display:flex;gap:.55rem;margin-top:1rem}
.footer__socials a{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:rgba(255,255,255,.08);color:#e7eef6}
.footer__socials a:hover{background:var(--teal-700);color:#fff}
.footer__bottom{border-top:1px solid rgba(255,255,255,.12);padding:18px 0;display:flex;flex-wrap:wrap;gap:.6rem 1.4rem;align-items:center;justify-content:space-between;font-size:.85rem;color:#9fb4c4}
.footer__bottom a{color:#c4d3df}
.footer__legal{display:flex;flex-wrap:wrap;gap:.4rem 1.2rem}

/* Mobile call bar */
.mcall{position:fixed;left:0;right:0;bottom:0;z-index:90;display:none;grid-template-columns:1fr 1fr;background:#fff;border-top:1px solid var(--line);box-shadow:0 -8px 24px -14px rgba(11,36,64,.5)}
.mcall a{display:flex;align-items:center;justify-content:center;gap:.5rem;padding:.9rem;font-weight:800;text-decoration:none;font-size:.95rem}
.mcall a.call{color:var(--navy)}
.mcall a.enq{background:var(--teal-700);color:#fff}

/* Responsive */
@media (max-width:960px){
  .hero .wrap,.matching .wrap,.cta .wrap{grid-template-columns:1fr;gap:34px}
  .hero__media{max-width:520px}
  .trustbar .grid{grid-template-columns:repeat(2,1fr)}
  .steps{grid-template-columns:1fr 1fr}
  .why-grid,.rev-grid{grid-template-columns:1fr 1fr}
  .footer__top{grid-template-columns:1fr 1fr}
  .nav,.header__phone{display:none}
  .burger{display:inline-flex;align-items:center;justify-content:center}
  .mcall{display:grid}
  body{padding-bottom:56px}
}
@media (max-width:620px){
  .section{padding:56px 0}
  .svc-grid,.match-grid,.cov-grid,.why-grid,.rev-grid,.steps,.trustbar .grid{grid-template-columns:1fr}
  .matchcard{position:static;width:100%;margin-top:14px}
  .util .wrap{justify-content:flex-start}
  .footer__top{grid-template-columns:1fr}
  h2{font-size:1.6rem}
}
.mnav{position:fixed;inset:0;z-index:120;background:rgba(6,18,32,.55);display:none}
.mnav.open{display:block}
.mnav__panel{position:absolute;top:0;right:0;height:100%;width:min(330px,86vw);background:#fff;padding:20px;overflow-y:auto;box-shadow:var(--shadow)}
.mnav__panel a{display:block;padding:.8rem .4rem;border-bottom:1px solid var(--line);color:var(--ink);text-decoration:none;font-weight:700}
.mnav__panel a.sub{padding-left:1.3rem;font-weight:600;font-size:.94rem;color:var(--body)}
.mnav__close{background:var(--mist);border:0;border-radius:10px;width:44px;height:44px;font-size:1.1rem;float:right;margin-bottom:.5rem;cursor:pointer;color:var(--navy)}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}

:root{
  /* Brand palette v5, sampled from the approved logo: blue #0088C0, teal #00A890, grey #888888 */
  --blue:#0088C0; --blue-600:#0A78AC; --blue-700:#0A6E9C; --blue-800:#0A587F; --deep:#0A3A52;
  --navy:#0A3A52; --navy-800:#0A3A52; --ink:#12303F; --grey:#888888;
  --teal:#00A890; --teal-600:#0A8E7C; --teal-700:#0A7E6E; --teal-800:#0A6357; --teal-100:#D6EFEA;
  --amber:#0A6E9C; --amber-700:#0A6E9C; --amber-100:#E6F3FB; --hl:#86E6D8;
  --cream:#F3F7F9; --mist:#E7F4F1; --sky:#E6F3FB; --slate:#EEF5F9; --line:#D3E4EC;
  --body:#33474F; --muted:#5F7178; --white:#ffffff;
  --maxw:1180px; --radius:16px; --radius-sm:10px;
  --shadow:0 18px 44px -20px rgba(10,58,82,.42); --shadow-sm:0 8px 22px -14px rgba(10,58,82,.4);
  --font-body:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --font-display:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font-body);color:var(--body);background:var(--white);
  font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3,h4{font-family:var(--font-display);color:var(--ink);line-height:1.14;margin:0 0 .5em;font-weight:800;letter-spacing:-.02em}
h2{font-size:clamp(1.7rem,3.6vw,2.5rem)}
h3{font-size:1.26rem;font-weight:700;letter-spacing:-.01em}
p{margin:0 0 1rem}
a{color:var(--teal-700);text-decoration-thickness:1px;text-underline-offset:2px}
a:hover{color:var(--teal-800)}
.vh{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.hero__sub a{color:#fff;text-decoration:underline;text-underline-offset:3px;font-weight:600}
.hero__sub a:hover{color:var(--hl)}
img{max-width:100%;display:block}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 22px}
.section{padding:76px 0}
.section--tight{padding:56px 0}
.eyebrow{display:inline-flex;align-items:center;gap:.5rem;font-weight:700;font-size:.78rem;
  letter-spacing:.14em;text-transform:uppercase;color:var(--teal-700);margin:0 0 .9rem}
.eyebrow::before{content:"";width:26px;height:2px;background:var(--amber);border-radius:2px}
.lead{font-size:1.12rem;color:var(--body);max-width:60ch}
.center{text-align:center}
.center .lead{margin-left:auto;margin-right:auto}

/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.55rem;font-weight:700;
  font-size:1rem;padding:.92rem 1.5rem;border-radius:999px;border:2px solid transparent;cursor:pointer;
  text-decoration:none;transition:transform .15s ease,background .2s ease,box-shadow .2s ease;line-height:1}
.btn:hover{transform:translateY(-2px)}
.btn--primary{background:var(--teal-700);color:#fff;box-shadow:var(--shadow-sm)}
.btn--primary:hover{background:var(--teal-800);color:#fff}
.btn--light{background:var(--cream);color:var(--navy)}
.btn--light:hover{background:#fff;color:var(--navy)}
.btn--ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn--ghost:hover{background:rgba(255,255,255,.12);color:#fff}
.btn--outline{background:transparent;color:var(--teal-700);border-color:var(--teal-700)}
.btn--outline:hover{background:var(--mist);color:var(--teal-800)}

.skip{position:absolute;left:-999px;top:0;background:var(--navy);color:#fff;padding:.7rem 1.1rem;z-index:200;border-radius:0 0 8px 0}
.skip:focus{left:0;color:#fff}

/* Utility bar */
.util{background:var(--navy);color:#cddbe8;font-size:.86rem}
.util .wrap{display:flex;flex-wrap:wrap;gap:.4rem 1.4rem;align-items:center;justify-content:space-between;padding-top:.5rem;padding-bottom:.5rem}
.util a{color:#e7eef6;text-decoration:none}
.util a:hover{color:#fff}
.util .util__group{display:flex;flex-wrap:wrap;gap:.3rem 1.3rem;align-items:center}
.util i{color:var(--hl);margin-right:.4rem}
.util__reg{font-weight:700;color:#fff}

/* Header */
.site-header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.93);backdrop-filter:saturate(1.4) blur(8px);
  border-bottom:1px solid var(--line)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding-top:.55rem;padding-bottom:.55rem}
.brand{display:inline-flex;align-items:center;text-decoration:none}
.brand img{height:56px;width:auto;max-width:210px;object-fit:contain;display:block}
.nav{display:flex;align-items:center;gap:.35rem}
.nav a{color:var(--ink);text-decoration:none;font-weight:600;font-size:.97rem;padding:.5rem .7rem;border-radius:8px}
.nav a:hover{background:var(--mist);color:var(--teal-800)}
.nav__has{position:relative}
.nav__panel{position:absolute;top:calc(100% + 6px);left:0;background:#fff;border:1px solid var(--line);border-radius:12px;
  box-shadow:var(--shadow);padding:.5rem;min-width:255px;display:none;z-index:20}
.nav__has:hover .nav__panel,.nav__has:focus-within .nav__panel{display:block}
.nav__panel a{display:block;padding:.55rem .7rem;font-size:.92rem}
.header__cta{display:flex;align-items:center;gap:.6rem}
.header__phone{display:inline-flex;align-items:center;gap:.45rem;font-weight:700;color:var(--navy);text-decoration:none;font-size:.95rem}
.header__phone i{color:var(--teal-700)}
.burger{display:none;background:var(--mist);border:1px solid var(--line);border-radius:10px;width:46px;height:46px;font-size:1.2rem;color:var(--navy);cursor:pointer}

/* Hero */
.hero{position:relative;color:#e9f3f1;background:linear-gradient(120deg,#0A3A52 0%,#0A6E9C 46%,#00A890 120%);overflow:hidden}
.hero::after{content:"";position:absolute;right:-8%;top:-30%;width:520px;height:520px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,rgba(0,168,144,.30),rgba(0,168,144,0) 62%);pointer-events:none}
.hero .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1.08fr .92fr;gap:48px;align-items:center;padding-top:70px;padding-bottom:78px}
.hero__eyebrow{color:var(--hl)}
.hero h1{color:#fff;font-size:clamp(2.15rem,5vw,3.4rem);font-weight:800;margin-bottom:.4em;letter-spacing:-.025em}
.hero h1 .hl{color:var(--hl)}
.hero__sub{font-size:1.15rem;color:#dcebe8;max-width:52ch;margin-bottom:1.5rem}
.hero__cta{display:flex;flex-wrap:wrap;gap:.8rem;margin-bottom:1.6rem}
.hero__chips{display:flex;flex-wrap:wrap;gap:.5rem}
.chip{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.22);
  border-radius:999px;padding:.42rem .8rem;font-size:.82rem;font-weight:600;color:#eef7f4}
.chip i{color:var(--hl)}

.hero__media{position:relative}
.hero__ph{position:relative;border-radius:22px;overflow:hidden;box-shadow:0 30px 60px -28px rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.2)}
.ph{position:relative;background:
    repeating-linear-gradient(45deg,rgba(255,255,255,.05) 0 12px,rgba(255,255,255,.09) 12px 24px),
    linear-gradient(135deg,#0A78AC,#0A7E6E);
  color:#eafaf6;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:.45rem;padding:22px}
.ph--light{background:
    repeating-linear-gradient(45deg,rgba(11,36,64,.05) 0 12px,rgba(11,36,64,.09) 12px 24px),
    linear-gradient(135deg,#E6F3FB,#E7F4F1);color:var(--teal-800)}
.ph i.ph__ico{font-size:1.9rem;opacity:.9}
.ph__label{font-weight:700;font-size:.82rem;letter-spacing:.08em;text-transform:uppercase}
.ph__meta{font-size:.75rem;opacity:.9;max-width:36ch;line-height:1.4}
.hero__ph .ph{aspect-ratio:4/3}
.matchcard{position:absolute;left:-18px;bottom:-22px;background:#fff;color:var(--ink);border-radius:16px;
  box-shadow:var(--shadow);padding:14px 16px;width:min(300px,78%);border:1px solid var(--line)}
.matchcard .mc-title{font-size:.8rem;text-transform:uppercase;letter-spacing:.1em;color:var(--teal-700);margin:0 0 .55rem;font-weight:800}
.matchcard ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:.5rem}
.matchcard li{display:flex;align-items:center;gap:.5rem;font-size:.86rem;font-weight:600;color:var(--body)}
.matchcard li i{width:26px;height:26px;display:grid;place-items:center;border-radius:8px;background:var(--mist);color:var(--teal-700);font-size:.8rem}

/* Trust bar */
.trustbar{background:var(--cream);border-bottom:1px solid var(--line)}
.trustbar .grid{display:grid;grid-template-columns:repeat(5,1fr);gap:18px}
.trust{display:flex;gap:.7rem;align-items:flex-start}
.trust i{flex:none;width:40px;height:40px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.05rem}
.trust b{display:block;color:var(--ink);font-size:.95rem;line-height:1.25}
.trust span{font-size:.83rem;color:var(--muted)}

/* Services */
.svc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:36px}
.svc{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px;box-shadow:var(--shadow-sm);transition:transform .18s ease,box-shadow .2s ease;overflow:hidden}
.svc::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:linear-gradient(var(--blue),var(--teal))}
.svc:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.svc__ico{width:52px;height:52px;display:grid;place-items:center;border-radius:13px;background:var(--mist);color:var(--teal-700);font-size:1.3rem;margin-bottom:14px}
.svc h3{margin-bottom:.4rem}
.svc p{font-size:.96rem;margin-bottom:1rem}
.svc a.svc__link{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}
.svc a.svc__link i{transition:transform .15s ease}
.svc a.svc__link:hover i{transform:translateX(3px)}
.svc-more{margin-top:22px;display:flex;flex-wrap:wrap;gap:.6rem 1.1rem;align-items:center;font-size:.95rem}
.svc-more span{font-weight:700;color:var(--ink)}
.callout{margin-top:26px;display:flex;gap:18px;align-items:center;flex-wrap:wrap;justify-content:space-between;
  background:linear-gradient(120deg,#0A3A52,#0A7E6E);color:#e9f3f1;border-radius:var(--radius);padding:24px 26px;
  border:1px solid rgba(255,255,255,.14);box-shadow:var(--shadow-sm);position:relative;overflow:hidden}
.callout::after{content:"";position:absolute;right:-40px;top:-40px;width:180px;height:180px;border-radius:50%;
  background:radial-gradient(circle,rgba(0,168,144,.32),transparent 65%)}
.callout .callout__t{position:relative;z-index:2;max-width:64ch}
.callout h3{color:#fff;margin-bottom:.25rem}
.callout p{margin:0;color:#d7e6e2;font-size:.96rem}
.callout .btn{position:relative;z-index:2}

/* Matching */
.matching{background:var(--navy);color:#e3eef1;position:relative;overflow:hidden}
.matching::before{content:"";position:absolute;inset:0;background:radial-gradient(1000px 420px at 82% -10%,rgba(0,168,144,.34),transparent 60%);pointer-events:none}
.matching .wrap{position:relative;z-index:2;display:grid;grid-template-columns:.95fr 1.05fr;gap:46px;align-items:center}
.matching h2{color:#fff}
.matching .eyebrow{color:var(--hl)}
.matching .lead{color:#c6d7db}
.match-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.match{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:14px;padding:18px}
.match i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:rgba(134,230,216,.16);color:var(--hl);font-size:1.1rem;margin-bottom:10px}
.match b{display:block;color:#fff;font-size:1rem;margin-bottom:.2rem}
.match span{font-size:.88rem;color:#bfd3d7}

/* Steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:40px;counter-reset:step}
.step{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px 22px;box-shadow:var(--shadow-sm)}
.step__n{counter-increment:step;width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:var(--amber-100);color:var(--amber-700);font-size:1.3rem;font-weight:800;margin-bottom:14px}
.step__n::before{content:counter(step)}
.step h3{font-size:1.1rem;margin-bottom:.35rem}
.step p{font-size:.92rem;margin:0}
.pill-note{margin-top:26px;display:inline-flex;align-items:center;gap:.6rem;background:var(--mist);border:1px solid var(--line);border-radius:999px;padding:.6rem 1.1rem;font-weight:600;color:var(--teal-800);font-size:.95rem}
.pill-note i{color:var(--teal-700)}

/* Coverage */
.coverage{background:var(--slate)}
.cov-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:34px}
.cov{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:28px;box-shadow:var(--shadow-sm)}
.cov__head{display:flex;align-items:center;gap:.7rem;margin-bottom:.4rem}
.cov__head i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.1rem}
.cov__head h3{margin:0}
.cov__head span{font-size:.82rem;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.08em}
.cov ul{list-style:none;padding:0;margin:.7rem 0 1rem;display:flex;flex-wrap:wrap;gap:.5rem}
.cov li{background:var(--mist);border:1px solid var(--line);border-radius:999px;font-size:.85rem;font-weight:600;color:var(--teal-800);overflow:hidden;transition:background .15s ease,border-color .15s ease}
.cov li:hover{background:var(--teal-100);border-color:var(--teal-700)}
.cov li a{display:block;padding:.32rem .75rem;color:var(--teal-800);text-decoration:none}
.cov a{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}

/* Reviews */
.rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:34px}
.rev{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm);position:relative}
.rev .quo{font-size:1.6rem;color:var(--teal);opacity:.5}
.rev p{color:var(--muted);font-size:.95rem;font-style:italic}
.rev .rev__ph{display:flex;align-items:center;gap:.7rem;margin-top:14px;border-top:1px dashed var(--line);padding-top:14px}
.rev .rev__av{width:42px;height:42px;border-radius:50%;background:var(--mist);display:grid;place-items:center;color:var(--teal-700)}
.rev .rev__meta b{display:block;color:var(--ink);font-size:.9rem}
.rev .rev__meta span{font-size:.78rem;color:var(--muted)}
.rev-note{margin-top:22px;text-align:center;font-size:.92rem;color:var(--muted)}

/* Why */
.why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:36px}
.why{display:flex;gap:.9rem;align-items:flex-start;background:var(--cream);border:1px solid var(--line);border-radius:14px;padding:22px}
.why i{flex:none;width:46px;height:46px;display:grid;place-items:center;border-radius:12px;background:var(--teal-700);color:#fff;font-size:1.1rem}
.why b{display:block;color:var(--ink);font-size:1.02rem;margin-bottom:.2rem}
.why span{font-size:.9rem;color:var(--muted)}

/* FAQ */
.faq{max-width:820px;margin:34px auto 0}
.qa{border:1px solid var(--line);border-radius:12px;margin-bottom:12px;background:#fff;overflow:hidden}
.qa__q{width:100%;text-align:left;background:none;border:0;padding:18px 20px;font-family:var(--font-body);font-weight:700;font-size:1.03rem;color:var(--ink);display:flex;justify-content:space-between;align-items:center;gap:1rem;cursor:pointer}
.qa__q i{color:var(--teal-700);transition:transform .2s ease;flex:none}
.qa__q[aria-expanded="true"] i{transform:rotate(45deg)}
.qa__a{padding:0 20px;max-height:0;overflow:hidden;transition:max-height .25s ease,padding .25s ease}
.qa__a p{margin:0 0 16px}
.qa__q[aria-expanded="true"]+.qa__a{padding:2px 20px 4px}

/* CTA + form */
.cta{background:linear-gradient(135deg,#0A3A52 0%,#0A6E9C 50%,#00A890 130%);color:#e9f3f1;position:relative;overflow:hidden}
.cta::after{content:"";position:absolute;left:-6%;bottom:-40%;width:460px;height:460px;border-radius:50%;background:radial-gradient(circle,rgba(0,168,144,.24),transparent 62%);pointer-events:none}
.cta .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
.cta h2{color:#fff}
.cta .eyebrow{color:var(--hl)}
.cta__points{list-style:none;padding:0;margin:1.2rem 0 0;display:grid;gap:.6rem}
.cta__points li{display:flex;gap:.6rem;align-items:flex-start;color:#d7e6e2;font-size:.98rem}
.cta__points i{color:var(--hl);margin-top:.2rem}
.cta__calls{display:flex;flex-wrap:wrap;gap:.7rem;margin-top:1.4rem}
.callbtn{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.24);color:#fff;text-decoration:none;border-radius:12px;padding:.7rem 1rem;font-weight:700;font-size:.95rem}
.callbtn i{color:var(--hl)}
.callbtn:hover{background:rgba(255,255,255,.18);color:#fff}
.form{background:#fff;border-radius:20px;padding:26px;box-shadow:var(--shadow);color:var(--body)}
.form h3{color:var(--ink)}
.form .fnote{font-size:.86rem;color:var(--muted);margin-bottom:1.1rem}
.field{margin-bottom:14px}
.field label{display:block;font-weight:700;font-size:.88rem;color:var(--ink);margin-bottom:.35rem}
.field input,.field select,.field textarea{width:100%;padding:.72rem .85rem;border:1.5px solid var(--line);border-radius:10px;font-family:inherit;font-size:.97rem;color:var(--ink);background:#fff}
.field input:focus,.field select:focus,.field textarea:focus{outline:3px solid rgba(14,159,142,.30);border-color:var(--teal-700)}
.field textarea{min-height:92px;resize:vertical}
.field .req{color:#b23b3b}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.form .consent{font-size:.8rem;color:var(--muted);margin:.4rem 0 1rem}
.form__msg{display:none;background:var(--sky);border:1px solid var(--blue);color:var(--deep);border-radius:10px;padding:.8rem 1rem;font-size:.9rem;font-weight:600;margin-bottom:1rem}
.form__msg.show{display:block}

/* Footer */
.footer{background:var(--navy);color:#c4d3df;font-size:.94rem}
.footer a{color:#dbe6f0;text-decoration:none}
.footer a:hover{color:#fff}
.footer__top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.2fr;gap:34px;padding:58px 0 34px}
.footer__logo{display:inline-block;background:#fff;border-radius:12px;padding:10px 14px;margin-bottom:1rem}
.footer__logo img{height:44px;width:auto;max-width:170px;object-fit:contain;display:block}
.footer p{color:#b6c7d4;font-size:.92rem}
.footer h4{color:#fff;font-size:.82rem;letter-spacing:.12em;text-transform:uppercase;margin:0 0 1rem;font-weight:800}
.footer ul{list-style:none;padding:0;margin:0;display:grid;gap:.55rem}
.footer .nap li{display:flex;gap:.6rem;align-items:flex-start;margin-bottom:.55rem}
.footer .nap i{color:var(--hl);width:18px;margin-top:.2rem;flex:none}
.footer__socials{display:flex;gap:.55rem;margin-top:1rem}
.footer__socials a{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:rgba(255,255,255,.08);color:#e7eef6}
.footer__socials a:hover{background:var(--teal-700);color:#fff}
.footer__bottom{border-top:1px solid rgba(255,255,255,.12);padding:18px 0;display:flex;flex-wrap:wrap;gap:.6rem 1.4rem;align-items:center;justify-content:space-between;font-size:.85rem;color:#9fb4c4}
.footer__bottom a{color:#c4d3df}
.footer__legal{display:flex;flex-wrap:wrap;gap:.4rem 1.2rem}

/* Mobile call bar */
.mcall{position:fixed;left:0;right:0;bottom:0;z-index:90;display:none;grid-template-columns:1fr 1fr;background:#fff;border-top:1px solid var(--line);box-shadow:0 -8px 24px -14px rgba(11,36,64,.5)}
.mcall a{display:flex;align-items:center;justify-content:center;gap:.5rem;padding:.9rem;font-weight:800;text-decoration:none;font-size:.95rem}
.mcall a.call{color:var(--navy)}
.mcall a.enq{background:var(--teal-700);color:#fff}

/* Responsive */
@media (max-width:960px){
  .hero .wrap,.matching .wrap,.cta .wrap{grid-template-columns:1fr;gap:34px}
  .hero__media{max-width:520px}
  .trustbar .grid{grid-template-columns:repeat(2,1fr)}
  .steps{grid-template-columns:1fr 1fr}
  .why-grid,.rev-grid{grid-template-columns:1fr 1fr}
  .footer__top{grid-template-columns:1fr 1fr}
  .nav,.header__phone{display:none}
  .burger{display:inline-flex;align-items:center;justify-content:center}
  .mcall{display:grid}
  body{padding-bottom:56px}
}
@media (max-width:620px){
  .section{padding:56px 0}
  .svc-grid,.match-grid,.cov-grid,.why-grid,.rev-grid,.steps,.trustbar .grid{grid-template-columns:1fr}
  .matchcard{position:static;width:100%;margin-top:14px}
  .util .wrap{justify-content:flex-start}
  .footer__top{grid-template-columns:1fr}
  h2{font-size:1.6rem}
}
.mnav{position:fixed;inset:0;z-index:120;background:rgba(6,18,32,.55);display:none}
.mnav.open{display:block}
.mnav__panel{position:absolute;top:0;right:0;height:100%;width:min(330px,86vw);background:#fff;padding:20px;overflow-y:auto;box-shadow:var(--shadow)}
.mnav__panel a{display:block;padding:.8rem .4rem;border-bottom:1px solid var(--line);color:var(--ink);text-decoration:none;font-weight:700}
.mnav__panel a.sub{padding-left:1.3rem;font-weight:600;font-size:.94rem;color:var(--body)}
.mnav__close{background:var(--mist);border:0;border-radius:10px;width:44px;height:44px;font-size:1.1rem;float:right;margin-bottom:.5rem;cursor:pointer;color:var(--navy)}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}

:root{
  --blue:#0088C0;
  --teal:#00A890;
  --grey:#888888;
  --deep:#0A3A52;
  --deep-2:#072a3d;
  --ink:#123040;
  --body:#33474f;
  --line:#dbe6ec;
  --tint-blue:#eef6fb;
  --tint-teal:#e8f7f2;
  --white:#ffffff;
  --grad:linear-gradient(135deg,var(--blue) 0%,var(--teal) 100%);
  --radius:14px;
  --shadow:0 10px 30px rgba(10,58,82,.10);
  --shadow-sm:0 4px 14px rgba(10,58,82,.08);
  --wrap:1160px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:var(--body);line-height:1.65;background:var(--white);font-size:17px}
h1,h2,h3,h4{color:var(--ink);line-height:1.2;font-weight:800;margin:0 0 .5em}
h1{font-size:clamp(2rem,4.4vw,3.15rem);letter-spacing:-.5px}
h2{font-size:clamp(1.6rem,3vw,2.3rem);letter-spacing:-.3px}
h3{font-size:1.2rem}
p{margin:0 0 1rem}
a{color:var(--deep);text-decoration:underline;text-underline-offset:3px}
a:hover{color:var(--blue)}
img{max-width:100%;display:block}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.section{padding:76px 0}
.eyebrow{display:inline-flex;align-items:center;gap:8px;font-weight:800;letter-spacing:1.4px;text-transform:uppercase;font-size:.76rem;color:var(--teal);margin:0 0 14px}
.eyebrow i{color:var(--teal)}
.lead{font-size:1.12rem}
.center{text-align:center}
.center .eyebrow{color:var(--teal)}
.skip{position:absolute;left:-999px;top:0;background:var(--deep);color:#fff;padding:12px 18px;border-radius:0 0 8px 0;z-index:200}
.skip:focus{left:0}

/* Buttons */
.btn{display:inline-flex;align-items:center;gap:10px;font-weight:800;font-size:1rem;padding:15px 26px;border-radius:10px;text-decoration:none;border:2px solid transparent;cursor:pointer;transition:transform .15s ease,box-shadow .15s ease,background .15s ease}
.btn:hover{transform:translateY(-2px)}
.btn-primary{background:var(--deep);color:#fff}
.btn-primary:hover{background:var(--deep-2);color:#fff;box-shadow:var(--shadow)}
.btn-ghost{background:transparent;color:var(--deep);border-color:var(--deep)}
.btn-ghost:hover{background:var(--deep);color:#fff}
.btn-white{background:#fff;color:var(--deep)}
.btn-white:hover{background:#eef6fb;color:var(--deep-2)}
.btn-outline-white{background:transparent;color:#fff;border-color:rgba(255,255,255,.75)}
.btn-outline-white:hover{background:#fff;color:var(--deep)}

/* Utility bar */
.util{background:var(--deep);color:#dcecf4;font-size:.86rem}
.util .wrap{display:flex;justify-content:space-between;align-items:center;gap:14px;padding-top:9px;padding-bottom:9px;flex-wrap:wrap}
.util a{color:#fff;text-decoration:none}
.util .util-items{display:flex;gap:20px;flex-wrap:wrap}
.util .util-items span{display:inline-flex;align-items:center;gap:8px}
.util i{color:var(--teal)}

/* Header */
.site-header{position:sticky;top:0;z-index:120;background:#fff;border-bottom:1px solid var(--line);box-shadow:0 2px 10px rgba(10,58,82,.05)}
.hbar{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:12px 0}
.brand{display:flex;align-items:center}
.brand img{height:56px;width:auto}
.nav{display:flex;align-items:center;gap:26px}
.nav a{color:var(--ink);text-decoration:none;font-weight:700;font-size:.98rem}
.nav a:hover{color:var(--blue)}
.has-drop{position:relative}
.drop{position:absolute;top:130%;left:50%;transform:translateX(-50%);background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow);padding:10px;min-width:250px;opacity:0;visibility:hidden;transition:.15s}
.has-drop:hover .drop,.has-drop:focus-within .drop{opacity:1;visibility:visible;top:118%}
.drop a{display:block;padding:9px 12px;border-radius:8px;font-size:.94rem}
.drop a:hover{background:var(--tint-blue)}
.header-cta{display:flex;align-items:center;gap:14px}
.phone-pill{display:inline-flex;align-items:center;gap:9px;background:var(--tint-blue);color:var(--deep);font-weight:800;padding:11px 17px;border-radius:10px;text-decoration:none;white-space:nowrap}
.phone-pill i{color:var(--teal)}
.phone-pill:hover{background:#e2f0f8;color:var(--deep)}
.burger{display:none;background:var(--deep);color:#fff;border:0;width:46px;height:46px;border-radius:10px;font-size:1.2rem;cursor:pointer}

/* Hero */
.hero{background:radial-gradient(circle at 12% 0%,rgba(0,168,144,.10),transparent 45%),radial-gradient(circle at 92% 30%,rgba(0,136,192,.12),transparent 40%),var(--tint-blue);border-bottom:1px solid var(--line)}
.hero .wrap{display:grid;grid-template-columns:1.05fr .95fr;gap:46px;align-items:center;padding-top:64px;padding-bottom:64px}
.hero h1 span{color:var(--blue)}
.hero p.lead{color:var(--body);max-width:36em}
.trust-chips{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0 26px}
.chip{display:inline-flex;align-items:center;gap:9px;background:#fff;border:1px solid var(--line);border-radius:40px;padding:9px 15px;font-weight:700;font-size:.86rem;color:var(--ink);box-shadow:var(--shadow-sm)}
.chip i{color:var(--teal)}
.hero-actions{display:flex;flex-wrap:wrap;gap:14px}

/* Enquiry card */
.enquiry{background:#fff;border-radius:18px;box-shadow:var(--shadow);border:1px solid var(--line);overflow:hidden}
.enquiry .eh{background:var(--grad);color:#fff;padding:20px 24px}
.enquiry .eh h2{color:#fff;font-size:1.3rem;margin:0}
.enquiry .eh p{margin:.25rem 0 0;color:#eaffff;font-size:.92rem}
.enquiry form{padding:22px 24px 24px}
.field{margin-bottom:14px}
.field label{display:block;font-weight:700;color:var(--ink);font-size:.9rem;margin-bottom:6px}
.field .req{color:#c0392b}
.field input,.field select,.field textarea{width:100%;padding:12px 13px;border:1.5px solid var(--line);border-radius:9px;font:inherit;font-size:.96rem;color:var(--ink);background:#fff}
.field input:focus,.field select:focus,.field textarea:focus{outline:3px solid rgba(0,136,192,.35);border-color:var(--blue)}
.enquiry .btn{width:100%;justify-content:center}
.form-note{font-size:.8rem;color:var(--grey);margin:12px 0 0;text-align:center}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.form-status{display:none;margin-top:14px;padding:12px 14px;border-radius:9px;font-weight:700;font-size:.92rem}
.form-status.show{display:block}
.form-status.ok{background:var(--tint-teal);color:#0a6b57;border:1px solid #bfe9dd}
.form-status.err{background:#fdecea;color:#a12a1d;border:1px solid #f5c6c0}

/* Trust bar */
.trustbar{background:var(--deep);color:#eaf4f9}
.trustbar .wrap{display:grid;grid-template-columns:repeat(5,1fr);gap:20px;padding:34px 22px}
.tb{display:flex;gap:12px;align-items:flex-start}
.tb i{color:var(--teal);font-size:1.3rem;margin-top:3px;width:26px;text-align:center}
.tb b{color:#fff;display:block;font-size:.98rem}
.tb span{font-size:.84rem;color:#c4dae5}

/* Split blocks */
.split{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:center}
.split.alt{background:var(--tint-teal)}
.media{border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow)}

/* Image placeholder */
.imgph{position:relative;background:linear-gradient(135deg,#d7ebf5,#dff3ee);border:2px dashed #9cc4d6;border-radius:var(--radius);min-height:300px;display:flex;align-items:center;justify-content:center;color:#3d6b80;text-align:center;padding:22px}
.imgph .ic{font-size:2rem;color:var(--blue);margin-bottom:8px}
.imgph .lbl{display:none}
body.review .imgph .lbl{display:block;font-size:.8rem;line-height:1.5;color:#33586c}
body.review .imgph .lbl b{display:block;color:var(--deep);font-size:.9rem;margin-bottom:4px;letter-spacing:.5px}

/* Services */
.svc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:22px;margin-top:34px}
.svc{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px;box-shadow:var(--shadow-sm);transition:transform .15s ease,box-shadow .15s ease;display:flex;flex-direction:column}
.svc:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.svc .si{width:52px;height:52px;border-radius:12px;background:var(--grad);color:#fff;display:flex;align-items:center;justify-content:center;font-size:1.35rem;margin-bottom:14px}
.svc h3{margin-bottom:8px}
.svc p{font-size:.98rem}
.svc .more{margin-top:auto;font-weight:800;text-decoration:none;color:var(--deep);display:inline-flex;align-items:center;gap:8px}
.svc .more i{transition:transform .15s ease}
.svc:hover .more i{transform:translateX(4px)}

/* Match band */
.match{background:var(--deep);color:#eaf4f9;position:relative;overflow:hidden}
.match:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 85% 15%,rgba(0,168,144,.22),transparent 45%);pointer-events:none}
.match h2{color:#fff}
.match .lead{color:#cfe3ec;max-width:44em}
.match a{color:#7fe3cf}
.match-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:32px}
.mtile{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:12px;padding:22px}
.mtile i{font-size:1.5rem;color:var(--teal);margin-bottom:10px}
.mtile b{color:#fff;display:block;margin-bottom:4px}
.mtile span{font-size:.86rem;color:#c4dae5}

/* Coverage */
.coverage{background:var(--tint-blue)}
.chips{display:flex;flex-wrap:wrap;gap:12px;margin-top:8px}
.area{display:inline-flex;align-items:center;gap:9px;background:#fff;border:1px solid var(--line);border-radius:40px;padding:11px 18px;font-weight:700;text-decoration:none;color:var(--ink);box-shadow:var(--shadow-sm)}
.area:hover{border-color:var(--blue);color:var(--blue)}
.area i{color:var(--teal)}
.area.here{background:var(--deep);color:#fff;border-color:var(--deep)}
.area.here i{color:#fff}

/* Steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;margin-top:36px}
.step{text-align:center;padding:10px}
.step .num{width:58px;height:58px;margin:0 auto 14px;border-radius:50%;background:var(--grad);color:#fff;display:flex;align-items:center;justify-content:center;font-size:1.35rem;font-weight:800}
.step h3{font-size:1.05rem;margin-bottom:6px}
.step p{font-size:.92rem}

/* Why grid */
.why-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px 26px}
.why{display:flex;gap:14px;align-items:flex-start;background:#fff;border:1px solid var(--line);border-radius:12px;padding:18px 20px;box-shadow:var(--shadow-sm)}
.why i{color:var(--teal);font-size:1.25rem;margin-top:3px;width:26px;text-align:center}
.why b{color:var(--ink);display:block;margin-bottom:3px}
.why span{font-size:.92rem}

/* Reviews */
.rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:34px}
.rev{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px;box-shadow:var(--shadow-sm)}
.rev .stars{color:var(--grey);margin-bottom:10px;font-size:.9rem;letter-spacing:2px}
.rev p{font-style:italic;color:var(--body)}
.rev .who{font-weight:800;color:var(--ink);font-style:normal;font-size:.92rem;margin-top:10px}
.rev .who span{display:block;font-weight:600;color:var(--grey);font-size:.82rem}
.rev.ph{background:var(--tint-blue);border-style:dashed;border-color:#9cc4d6}
.rev.ph .plc{display:none}
body.review .rev.ph .plc{display:block;font-size:.82rem;color:#33586c}
body.review .rev.ph .plc b{color:var(--deep)}

/* FAQ */
.faq{max-width:860px;margin:34px auto 0}
.qa{background:#fff;border:1px solid var(--line);border-radius:12px;margin-bottom:14px;overflow:hidden;box-shadow:var(--shadow-sm)}
.qa button{width:100%;text-align:left;background:#fff;border:0;padding:20px 22px;font:inherit;font-weight:800;color:var(--ink);font-size:1.03rem;display:flex;justify-content:space-between;align-items:center;gap:16px;cursor:pointer}
.qa button:hover{color:var(--blue)}
.qa button i{color:var(--teal);transition:transform .2s ease;flex-shrink:0}
.qa button[aria-expanded="true"] i{transform:rotate(45deg)}
.qa .ans{padding:0 22px;max-height:0;overflow:hidden;transition:max-height .25s ease}
.qa .ans p{padding:0 0 20px}
.qa .ans p:first-child{padding-top:2px}

/* CTA */
.cta{background:var(--grad);color:#fff;text-align:center}
.cta h2{color:#fff}
.cta p{color:#eafbff;max-width:40em;margin-left:auto;margin-right:auto}
.cta-actions{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-top:24px}

/* Footer */
.footer{background:#fff;border-top:1px solid var(--line);padding:60px 0 0}
.foot-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1.2fr;gap:34px}
.footer img.flogo{height:54px;margin-bottom:14px}
.footer h4{color:var(--deep);font-size:1rem;letter-spacing:.4px;margin-bottom:14px}
.footer a{color:var(--body);text-decoration:none}
.footer a:hover{color:var(--blue);text-decoration:underline}
.footer ul{list-style:none;padding:0;margin:0}
.footer ul li{margin-bottom:9px;font-size:.95rem}
.fcontact li{display:flex;gap:11px;align-items:flex-start;margin-bottom:12px}
.fcontact i{color:var(--teal);margin-top:4px;width:18px;text-align:center}
.fcontact b{color:var(--ink)}
.socials{display:flex;gap:10px;margin-top:16px;flex-wrap:wrap}
.socials a{width:42px;height:42px;border-radius:10px;background:var(--tint-blue);color:var(--deep);display:flex;align-items:center;justify-content:center;font-size:1.05rem}
.socials a:hover{background:var(--deep);color:#fff}
.foot-bottom{border-top:1px solid var(--line);margin-top:44px;padding:22px 0;font-size:.86rem;color:var(--grey)}
.foot-bottom .wrap{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}
.foot-bottom a{color:var(--grey)}
.foot-legal{display:flex;gap:18px;flex-wrap:wrap}

@media (max-width:940px){
  .hero .wrap{grid-template-columns:1fr;gap:34px}
  .trustbar .wrap{grid-template-columns:repeat(2,1fr)}
  .split{grid-template-columns:1fr;gap:28px}
  .svc-grid,.match-grid,.steps,.why-grid,.rev-grid{grid-template-columns:1fr 1fr}
  .foot-grid{grid-template-columns:1fr 1fr}
  .nav,.header-cta .phone-pill{display:none}
  .burger{display:inline-flex}
  .nav.open{display:flex;position:absolute;top:100%;left:0;right:0;flex-direction:column;background:#fff;border-bottom:1px solid var(--line);padding:16px 22px;gap:6px;box-shadow:var(--shadow)}
  .nav.open a{padding:10px 0;width:100%;border-bottom:1px solid var(--line)}
  .nav.open .drop{position:static;transform:none;opacity:1;visibility:visible;box-shadow:none;border:0;padding:0 0 0 14px;min-width:0}
}
@media (max-width:600px){
  .section{padding:54px 0}
  .svc-grid,.match-grid,.steps,.why-grid,.rev-grid,.trustbar .wrap,.foot-grid{grid-template-columns:1fr}
  .brand img{height:46px}
  .cta-actions .btn,.hero-actions .btn{width:100%;justify-content:center}
}
@media (prefers-reduced-motion:reduce){*{transition:none !important;scroll-behavior:auto !important}}

:root{
  /* Brand palette v5, sampled from the approved logo: blue #0088C0, teal #00A890, grey #888888 */
  --blue:#0088C0; --blue-600:#0A78AC; --blue-700:#0A6E9C; --blue-800:#0A587F; --deep:#0A3A52;
  --navy:#0A3A52; --navy-800:#0A3A52; --ink:#12303F; --grey:#888888;
  --teal:#00A890; --teal-600:#0A8E7C; --teal-700:#0A7E6E; --teal-800:#0A6357; --teal-100:#D6EFEA;
  --amber:#0A6E9C; --amber-700:#0A6E9C; --amber-100:#E6F3FB; --hl:#86E6D8;
  --cream:#F3F7F9; --mist:#E7F4F1; --sky:#E6F3FB; --slate:#EEF5F9; --line:#D3E4EC;
  --body:#33474F; --muted:#5F7178; --white:#ffffff;
  --maxw:1180px; --radius:16px; --radius-sm:10px;
  --shadow:0 18px 44px -20px rgba(10,58,82,.42); --shadow-sm:0 8px 22px -14px rgba(10,58,82,.4);
  --font-body:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --font-display:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font-body);color:var(--body);background:var(--white);
  font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3,h4{font-family:var(--font-display);color:var(--ink);line-height:1.14;margin:0 0 .5em;font-weight:800;letter-spacing:-.02em}
h2{font-size:clamp(1.7rem,3.6vw,2.5rem)}
h3{font-size:1.26rem;font-weight:700;letter-spacing:-.01em}
p{margin:0 0 1rem}
a{color:var(--teal-700);text-decoration-thickness:1px;text-underline-offset:2px}
a:hover{color:var(--teal-800)}
.vh{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.hero__sub a{color:#fff;text-decoration:underline;text-underline-offset:3px;font-weight:600}
.hero__sub a:hover{color:var(--hl)}
img{max-width:100%;display:block}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 22px}
.section{padding:76px 0}
.section--tight{padding:56px 0}
.eyebrow{display:inline-flex;align-items:center;gap:.5rem;font-weight:700;font-size:.78rem;
  letter-spacing:.14em;text-transform:uppercase;color:var(--teal-700);margin:0 0 .9rem}
.eyebrow::before{content:"";width:26px;height:2px;background:var(--amber);border-radius:2px}
.lead{font-size:1.12rem;color:var(--body);max-width:60ch}
.center{text-align:center}
.center .lead{margin-left:auto;margin-right:auto}

/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.55rem;font-weight:700;
  font-size:1rem;padding:.92rem 1.5rem;border-radius:999px;border:2px solid transparent;cursor:pointer;
  text-decoration:none;transition:transform .15s ease,background .2s ease,box-shadow .2s ease;line-height:1}
.btn:hover{transform:translateY(-2px)}
.btn--primary{background:var(--teal-700);color:#fff;box-shadow:var(--shadow-sm)}
.btn--primary:hover{background:var(--teal-800);color:#fff}
.btn--light{background:var(--cream);color:var(--navy)}
.btn--light:hover{background:#fff;color:var(--navy)}
.btn--ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn--ghost:hover{background:rgba(255,255,255,.12);color:#fff}
.btn--outline{background:transparent;color:var(--teal-700);border-color:var(--teal-700)}
.btn--outline:hover{background:var(--mist);color:var(--teal-800)}

.skip{position:absolute;left:-999px;top:0;background:var(--navy);color:#fff;padding:.7rem 1.1rem;z-index:200;border-radius:0 0 8px 0}
.skip:focus{left:0;color:#fff}

/* Utility bar */
.util{background:var(--navy);color:#cddbe8;font-size:.86rem}
.util .wrap{display:flex;flex-wrap:wrap;gap:.4rem 1.4rem;align-items:center;justify-content:space-between;padding-top:.5rem;padding-bottom:.5rem}
.util a{color:#e7eef6;text-decoration:none}
.util a:hover{color:#fff}
.util .util__group{display:flex;flex-wrap:wrap;gap:.3rem 1.3rem;align-items:center}
.util i{color:var(--hl);margin-right:.4rem}
.util__reg{font-weight:700;color:#fff}

/* Header */
.site-header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.93);backdrop-filter:saturate(1.4) blur(8px);
  border-bottom:1px solid var(--line)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding-top:.55rem;padding-bottom:.55rem}
.brand{display:inline-flex;align-items:center;text-decoration:none}
.brand img{height:56px;width:auto;max-width:210px;object-fit:contain;display:block}
.nav{display:flex;align-items:center;gap:.35rem}
.nav a{color:var(--ink);text-decoration:none;font-weight:600;font-size:.97rem;padding:.5rem .7rem;border-radius:8px}
.nav a:hover{background:var(--mist);color:var(--teal-800)}
.nav__has{position:relative}
.nav__panel{position:absolute;top:calc(100% + 6px);left:0;background:#fff;border:1px solid var(--line);border-radius:12px;
  box-shadow:var(--shadow);padding:.5rem;min-width:255px;display:none;z-index:20}
.nav__has:hover .nav__panel,.nav__has:focus-within .nav__panel{display:block}
.nav__panel a{display:block;padding:.55rem .7rem;font-size:.92rem}
.header__cta{display:flex;align-items:center;gap:.6rem}
.header__phone{display:inline-flex;align-items:center;gap:.45rem;font-weight:700;color:var(--navy);text-decoration:none;font-size:.95rem}
.header__phone i{color:var(--teal-700)}
.burger{display:none;background:var(--mist);border:1px solid var(--line);border-radius:10px;width:46px;height:46px;font-size:1.2rem;color:var(--navy);cursor:pointer}

/* Hero */
.hero{position:relative;color:#e9f3f1;background:linear-gradient(120deg,#0A3A52 0%,#0A6E9C 46%,#00A890 120%);overflow:hidden}
.hero::after{content:"";position:absolute;right:-8%;top:-30%;width:520px;height:520px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,rgba(0,168,144,.30),rgba(0,168,144,0) 62%);pointer-events:none}
.hero .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1.08fr .92fr;gap:48px;align-items:center;padding-top:70px;padding-bottom:78px}
.hero__eyebrow{color:var(--hl)}
.hero h1{color:#fff;font-size:clamp(2.15rem,5vw,3.4rem);font-weight:800;margin-bottom:.4em;letter-spacing:-.025em}
.hero h1 .hl{color:var(--hl)}
.hero__sub{font-size:1.15rem;color:#dcebe8;max-width:52ch;margin-bottom:1.5rem}
.hero__cta{display:flex;flex-wrap:wrap;gap:.8rem;margin-bottom:1.6rem}
.hero__chips{display:flex;flex-wrap:wrap;gap:.5rem}
.chip{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.22);
  border-radius:999px;padding:.42rem .8rem;font-size:.82rem;font-weight:600;color:#eef7f4}
.chip i{color:var(--hl)}

.hero__media{position:relative}
.hero__ph{position:relative;border-radius:22px;overflow:hidden;box-shadow:0 30px 60px -28px rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.2)}
.ph{position:relative;background:
    repeating-linear-gradient(45deg,rgba(255,255,255,.05) 0 12px,rgba(255,255,255,.09) 12px 24px),
    linear-gradient(135deg,#0A78AC,#0A7E6E);
  color:#eafaf6;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:.45rem;padding:22px}
.ph--light{background:
    repeating-linear-gradient(45deg,rgba(11,36,64,.05) 0 12px,rgba(11,36,64,.09) 12px 24px),
    linear-gradient(135deg,#E6F3FB,#E7F4F1);color:var(--teal-800)}
.ph i.ph__ico{font-size:1.9rem;opacity:.9}
.ph__label{font-weight:700;font-size:.82rem;letter-spacing:.08em;text-transform:uppercase}
.ph__meta{font-size:.75rem;opacity:.9;max-width:36ch;line-height:1.4}
.hero__ph .ph{aspect-ratio:4/3}
.matchcard{position:absolute;left:-18px;bottom:-22px;background:#fff;color:var(--ink);border-radius:16px;
  box-shadow:var(--shadow);padding:14px 16px;width:min(300px,78%);border:1px solid var(--line)}
.matchcard .mc-title{font-size:.8rem;text-transform:uppercase;letter-spacing:.1em;color:var(--teal-700);margin:0 0 .55rem;font-weight:800}
.matchcard ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:.5rem}
.matchcard li{display:flex;align-items:center;gap:.5rem;font-size:.86rem;font-weight:600;color:var(--body)}
.matchcard li i{width:26px;height:26px;display:grid;place-items:center;border-radius:8px;background:var(--mist);color:var(--teal-700);font-size:.8rem}

/* Trust bar */
.trustbar{background:var(--cream);border-bottom:1px solid var(--line)}
.trustbar .grid{display:grid;grid-template-columns:repeat(5,1fr);gap:18px}
.trust{display:flex;gap:.7rem;align-items:flex-start}
.trust i{flex:none;width:40px;height:40px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.05rem}
.trust b{display:block;color:var(--ink);font-size:.95rem;line-height:1.25}
.trust span{font-size:.83rem;color:var(--muted)}

/* Services */
.svc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:36px}
.svc{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px;box-shadow:var(--shadow-sm);transition:transform .18s ease,box-shadow .2s ease;overflow:hidden}
.svc::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:linear-gradient(var(--blue),var(--teal))}
.svc:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.svc__ico{width:52px;height:52px;display:grid;place-items:center;border-radius:13px;background:var(--mist);color:var(--teal-700);font-size:1.3rem;margin-bottom:14px}
.svc h3{margin-bottom:.4rem}
.svc p{font-size:.96rem;margin-bottom:1rem}
.svc a.svc__link{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}
.svc a.svc__link i{transition:transform .15s ease}
.svc a.svc__link:hover i{transform:translateX(3px)}
.svc-more{margin-top:22px;display:flex;flex-wrap:wrap;gap:.6rem 1.1rem;align-items:center;font-size:.95rem}
.svc-more span{font-weight:700;color:var(--ink)}
.callout{margin-top:26px;display:flex;gap:18px;align-items:center;flex-wrap:wrap;justify-content:space-between;
  background:linear-gradient(120deg,#0A3A52,#0A7E6E);color:#e9f3f1;border-radius:var(--radius);padding:24px 26px;
  border:1px solid rgba(255,255,255,.14);box-shadow:var(--shadow-sm);position:relative;overflow:hidden}
.callout::after{content:"";position:absolute;right:-40px;top:-40px;width:180px;height:180px;border-radius:50%;
  background:radial-gradient(circle,rgba(0,168,144,.32),transparent 65%)}
.callout .callout__t{position:relative;z-index:2;max-width:64ch}
.callout h3{color:#fff;margin-bottom:.25rem}
.callout p{margin:0;color:#d7e6e2;font-size:.96rem}
.callout .btn{position:relative;z-index:2}

/* Matching */
.matching{background:var(--navy);color:#e3eef1;position:relative;overflow:hidden}
.matching::before{content:"";position:absolute;inset:0;background:radial-gradient(1000px 420px at 82% -10%,rgba(0,168,144,.34),transparent 60%);pointer-events:none}
.matching .wrap{position:relative;z-index:2;display:grid;grid-template-columns:.95fr 1.05fr;gap:46px;align-items:center}
.matching h2{color:#fff}
.matching .eyebrow{color:var(--hl)}
.matching .lead{color:#c6d7db}
.match-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.match{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:14px;padding:18px}
.match i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:rgba(134,230,216,.16);color:var(--hl);font-size:1.1rem;margin-bottom:10px}
.match b{display:block;color:#fff;font-size:1rem;margin-bottom:.2rem}
.match span{font-size:.88rem;color:#bfd3d7}

/* Steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:40px;counter-reset:step}
.step{position:relative;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px 22px;box-shadow:var(--shadow-sm)}
.step__n{counter-increment:step;width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:var(--amber-100);color:var(--amber-700);font-size:1.3rem;font-weight:800;margin-bottom:14px}
.step__n::before{content:counter(step)}
.step h3{font-size:1.1rem;margin-bottom:.35rem}
.step p{font-size:.92rem;margin:0}
.pill-note{margin-top:26px;display:inline-flex;align-items:center;gap:.6rem;background:var(--mist);border:1px solid var(--line);border-radius:999px;padding:.6rem 1.1rem;font-weight:600;color:var(--teal-800);font-size:.95rem}
.pill-note i{color:var(--teal-700)}

/* Coverage */
.coverage{background:var(--slate)}
.cov-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:34px}
.cov{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:28px;box-shadow:var(--shadow-sm)}
.cov__head{display:flex;align-items:center;gap:.7rem;margin-bottom:.4rem}
.cov__head i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:var(--mist);color:var(--teal-700);font-size:1.1rem}
.cov__head h3{margin:0}
.cov__head span{font-size:.82rem;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.08em}
.cov ul{list-style:none;padding:0;margin:.7rem 0 1rem;display:flex;flex-wrap:wrap;gap:.5rem}
.cov li{background:var(--mist);border:1px solid var(--line);border-radius:999px;font-size:.85rem;font-weight:600;color:var(--teal-800);overflow:hidden;transition:background .15s ease,border-color .15s ease}
.cov li:hover{background:var(--teal-100);border-color:var(--teal-700)}
.cov li a{display:block;padding:.32rem .75rem;color:var(--teal-800);text-decoration:none}
.cov a{font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:.4rem}

/* Reviews */
.rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:34px}
.rev{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm);position:relative}
.rev .quo{font-size:1.6rem;color:var(--teal);opacity:.5}
.rev p{color:var(--muted);font-size:.95rem;font-style:italic}
.rev .rev__ph{display:flex;align-items:center;gap:.7rem;margin-top:14px;border-top:1px dashed var(--line);padding-top:14px}
.rev .rev__av{width:42px;height:42px;border-radius:50%;background:var(--mist);display:grid;place-items:center;color:var(--teal-700)}
.rev .rev__meta b{display:block;color:var(--ink);font-size:.9rem}
.rev .rev__meta span{font-size:.78rem;color:var(--muted)}
.rev-note{margin-top:22px;text-align:center;font-size:.92rem;color:var(--muted)}

/* Why */
.why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:36px}
.why{display:flex;gap:.9rem;align-items:flex-start;background:var(--cream);border:1px solid var(--line);border-radius:14px;padding:22px}
.why i{flex:none;width:46px;height:46px;display:grid;place-items:center;border-radius:12px;background:var(--teal-700);color:#fff;font-size:1.1rem}
.why b{display:block;color:var(--ink);font-size:1.02rem;margin-bottom:.2rem}
.why span{font-size:.9rem;color:var(--muted)}

/* FAQ */
.faq{max-width:820px;margin:34px auto 0}
.qa{border:1px solid var(--line);border-radius:12px;margin-bottom:12px;background:#fff;overflow:hidden}
.qa__q{width:100%;text-align:left;background:none;border:0;padding:18px 20px;font-family:var(--font-body);font-weight:700;font-size:1.03rem;color:var(--ink);display:flex;justify-content:space-between;align-items:center;gap:1rem;cursor:pointer}
.qa__q i{color:var(--teal-700);transition:transform .2s ease;flex:none}
.qa__q[aria-expanded="true"] i{transform:rotate(45deg)}
.qa__a{padding:0 20px;max-height:0;overflow:hidden;transition:max-height .25s ease,padding .25s ease}
.qa__a p{margin:0 0 16px}
.qa__q[aria-expanded="true"]+.qa__a{padding:2px 20px 4px}

/* CTA + form */
.cta{background:linear-gradient(135deg,#0A3A52 0%,#0A6E9C 50%,#00A890 130%);color:#e9f3f1;position:relative;overflow:hidden}
.cta::after{content:"";position:absolute;left:-6%;bottom:-40%;width:460px;height:460px;border-radius:50%;background:radial-gradient(circle,rgba(0,168,144,.24),transparent 62%);pointer-events:none}
.cta .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
.cta h2{color:#fff}
.cta .eyebrow{color:var(--hl)}
.cta__points{list-style:none;padding:0;margin:1.2rem 0 0;display:grid;gap:.6rem}
.cta__points li{display:flex;gap:.6rem;align-items:flex-start;color:#d7e6e2;font-size:.98rem}
.cta__points i{color:var(--hl);margin-top:.2rem}
.cta__calls{display:flex;flex-wrap:wrap;gap:.7rem;margin-top:1.4rem}
.callbtn{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.24);color:#fff;text-decoration:none;border-radius:12px;padding:.7rem 1rem;font-weight:700;font-size:.95rem}
.callbtn i{color:var(--hl)}
.callbtn:hover{background:rgba(255,255,255,.18);color:#fff}
.form{background:#fff;border-radius:20px;padding:26px;box-shadow:var(--shadow);color:var(--body)}
.form h3{color:var(--ink)}
.form .fnote{font-size:.86rem;color:var(--muted);margin-bottom:1.1rem}
.field{margin-bottom:14px}
.field label{display:block;font-weight:700;font-size:.88rem;color:var(--ink);margin-bottom:.35rem}
.field input,.field select,.field textarea{width:100%;padding:.72rem .85rem;border:1.5px solid var(--line);border-radius:10px;font-family:inherit;font-size:.97rem;color:var(--ink);background:#fff}
.field input:focus,.field select:focus,.field textarea:focus{outline:3px solid rgba(14,159,142,.30);border-color:var(--teal-700)}
.field textarea{min-height:92px;resize:vertical}
.field .req{color:#b23b3b}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.form .consent{font-size:.8rem;color:var(--muted);margin:.4rem 0 1rem}
.form__msg{display:none;background:var(--sky);border:1px solid var(--blue);color:var(--deep);border-radius:10px;padding:.8rem 1rem;font-size:.9rem;font-weight:600;margin-bottom:1rem}
.form__msg.show{display:block}

/* Footer */
.footer{background:var(--navy);color:#c4d3df;font-size:.94rem}
.footer a{color:#dbe6f0;text-decoration:none}
.footer a:hover{color:#fff}
.footer__top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.2fr;gap:34px;padding:58px 0 34px}
.footer__logo{display:inline-block;background:#fff;border-radius:12px;padding:10px 14px;margin-bottom:1rem}
.footer__logo img{height:44px;width:auto;max-width:170px;object-fit:contain;display:block}
.footer p{color:#b6c7d4;font-size:.92rem}
.footer h4{color:#fff;font-size:.82rem;letter-spacing:.12em;text-transform:uppercase;margin:0 0 1rem;font-weight:800}
.footer ul{list-style:none;padding:0;margin:0;display:grid;gap:.55rem}
.footer .nap li{display:flex;gap:.6rem;align-items:flex-start;margin-bottom:.55rem}
.footer .nap i{color:var(--hl);width:18px;margin-top:.2rem;flex:none}
.footer__socials{display:flex;gap:.55rem;margin-top:1rem}
.footer__socials a{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:rgba(255,255,255,.08);color:#e7eef6}
.footer__socials a:hover{background:var(--teal-700);color:#fff}
.footer__bottom{border-top:1px solid rgba(255,255,255,.12);padding:18px 0;display:flex;flex-wrap:wrap;gap:.6rem 1.4rem;align-items:center;justify-content:space-between;font-size:.85rem;color:#9fb4c4}
.footer__bottom a{color:#c4d3df}
.footer__legal{display:flex;flex-wrap:wrap;gap:.4rem 1.2rem}

/* Mobile call bar */
.mcall{position:fixed;left:0;right:0;bottom:0;z-index:90;display:none;grid-template-columns:1fr 1fr;background:#fff;border-top:1px solid var(--line);box-shadow:0 -8px 24px -14px rgba(11,36,64,.5)}
.mcall a{display:flex;align-items:center;justify-content:center;gap:.5rem;padding:.9rem;font-weight:800;text-decoration:none;font-size:.95rem}
.mcall a.call{color:var(--navy)}
.mcall a.enq{background:var(--teal-700);color:#fff}

/* Dev notes */
.dn-toggle{position:fixed;right:16px;bottom:16px;z-index:130;background:var(--blue-700);color:#fff;border:0;border-radius:999px;padding:.7rem 1.05rem;font-weight:800;font-size:.86rem;cursor:pointer;box-shadow:var(--shadow);display:inline-flex;gap:.5rem;align-items:center}
.dn-panel{position:fixed;top:0;right:0;height:100%;width:min(430px,92vw);background:#0a1f38;color:#dbe7f0;z-index:140;box-shadow:-20px 0 50px -20px rgba(0,0,0,.6);transform:translateX(102%);transition:transform .28s ease;overflow-y:auto;padding:22px 22px 60px}
.dn-panel.open{transform:translateX(0)}
.dn-panel h3{color:#fff;font-size:1.05rem}
.dn-panel h4{color:var(--hl);font-size:.78rem;letter-spacing:.1em;text-transform:uppercase;margin:20px 0 .5rem}
.dn-close{position:absolute;top:14px;right:14px;background:rgba(255,255,255,.1);border:0;color:#fff;width:38px;height:38px;border-radius:10px;cursor:pointer;font-size:1rem}
.dn-panel .note{border-left:4px solid;border-radius:8px;padding:10px 12px;margin-bottom:10px;font-size:.85rem;line-height:1.5;background:rgba(255,255,255,.04)}
.dn-panel .note b{color:#fff}
.note--red{border-color:#e8776f}
.note--yellow{border-color:#e9c85f}
.note--blue{border-color:#68c3e8}
.dn-panel small{color:#9db6c9}
.dn-panel code{background:rgba(255,255,255,.1);padding:.05rem .35rem;border-radius:5px;font-size:.82rem}

/* Production mode: hide review-only labels and notes, keep media containers */
body.production .ph__review{display:none}
body.production .dn-toggle,body.production .dn-panel{display:none!important}

/* Responsive */
@media (max-width:960px){
  .hero .wrap,.matching .wrap,.cta .wrap{grid-template-columns:1fr;gap:34px}
  .hero__media{max-width:520px}
  .trustbar .grid{grid-template-columns:repeat(2,1fr)}
  .steps{grid-template-columns:1fr 1fr}
  .why-grid,.rev-grid{grid-template-columns:1fr 1fr}
  .footer__top{grid-template-columns:1fr 1fr}
  .nav,.header__phone{display:none}
  .burger{display:inline-flex;align-items:center;justify-content:center}
  .mcall{display:grid}
  body{padding-bottom:56px}
  .dn-toggle{bottom:66px}
}
@media (max-width:620px){
  .section{padding:56px 0}
  .svc-grid,.match-grid,.cov-grid,.why-grid,.rev-grid,.steps,.trustbar .grid{grid-template-columns:1fr}
  .matchcard{position:static;width:100%;margin-top:14px}
  .util .wrap{justify-content:flex-start}
  .footer__top{grid-template-columns:1fr}
  h2{font-size:1.6rem}
}
.mnav{position:fixed;inset:0;z-index:120;background:rgba(6,18,32,.55);display:none}
.mnav.open{display:block}
.mnav__panel{position:absolute;top:0;right:0;height:100%;width:min(330px,86vw);background:#fff;padding:20px;overflow-y:auto;box-shadow:var(--shadow)}
.mnav__panel a{display:block;padding:.8rem .4rem;border-bottom:1px solid var(--line);color:var(--ink);text-decoration:none;font-weight:700}
.mnav__panel a.sub{padding-left:1.3rem;font-weight:600;font-size:.94rem;color:var(--body)}
.mnav__close{background:var(--mist);border:0;border-radius:10px;width:44px;height:44px;font-size:1.1rem;float:right;margin-bottom:.5rem;cursor:pointer;color:var(--navy)}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
